<?php

if ( ! defined( 'ABSPATH' ) ) {
    exit;
}

trait ACDC_Kernel_Render_Trait {

  public function render_runtime_state_notice() {
    if ( ! current_user_can( 'manage_options' ) || ! function_exists( 'get_transient' ) ) {
      return;
    }

    $notice = get_transient( 'acdc_of_saas_runtime_notice' );
    if ( empty( $notice['items'] ) || ! is_array( $notice['items'] ) ) {
      return;
    }

    echo '<div class="notice notice-warning is-dismissible"><p><strong>ACDC SAAS OF</strong> — stabilisation automatique appliquée :</p><ul style="margin-left:18px;list-style:disc;">';
    foreach ( $notice['items'] as $item ) {
      echo '<li>' . esc_html( $item ) . '</li>';
    }
    if ( ! empty( $notice['time'] ) ) {
      echo '</ul><p><small>Dernière réparation : ' . esc_html( $notice['time'] ) . '</small></p></div>';
    } else {
      echo '</ul></div>';
    }

    delete_transient( 'acdc_of_saas_runtime_notice' );
  }  public function print_plugin_favicon() {
    if ( ! $this->is_acdc_admin_screen() ) {
      echo '</div>';
      return;
    }

    $favicon_url = $this->get_plugin_logo_url();
    if ( ! $favicon_url ) {
      return;
    }

    $favicon_url = esc_url( add_query_arg( 'ver', ACDC_OF_SAAS_VERSION, $favicon_url ) );

    echo '
<link rel="icon" href="' . $favicon_url . '" sizes="32x32">
';
    echo '<link rel="icon" href="' . $favicon_url . '" sizes="192x192">
';
    echo '<link rel="apple-touch-icon" href="' . $favicon_url . '">
';
    echo '<link rel="shortcut icon" href="' . $favicon_url . '">
';
    echo '<meta name="msapplication-TileImage" content="' . $favicon_url . '">
';
  }  /**
   * ACDC 3.21.11-hotfix4 — Exclure les CSS critiques ACDC du defer LiteSpeed Cache.
   * LiteSpeed Cache respecte data-no-optimize="1" sur les balises link pour ne pas
   * différer le chargement d'une feuille de style.
   */
  public function acdc_no_defer_critical_styles( $tag, $handle ) {
    $critical = array( 'acdc-of-frontend', 'acdc-of-ui-system', 'acdc-of-components' );
    if ( in_array( $handle, $critical, true ) && strpos( $tag, 'data-no-optimize' ) === false ) {
      $tag = str_replace( "rel='stylesheet'", "rel='stylesheet' data-no-optimize='1'", $tag );
    }
    return $tag;
  }

    public function enqueue_front_assets() {
    if ( ! is_singular() ) {
      return;
    }

    global $post;
    if ( ! $post instanceof WP_Post ) {
      return;
    }

    if ( has_shortcode( $post->post_content, 'acdc_of_login' ) || has_shortcode( $post->post_content, 'acdc_of_portal' ) || has_shortcode( $post->post_content, 'acdc_of_marketing_public' ) || has_shortcode( $post->post_content, 'acdc_of_questionnaire_session' ) || has_shortcode( $post->post_content, 'acdc_of_learner_login' ) || has_shortcode( $post->post_content, 'acdc_of_learner_portal' ) || has_shortcode( $post->post_content, 'acdc_trainer_portal_login' ) || $this->is_acdc_front_page( $post->ID ) || (int) get_option( 'acdc_of_marketing_public_page_id', 0 ) === (int) $post->ID || (int) get_option( 'acdc_of_questionnaire_session_page_id', 0 ) === (int) $post->ID || (int) get_option( 'acdc_of_trainer_portal_page_id', 0 ) === (int) $post->ID ) {
      wp_enqueue_style( 'dashicons' );
      wp_enqueue_style(
        'acdc-of-frontend',
        ACDC_OF_SAAS_URL . 'assets/css/frontend.css',
        array( 'dashicons' ),
        ACDC_OF_SAAS_VERSION
      );
      wp_add_inline_style( 'acdc-of-frontend', $this->get_dynamic_css() );
      // ACDC 3.25.47 — Masquer la barre admin WordPress sur toutes les pages ACDC
      wp_add_inline_style( 'acdc-of-frontend', '#wpadminbar { display:none !important; } html { margin-top:0 !important; }' );
      show_admin_bar( false );
      wp_enqueue_style( 'acdc-of-ui-system', ACDC_OF_SAAS_URL . 'assets/css/acdc-ui-system.css', array( 'acdc-of-frontend' ), ACDC_OF_SAAS_VERSION );
      wp_enqueue_style( 'acdc-of-components', ACDC_OF_SAAS_URL . 'assets/css/acdc-components.css', array( 'acdc-of-ui-system' ), ACDC_OF_SAAS_VERSION );
      /* ACDC 3.21.11-hotfix4 — Exclure nos CSS critiques du defer LiteSpeed pour garantir
       * que les règles modal (z-index, stacking) sont appliquées avant le premier paint. */
      add_filter( 'style_loader_tag', array( $this, 'acdc_no_defer_critical_styles' ), 10, 2 );
      wp_enqueue_style(
        'acdc-of-learner-portal',
        ACDC_OF_SAAS_URL . 'assets/css/learner-portal.css',
        array( 'acdc-of-ui-system' ),
        ACDC_OF_SAAS_VERSION
      );
      /* ACDC 3.20.95 — CSS du portail formateur, frère jumeau structurel du portail apprenant. */
      wp_enqueue_style(
        'acdc-of-trainer-portal',
        ACDC_OF_SAAS_URL . 'assets/css/trainer-portal.css',
        array( 'acdc-of-ui-system' ),
        ACDC_OF_SAAS_VERSION
      );
      wp_enqueue_script( 'acdc-of-ui-kernel', ACDC_OF_SAAS_URL . 'assets/js/acdc-ui-kernel.js', array(), ACDC_OF_SAAS_VERSION, true );
      if ( method_exists( $this, 'localize_ui_kernel_settings' ) ) { $this->localize_ui_kernel_settings(); }
      wp_enqueue_script( 'acdc-of-admin', ACDC_OF_SAAS_URL . 'assets/js/admin.js', array( 'acdc-of-ui-kernel' ), ACDC_OF_SAAS_VERSION, true );
      /* ACDC 3.20.60 — passage de la config back office au moteur AcdcActionHub. */
      wp_localize_script( 'acdc-of-admin', 'ACDC_ACTION_HUB_CONFIG', $this->get_action_hub_config() );
      wp_enqueue_script( 'acdc-of-ui-system', ACDC_OF_SAAS_URL . 'assets/js/acdc-ui-system.js', array( 'acdc-of-ui-kernel', 'acdc-of-admin' ), ACDC_OF_SAAS_VERSION, true );

      /* ACDC 3.20.74 — Composant éditeur riche centralisé (réutilisable partout). */
      wp_enqueue_style( 'acdc-of-rich-editor', ACDC_OF_SAAS_URL . 'assets/css/acdc-rich-editor.css', array( 'acdc-of-ui-system' ), ACDC_OF_SAAS_VERSION );
      wp_enqueue_script( 'acdc-of-rich-editor', ACDC_OF_SAAS_URL . 'assets/js/acdc-rich-editor.js', array(), ACDC_OF_SAAS_VERSION, true );
    }

  }

  /**
   * ACDC 3.20.74 — Éditeur de texte enrichi centralisé.
   *
   * Composant réutilisable dans tout le plugin. Génère un bloc HTML
   * cohérent avec le système UI ACDC, activé côté navigateur par
   * assets/js/acdc-rich-editor.js. Le contenu HTML est synchronisé
   * en continu vers un <textarea hidden> dont le name est posté
   * normalement avec le formulaire.
   *
   * @param string $name      Nom du champ posté (sera l'attribut name du textarea hidden).
   * @param string $value     Contenu HTML initial (déjà passé par wp_kses_post au save).
   * @param array  $args      Options : profile (minimal|standard|full|mail), disabled, rows, placeholder, variables.
   * @return string           HTML complet du composant.
   */
  protected function render_acdc_rich_editor( $name, $value = '', $args = array() ) {
    $defaults = array(
      'profile'        => 'standard',
      'disabled'       => false,
      'placeholder'    => '',
      'variables'      => array(),
      'variables_json' => '',
      'min_height'     => 160,
    );
    $args = wp_parse_args( $args, $defaults );

    $profile      = in_array( $args['profile'], array( 'minimal', 'standard', 'full', 'mail' ), true ) ? $args['profile'] : 'standard';
    $disabled     = ! empty( $args['disabled'] );
    $editable     = $disabled ? 'false' : 'true';
    $name_attr    = esc_attr( (string) $name );
    $value_html   = (string) $value;
    $placeholder  = esc_attr( (string) $args['placeholder'] );
    $min_height   = absint( $args['min_height'] );
    $style_attr   = $min_height ? ' style="min-height:' . $min_height . 'px;"' : '';
    $vars_attr    = ! empty( $args['variables_json'] ) ? ' data-variables="' . esc_attr( $args['variables_json'] ) . '"' : '';

    // Le contenu est nettoyé par wp_kses_post pour l'affichage en mode contenteditable.
    // À la sauvegarde, handle_save_formation() applique également wp_kses_post.
    $safe_html = wp_kses_post( $value_html );

    ob_start();
    ?>
    <div class="acdc-rich-editor<?php echo $disabled ? ' is-disabled' : ''; ?>"
         data-acdc-rich-editor
         data-profile="<?php echo esc_attr( $profile ); ?>"
         data-disabled="<?php echo $disabled ? '1' : '0'; ?>"<?php echo $vars_attr; ?>>
      <div class="acdc-rich-toolbar" data-acdc-rich-toolbar role="toolbar" aria-label="Outils de mise en forme"></div>
      <div class="acdc-rich-content"
           data-acdc-rich-content
           contenteditable="<?php echo $editable; ?>"
           role="textbox"
           aria-multiline="true"
           aria-label="<?php echo $placeholder ? $placeholder : esc_attr__( 'Zone de saisie', 'acdc-formation-saas' ); ?>"
           <?php echo $style_attr; ?>><?php echo $safe_html; ?></div>
      <textarea name="<?php echo $name_attr; ?>" data-acdc-rich-input hidden tabindex="-1" aria-hidden="true"><?php echo esc_textarea( $value_html ); ?></textarea>
      <textarea data-acdc-rich-codearea class="acdc-rich-codearea" aria-label="<?php esc_attr_e( 'Code HTML', 'acdc-formation-saas' ); ?>"></textarea>
    </div>
    <?php
    return (string) ob_get_clean();
  }

  /**
   * ACDC 3.20.74 — Filtre permettant les styles inline utiles à l'éditeur riche.
   * Étend la whitelist par défaut de wp_kses pour autoriser font-size, color,
   * background-color, text-align, font-weight, font-style, text-decoration,
   * margin-left. Les valeurs sont validées par wp_kses ensuite.
   *
   * Activé via add_filter('safe_style_css', array($this, 'extend_safe_style_css')) ;
   * voir la classe principale du plugin.
   */
  public function extend_safe_style_css( $styles ) {
    $extra = array( 'font-size', 'color', 'background-color', 'text-align', 'font-weight', 'font-style', 'text-decoration', 'margin-left' );
    foreach ( $extra as $rule ) {
      if ( ! in_array( $rule, $styles, true ) ) {
        $styles[] = $rule;
      }
    }
    return $styles;
  }

