  /**
   * ACDC 3.20.77 — Rendu centralisé d'une liste de documents existants
   * (formation : documents partagés ou internes).
   *
   * @param string $multiline_urls  Contenu BD (URLs séparées par retours ligne).
   * @param string $remove_field    Nom du champ checkbox de suppression (ex. 'shared_docs_remove').
   * @param bool   $is_view         True = mode lecture seule (pas de checkbox).
   * @return string                 HTML de la liste, vide si pas de documents.
   */
  protected function render_acdc_existing_docs_list( $multiline_urls, $remove_field, $is_view = false ) {
    $multiline_urls = (string) $multiline_urls;
    if ( '' === trim( $multiline_urls ) ) {
      return '';
    }
    $urls = array_filter( array_map( 'trim', preg_split( '/\r?\n/', $multiline_urls ) ) );
    if ( empty( $urls ) ) {
      return '';
    }
    ob_start();
    ?>
    <ul class="acdc-doc-list" style="list-style:none;padding:0;margin:6px 0 10px;">
      <?php foreach ( $urls as $url ) :
        $path = wp_parse_url( $url, PHP_URL_PATH );
        $name = $path ? rawurldecode( basename( (string) $path ) ) : $url;
      ?>
        <li class="acdc-doc-item" style="display:flex;align-items:center;gap:10px;padding:8px 12px;border:1px solid #e0e6ee;border-radius:8px;margin-bottom:6px;background:#fafbfc;">
          <span class="acdc-doc-name" style="flex:1 1 auto;color:#2a3a55;word-break:break-all;"><?php echo esc_html( $name ); ?></span>
          <a class="acdc-button acdc-button-soft" href="<?php echo esc_url( $url ); ?>" target="_blank" rel="noopener noreferrer" style="flex:none;">Voir</a>
          <?php if ( ! $is_view ) : ?>
            <label style="flex:none;display:inline-flex;align-items:center;gap:6px;color:#c62828;font-size:13px;cursor:pointer;">
              <input type="checkbox" name="<?php echo esc_attr( $remove_field ); ?>[]" value="<?php echo esc_attr( $url ); ?>">
              Supprimer
            </label>
          <?php endif; ?>
        </li>
      <?php endforeach; ?>
    </ul>
    <?php
    return (string) ob_get_clean();
  }

  /**
   * ACDC 3.20.77 — Rendu centralisé d'une liste de liens cliquables (aperçu sous textarea).
   *
   * @param string $multiline_urls  Contenu BD (URLs séparées par retours ligne).
   * @return string                 HTML de la liste, vide si pas de liens.
   */
  protected function render_acdc_existing_links_preview( $multiline_urls ) {
    $multiline_urls = (string) $multiline_urls;
    if ( '' === trim( $multiline_urls ) ) {
      return '';
    }
    $urls = array_filter( array_map( 'trim', preg_split( '/\r?\n/', $multiline_urls ) ) );
    if ( empty( $urls ) ) {
      return '';
    }
    ob_start();
    ?>
    <ul class="acdc-link-list" style="list-style:none;padding:0;margin:6px 0 10px;">
      <?php foreach ( $urls as $url ) :
        // Affichage du libellé : si c'est une URL valide, on extrait l'hôte + path court.
        $display = $url;
        $parsed  = wp_parse_url( $url );
        if ( ! empty( $parsed['host'] ) ) {
          $path_short = isset( $parsed['path'] ) ? rawurldecode( $parsed['path'] ) : '';
          $display    = $parsed['host'] . $path_short;
        }
      ?>
        <li class="acdc-link-item" style="display:flex;align-items:center;gap:10px;padding:8px 12px;border:1px solid #e0e6ee;border-radius:8px;margin-bottom:6px;background:#fafbfc;">
          <span style="flex:1 1 auto;color:#2a3a55;word-break:break-all;"><?php echo esc_html( $display ); ?></span>
          <a class="acdc-button acdc-button-soft" href="<?php echo esc_url( $url ); ?>" target="_blank" rel="noopener noreferrer" style="flex:none;">Voir</a>
        </li>
      <?php endforeach; ?>
    </ul>
    <?php
    return (string) ob_get_clean();
  }

  protected function acdc_get_admin_page_hidden_field() {
    if ( ! is_admin() ) {
      return '';
    }

    return '<input type="hidden" name="page" value="acdc-of-dashboard">';
  }

  protected function acdc_render_section_head( $title, $actions_html = '', $classes = '', $attrs = array() ) {
    $attr_html = '';
    if ( is_array( $attrs ) ) {
      foreach ( $attrs as $key => $value ) {
        if ( '' === (string) $value ) {
          continue;
        }
        $attr_html .= ' ' . preg_replace( '/[^a-zA-Z0-9_:\-]/', '', (string) $key ) . '="' . esc_attr( (string) $value ) . '"';
      }
    }

    echo '<section class="acdc-section-head acdc-section-head-standard ' . esc_attr( trim( (string) $classes ) ) . '"' . $attr_html . '>';
    echo '<div><h2>' . esc_html( $title ) . '</h2></div>';
    if ( '' !== $actions_html ) {
      echo '<div class="acdc-section-head-actions">' . $actions_html . '</div>';
    }
    echo '</section>';
  }

  protected function acdc_render_search_toolbar( $args = array() ) {
    $defaults = array(
      'action'          => '',
      'tab'             => '',
      'search_name'     => 'q',
      'search_value'    => '',
      'placeholder'     => 'Rechercher',
      'form_class'      => 'acdc-search-form',
      'toolbar_class'   => 'acdc-toolbar acdc-toolbar-standard',
      'hidden_fields'   => array(),
      'leading_html'    => '',
      'trailing_html'   => '',
    );
    $args = wp_parse_args( $args, $defaults );

    echo '<div class="' . esc_attr( $args['toolbar_class'] ) . '">';
    echo '<form method="get" action="' . esc_url( $args['action'] ) . '" class="' . esc_attr( $args['form_class'] ) . '">';
    echo $this->acdc_get_admin_page_hidden_field();
    if ( '' !== $args['tab'] ) {
      echo '<input type="hidden" name="tab" value="' . esc_attr( $args['tab'] ) . '">';
    }
    if ( ! empty( $args['hidden_fields'] ) && is_array( $args['hidden_fields'] ) ) {
      foreach ( $args['hidden_fields'] as $hidden_key => $hidden_value ) {
        echo '<input type="hidden" name="' . esc_attr( $hidden_key ) . '" value="' . esc_attr( $hidden_value ) . '">';
      }
    }
    echo $args['leading_html'];
    echo '<span class="acdc-search-icon">' . $this->render_inline_icon( 'search', 16 ) . '</span>';
    echo '<input type="search" name="' . esc_attr( $args['search_name'] ) . '" value="' . esc_attr( $args['search_value'] ) . '" placeholder="' . esc_attr( $args['placeholder'] ) . '">';
    echo $args['trailing_html'];
    echo '</form>';
    echo '</div>';
  }

  protected function acdc_render_empty_state( $message, $args = array() ) {
    $defaults = array(
      'icon'        => '',
      'actions_html'=> '',
      'classes'     => '',
    );
    $args = wp_parse_args( $args, $defaults );
    echo '<div class="acdc-empty-state acdc-empty-state-standard ' . esc_attr( trim( (string) $args['classes'] ) ) . '">';
    if ( '' !== $args['icon'] ) {
      echo '<div class="acdc-empty-state-icon" aria-hidden="true">' . $this->render_inline_icon( $args['icon'], 54 ) . '</div>';
    }
    echo '<p>' . esc_html( $message ) . '</p>';
    if ( '' !== $args['actions_html'] ) {
      echo '<div class="acdc-empty-state-actions">' . $args['actions_html'] . '</div>';
    }
    echo '</div>';
  }

  protected function acdc_render_choice_tiles( $tiles, $classes = '' ) {
    echo '<div class="acdc-choice-tiles ' . esc_attr( trim( (string) $classes ) ) . '">';
    foreach ( $tiles as $tile ) {
      $link = ! empty( $tile['link'] ) ? $tile['link'] : '#';
      $title = ! empty( $tile['title'] ) ? $tile['title'] : '';
      $subtitle = ! empty( $tile['subtitle'] ) ? $tile['subtitle'] : '';
      echo '<a href="' . esc_url( $link ) . '" class="acdc-choice-tile">';
      echo '<strong class="acdc-choice-tile-title">' . esc_html( $title ) . '</strong>';
      if ( '' !== $subtitle ) {
        echo '<span class="acdc-choice-tile-subtitle">' . esc_html( $subtitle ) . '</span>';
      }
      echo '</a>';
    }
    echo '</div>';
  }

  private function acdc_render_portal_runtime_error( $tab, $error ) {
    $message = $error instanceof \Throwable ? $error->getMessage() : (string) $error;
    $this->log_error( 'portal_render_' . sanitize_key( (string) $tab ), 'Erreur de rendu d\'écran : ' . $message, array(
      'tab'   => sanitize_key( (string) $tab ),
      'error' => $message,
      'type'  => is_object( $error ) ? get_class( $error ) : gettype( $error ),
    ) );
    echo '<div class="acdc-panel acdc-panel-error">';
    echo '<h2>Erreur de chargement</h2>';
    echo '<p>Un incident a empêché l\'affichage complet de cet écran.</p>';
    echo '<p><strong>Onglet :</strong> ' . esc_html( (string) $tab ) . '</p>';
    echo '<p><strong>Détail :</strong> ' . esc_html( $message ) . '</p>';
    echo '</div>';
  }

  public function render_portal_shortcode( $atts = array() ) {
    if ( ! is_user_logged_in() ) {
      return '<div class="acdc-portal-shell"><div class="acdc-panel"><h2>Accès requis</h2><p>Veuillez vous connecter pour accéder à cet espace.</p><p><a class="acdc-button acdc-button-primary" href="' . esc_url( $this->login_page_url() ) . '">Aller à la connexion</a></p></div></div>';
    }

    /* M25 — L'extranet est authentifié et dynamique : il ne doit jamais être servi en cache
       (sinon l'Archive des e-mails et les données récentes apparaissent périmées). On signale
       aux caches de page/objet de ne pas mettre cette page en cache. */
    if ( ! defined( 'DONOTCACHEPAGE' ) )   { define( 'DONOTCACHEPAGE', true ); }
    if ( ! defined( 'DONOTCACHEOBJECT' ) ) { define( 'DONOTCACHEOBJECT', true ); }
    if ( ! defined( 'DONOTCACHEDB' ) )     { define( 'DONOTCACHEDB', true ); }
    if ( ! headers_sent() && function_exists( 'nocache_headers' ) ) { nocache_headers(); }

    $atts = shortcode_atts( array( 'tab' => 'dashboard' ), $atts, 'acdc_of_portal' );
    $tab   = isset( $_GET['tab'] ) ? sanitize_key( wp_unslash( $_GET['tab'] ) ) : sanitize_key( $atts['tab'] );
    $action = isset( $_GET['action'] ) ? sanitize_key( wp_unslash( $_GET['action'] ) ) : 'list';

    if ( ! $this->current_user_can_access_plugin_screen( $tab, $action, 'front' ) ) {
      return '<div class="acdc-portal-shell"><div class="acdc-panel"><h2>Accès refusé</h2><p>Vous ne disposez pas des permissions nécessaires pour cet écran.</p></div></div>';
    }
    $item_id = isset( $_GET['item_id'] ) ? absint( $_GET['item_id'] ) : 0;

    $page_context = $this->get_page_context_classes( $tab, $action );

    ob_start();
    ?>
    <div class="acdc-portal-shell acdc-portal-shell-extranet <?php echo esc_attr( $page_context ); ?>">
      <div class="acdc-portal-layout acdc-portal-layout-extranet">
        <aside class="acdc-portal-nav acdc-portal-nav-extranet">
          <?php $this->render_brand_block(); ?>
          <?php $this->render_portal_navigation( $tab ); ?>
        </aside>

        <main class="acdc-portal-content acdc-portal-content-extranet <?php echo esc_attr( $page_context ); ?>">
          <div class="acdc-extranet-topbar">
            <?php $this->render_user_dropdown( false ); ?>
          </div>

          <?php $this->render_front_notice(); ?>

          <?php
          try {
          switch ( $tab ) {
            case 'crm':
              $this->render_front_crm_hub();
              break;
            case 'calendar':
              $this->render_front_calendar_tab();
