    /**
     * Filtre permettant aux modules métier d'ajouter, masquer ou réordonner
     * des entrées dans la sidebar extranet/admin.
     *
     * Le filtre reçoit la structure complète des groupes telle que définie
     * ci-dessus et doit retourner une structure de même forme. Voir le module
     * Quizzes (3.21.01.1) pour un exemple d'utilisation.
     *
     * @since 3.21.01.1
     *
     * @param array  $groups       Tableau des groupes de navigation.
     * @param string $current_tab  Onglet courant (utile pour highlighting conditionnel).
     */
    $groups = apply_filters( 'acdc_portal_navigation_groups', $groups, $current_tab );

    echo '<nav class="acdc-nav-list">';

    foreach ( $groups as $group ) {
      if ( isset( $group['tab'] ) && ! $this->current_user_can_access_plugin_screen( $group['tab'], 'list', is_admin() ? 'admin' : 'front' ) ) {
        continue;
      }
      if ( isset( $group['items'] ) && is_array( $group['items'] ) ) {
        $group['items'] = array_values( array_filter( $group['items'], function( $item ) {
          return ! isset( $item['tab'] ) || $this->current_user_can_access_plugin_screen( $item['tab'], 'list', is_admin() ? 'admin' : 'front' );
        } ) );
        if ( empty( $group['items'] ) && 'group' === ( isset( $group['type'] ) ? $group['type'] : '' ) ) {
          continue;
        }
      }
      if ( 'section' === $group['type'] ) {
        echo '<div class="acdc-nav-section-title">' . esc_html( $group['label'] ) . '</div>';
        continue;
      }

      if ( 'single' === $group['type'] ) {
        $class = $group['tab'] === $current_tab ? 'is-active' : '';
        echo '<a class="acdc-nav-item acdc-nav-item-single ' . esc_attr( $class ) . '" href="' . esc_url( $this->portal_page_url( array( 'tab' => $group['tab'] ) ) ) . '">';
        echo '<span class="acdc-nav-item-left">';
        echo $this->render_nav_icon( $group['icon'] );
        echo '<span class="acdc-nav-text">' . esc_html( $group['label'] ) . '</span>';
        echo '</span>';
        echo $this->render_nav_icon( 'chevron-right', 'acdc-nav-chevron' );
        echo '</a>';
        continue;
      }

      $group_tabs = wp_list_pluck( $group['items'], 'tab' );
      $is_open  = in_array( $current_tab, $group_tabs, true );

      echo '<details class="acdc-nav-group acdc-nav-group-extranet"' . ( $is_open ? ' open' : '' ) . '>';
      echo '<summary class="acdc-nav-group-summary">';
      echo '<span class="acdc-nav-item-left">';
      echo $this->render_nav_icon( $group['icon'] );
      echo '<span class="acdc-nav-text">' . esc_html( $group['label'] ) . '</span>';
      echo '</span>';
      echo $this->render_nav_icon( 'chevron-down', 'acdc-nav-chevron acdc-nav-summary-chevron' );
      echo '</summary>';

      echo '<div class="acdc-nav-submenu">';
      foreach ( $group['items'] as $item ) {
        $item_args = isset( $item['args'] ) && is_array( $item['args'] ) ? $item['args'] : array();
        $item_source_type = isset( $item_args['source_type'] ) ? (string) $item_args['source_type'] : '';
        $is_item_active = $item['tab'] === $current_tab;
        $children_html = '';
        $has_active_child = false;

        if ( ! empty( $item['children'] ) && is_array( $item['children'] ) ) {
          foreach ( $item['children'] as $child ) {
            $child_args = isset( $child['args'] ) && is_array( $child['args'] ) ? $child['args'] : array();
            $child_source_type = isset( $child_args['source_type'] ) ? (string) $child_args['source_type'] : '';
            $child_context = '' !== $child_source_type ? $child_source_type : ( isset( $child_args['from_context'] ) ? (string) $child_args['from_context'] : '' );
            $child_is_active = $child['tab'] === $current_tab;
            if ( $child_is_active && '' !== $child_context ) {
              $child_is_active = $child_context === $current_source_type;
            }
            if ( $child_is_active ) {
              $has_active_child = true;
            }
          }
          if ( $has_active_child ) {
            $is_item_active = true;
          }
        }

        if ( $is_item_active && '' !== $item_source_type ) {
          $is_item_active = $item_source_type === $current_source_type;
        }

        $highlight_prospects_from_dashboard = ( 'prospect_followup' === $current_tab && isset( $_GET['dashboard_focus'] ) && 'prospects' === sanitize_key( wp_unslash( $_GET['dashboard_focus'] ) ) && 'prospects' === $item['tab'] );
        $class = $is_item_active ? 'is-active' : '';
        if ( $highlight_prospects_from_dashboard ) {
          $class .= ( '' !== $class ? ' ' : '' ) . 'acdc-nav-subitem-dashboard-highlight';
        }
        echo '<a class="acdc-nav-subitem ' . esc_attr( $class ) . '" href="' . esc_url( $this->portal_page_url( array_merge( array( 'tab' => $item['tab'] ), $item_args ) ) ) . '">';
        echo '<span class="acdc-nav-item-left">';
        echo $this->render_nav_icon( $item['icon'] );
        echo '<span class="acdc-nav-text">' . esc_html( $item['label'] ) . '</span>';
        echo '</span>';
        echo '</a>';

        if ( ! empty( $item['children'] ) && is_array( $item['children'] ) ) {
          echo '<div class="acdc-nav-children" style="margin:4px 0 8px 34px;padding-left:10px;border-left:1px solid rgba(12,45,82,0.10);display:flex;flex-direction:column;gap:4px;">';
          foreach ( $item['children'] as $child ) {
            $child_args = isset( $child['args'] ) && is_array( $child['args'] ) ? $child['args'] : array();
            $child_source_type = isset( $child_args['source_type'] ) ? (string) $child_args['source_type'] : '';
            $child_context = '' !== $child_source_type ? $child_source_type : ( isset( $child_args['from_context'] ) ? (string) $child_args['from_context'] : '' );
            $child_is_active = $child['tab'] === $current_tab;
            if ( $child_is_active && '' !== $child_context ) {
              $child_is_active = $child_context === $current_source_type;
            }
            $child_class = $child_is_active ? 'is-active' : '';
            echo '<a class="acdc-nav-subitem acdc-nav-subitem-child ' . esc_attr( $child_class ) . '" style="min-height:34px;padding:6px 10px;border-radius:10px;font-size:12px;" href="' . esc_url( $this->portal_page_url( array_merge( array( 'tab' => $child['tab'] ), $child_args ) ) ) . '">';
            echo '<span class="acdc-nav-item-left">';
            echo $this->render_nav_icon( $child['icon'] );
            echo '<span class="acdc-nav-text">' . esc_html( $child['label'] ) . '</span>';
            echo '</span>';
            echo '</a>';
          }
          echo '</div>';
        }
      }
      echo '</div>';
      echo '</details>';
    }

    echo '</nav>';
  }  private function render_nav_icon( $icon, $class = 'acdc-nav-icon' ) {
    return '<span class="' . esc_attr( $class ) . '" aria-hidden="true">' . $this->get_nav_icon_svg( $icon ) . '</span>';
  }
  private function render_inline_icon( $icon, $size = 18, $class = '' ) {
    $icon = $this->map_configured_action_icon( $icon );
    $svg = preg_replace( '/<svg\b/', '<svg width="' . (int) $size . '" height="' . (int) $size . '"', $this->get_nav_icon_svg( $icon ), 1 );
    return '<span' . ( $class ? ' class="' . esc_attr( $class ) . '"' : '' ) . ' aria-hidden="true" style="display:inline-flex;align-items:center;justify-content:center;width:' . (int) $size . 'px;height:' . (int) $size . 'px;line-height:1;">' . $svg . '</span>';
  }

  private function map_configured_action_icon( $icon ) {
    $map = array(
      'more-horizontal' => 'action_icon_more',
      'eye' => 'action_icon_view',
      'view' => 'action_icon_view',
      'edit' => 'action_icon_edit',
      'edit-pencil' => 'action_icon_edit',
      'pencil' => 'action_icon_edit',
      'trash' => 'action_icon_delete',
      'trash-bin' => 'action_icon_delete',
      'delete' => 'action_icon_delete',
      'copy' => 'action_icon_duplicate',
      'duplicate' => 'action_icon_duplicate',
      'archive' => 'action_icon_archive',
      'clipboard' => 'action_icon_followup',
      'followup' => 'action_icon_followup',
      'task' => 'action_icon_followup',
      /* ACDC 3.20.104 — 4 nouvelles actions configurables. */
      'create-session' => 'action_icon_create_session',
      'add-session'    => 'action_icon_create_session',
      'new-session'    => 'action_icon_create_session',
      'add-circle'     => 'action_icon_create_session',
      'sessions-list'  => 'action_icon_sessions_list',
      'clock-list'     => 'action_icon_sessions_list',
      'sessions-clock' => 'action_icon_sessions_list',
      'results'        => 'action_icon_results',
      'bar-chart'      => 'action_icon_results',
      'stats'          => 'action_icon_results',
      'open'           => 'action_icon_open',
      'external-link'  => 'action_icon_open',
      'open-external'  => 'action_icon_open',
    );
    if ( ! isset( $map[ $icon ] ) ) { return $icon; }
    $options = method_exists( $this, 'get_branding_options' ) ? $this->get_branding_options() : array();
    $configured = isset( $options[ $map[ $icon ] ] ) ? sanitize_key( $options[ $map[ $icon ] ] ) : '';
    return $configured ? $configured : $icon;
  }

  private function render_user_dropdown( $is_admin_mode = false ) {
    $user = wp_get_current_user();
    $profile_url = $is_admin_mode ? $this->admin_tab_url( 'company_profile' ) : $this->portal_page_url( array( 'tab' => 'company_profile' ) );
    $my_profile_url = $is_admin_mode ? $this->admin_tab_url( 'my_profile' ) : $this->portal_page_url( array( 'tab' => 'my_profile' ) );
    $logout_url = wp_nonce_url( admin_url( 'admin-post.php?action=acdc_front_logout' ), 'acdc_front_logout' );
    ?>
