  }  private function render_front_notice() {
    $message = '';
    $type    = 'success';

    if ( ! empty( $_GET['notice'] ) ) {
      $message = sanitize_text_field( wp_unslash( $_GET['notice'] ) );
      $type    = ! empty( $_GET['notice_type'] ) ? $this->acdc_normalize_notice_type( wp_unslash( $_GET['notice_type'] ) ) : 'success';
    } elseif ( ! empty( $_GET['catalog_notice'] ) ) {
      $message = sanitize_text_field( wp_unslash( $_GET['catalog_notice'] ) );
      $type    = ! empty( $_GET['catalog_notice_type'] ) ? $this->acdc_normalize_notice_type( wp_unslash( $_GET['catalog_notice_type'] ) ) : 'info';
    } elseif ( ! empty( $_GET['q_notice'] ) ) {
      $message = sanitize_text_field( wp_unslash( $_GET['q_notice'] ) );
      $type    = ! empty( $_GET['q_notice_type'] ) ? $this->acdc_normalize_notice_type( wp_unslash( $_GET['q_notice_type'] ) ) : 'info';
    }

    if ( '' === $message ) {
      return;
    }

    $title_map = array(
      'success' => 'Action réussie',
      'error'   => 'Action impossible',
      'warning' => 'Vigilance',
      'info'    => 'Information',
    );
    $title = isset( $title_map[ $type ] ) ? $title_map[ $type ] : $title_map['info'];
    $class = 'acdc-alert acdc-alert-' . $type . ' acdc-alert-dismissible';

    echo '<div class="' . esc_attr( $class ) . '" role="status" aria-live="polite">';
    echo '<div class="acdc-alert-body">';
    echo '<strong class="acdc-alert-title">' . esc_html( $title ) . '</strong>';
    echo '<p class="acdc-alert-message">' . esc_html( $message ) . '</p>';
    echo '</div>';
    echo '<button type="button" class="acdc-alert-dismiss" data-acdc-dismiss-alert aria-label="Fermer ce message">×</button>';
    echo '</div>';
  }  private function render_front_training_convocations_tab() {
    $search = isset( $_GET['q'] ) ? sanitize_text_field( wp_unslash( $_GET['q'] ) ) : '';
    $per_page = isset( $_GET['per_page'] ) ? absint( wp_unslash( $_GET['per_page'] ) ) : 25;
    if ( ! in_array( $per_page, array( 25, 50, 100 ), true ) ) {
      $per_page = 25;
    }
    $paged = isset( $_GET['paged'] ) ? max( 1, absint( wp_unslash( $_GET['paged'] ) ) ) : 1;
    $base_tab = 'training_convocations';
    $base_url = is_admin() ? $this->admin_tab_url( $base_tab ) : $this->portal_page_url( array( 'tab' => $base_tab ) );
    $rows = $this->get_training_convocation_entries( $search );
    $total = count( $rows );
    $total_pages = max( 1, (int) ceil( $total / $per_page ) );
    if ( $paged > $total_pages ) {
      $paged = $total_pages;
    }
    $offset = ( $paged - 1 ) * $per_page;
    $page_rows = array_slice( $rows, $offset, $per_page );
    ?>
    <?php $this->acdc_render_section_head( 'Convocations de début de formation' ); ?>
    <div class="acdc-panel acdc-mb-18">
      <form class="acdc-search-bar" method="get" action="<?php echo esc_url( $base_url ); ?>">
