  }  private function render_front_training_files_tab( $action, $item_id, $forced_trf_view = null ) {
    $action = in_array( $action, array( 'list', 'view' ), true ) ? $action : 'list';
    // Déterminer trf_view dès l'entrée (accessible dans tout le scope de la fonction)
    $allowed_trf = array( 'inscriptions', 'apprenants', 'commanditaires', 'formations', 'seances' );
    if ( $forced_trf_view && in_array( $forced_trf_view, $allowed_trf, true ) ) {
      $trf_view = $forced_trf_view;
    } else {
      $trf_view = isset( $_GET['trf_view'] ) ? sanitize_key( wp_unslash( $_GET['trf_view'] ) ) : 'inscriptions';
      if ( ! in_array( $trf_view, $allowed_trf, true ) ) { $trf_view = 'inscriptions'; }
    }

    // ACDC 3.25.38 — Dispatch trf_action=delete_file (portal, évite admin-post.php / WAF)
    if ( ! is_admin() && isset( $_GET['trf_action'] ) && 'delete_file' === $_GET['trf_action'] ) {
      $rid    = isset( $_GET['registration_id'] ) ? absint( wp_unslash( $_GET['registration_id'] ) ) : 0;
      $rnonce = isset( $_REQUEST['_wpnonce'] ) ? sanitize_text_field( wp_unslash( $_REQUEST['_wpnonce'] ) ) : '';
      if ( is_user_logged_in() && $this->is_admin_manager() && wp_verify_nonce( $rnonce, 'acdc_delete_training_file_' . $rid ) ) {
        $this->handle_delete_training_file( true );
      } else {
        wp_safe_redirect( $this->portal_page_url( array( 'tab' => 'trf_inscriptions' ) ) );
        exit;
      }
    }

    // ACDC 3.25.06 — Sous-onglets Dossiers de formation (uniquement en mode liste)
    if ( 'list' === $action ) {
      // Base URL : pointe vers le tab courant (sous-module dédié si forced, sinon training_files legacy)
      $trf_tab_map = array(
        'inscriptions'   => 'trf_inscriptions',
        'apprenants'     => 'trf_apprenants',
        'commanditaires' => 'trf_commanditaires',
        'formations'     => 'trf_formations',
        'seances'        => 'trf_seances',
      );
      $current_tab_slug = isset( $trf_tab_map[ $trf_view ] ) ? $trf_tab_map[ $trf_view ] : 'trf_inscriptions';
      $base_url_trf = is_admin() ? $this->admin_tab_url( $current_tab_slug ) : $this->portal_page_url( array( 'tab' => $current_tab_slug ) );
      $tab_labels_trf = array(
        'inscriptions'   => 'Inscriptions',
        'apprenants'     => 'Par apprenant',
        'commanditaires' => 'Par commanditaire',
        'formations'     => 'Par formation',
        'seances'        => 'Par séance',
      );
      ?>
