      <?php
      // ── Tous les onglets (inscriptions, apprenants, commanditaires, formations, seances)
      // rendent la même liste d'inscriptions — section-head déjà rendue ci-dessus
    }
    // ── Code original (liste inscriptions + vue fiche) ────────────────────
    $search = isset( $_GET['q'] ) ? sanitize_text_field( wp_unslash( $_GET['q'] ) ) : '';
    $status = isset( $_GET['file_status'] ) ? sanitize_text_field( wp_unslash( $_GET['file_status'] ) ) : '';
    $entries = $this->get_training_registrations( null );
    $rows = array();
    foreach ( (array) $entries as $entry ) {
      $subject = $this->get_training_registration_subject_label( $entry->belongs_to_group, $entry->group_label, $entry->learner_label, $entry->learners_label );
      $status_label = $this->get_training_file_status_label( $entry );
      $haystack = strtolower( trim( implode( ' ', array_filter( array(
        (string) $entry->title,
        (string) $entry->formation_title,
        (string) $subject,
        (string) $entry->company_label,
        (string) $status_label,
      ) ) ) ) );
      if ( '' !== $search && false === strpos( $haystack, strtolower( $search ) ) ) {
        continue;
      }
      if ( '' !== $status && $status !== sanitize_title( $status_label ) ) {
        continue;
      }
      // Filtre par sous-module
      if ( 'apprenants' === $trf_view && 'Oui' === (string) $entry->belongs_to_group ) {
        continue; // exclure les groupes
      }
      $rows[] = array(
        'entry' => $entry,
        'subject' => $subject,
        'status_label' => $status_label,
      );
    }
    $trf_tab_map_base = array(
      'inscriptions'   => 'trf_inscriptions',
      'apprenants'     => 'trf_apprenants',
      'commanditaires' => 'trf_commanditaires',
      'formations'     => 'trf_formations',
      'seances'        => 'trf_seances',
    );
    $base_tab_slug = isset( $trf_tab_map_base[ $trf_view ] ) ? $trf_tab_map_base[ $trf_view ] : 'trf_inscriptions';
    $base_url = is_admin() ? $this->admin_tab_url( $base_tab_slug ) : $this->portal_page_url( array( 'tab' => $base_tab_slug ) );
    $registration = $item_id ? $this->get_training_registration( $item_id ) : null;
    ?>
    <?php if ( 'view' === $action && $registration ) :
      $subject = $this->get_training_registration_subject_label( $registration->belongs_to_group, $registration->group_label, $registration->learner_label, $registration->learners_label );
      $learner = ! empty( $registration->learner_id ) ? $this->get_learner( (int) $registration->learner_id ) : null;
      $company = ! empty( $registration->company_id ) ? $this->get_company( (int) $registration->company_id ) : null;
      $formation = ! empty( $registration->formation_id ) ? $this->get_formation( (int) $registration->formation_id ) : null;
      $subtab = isset( $_GET['subtab'] ) ? sanitize_key( wp_unslash( $_GET['subtab'] ) ) : 'synthesis';
      if ( ! in_array( $subtab, array( 'synthesis', 'need', 'objectives', 'positioning', 'contract', 'welcome', 'sessions', 'support', 'evaluations', 'documents', 'complaints', 'compliance', 'quality', 'public_info', 'accounting', 'history' ), true ) ) { $subtab = 'synthesis'; }
      $history_entries = $this->get_training_file_history_entries( $registration );
      $profile = $this->get_training_file_profile( (int) $registration->id );
      $linked_sessions = $this->get_training_file_linked_sessions( $registration );
