        <?php if ( 'apprenants' === $trf_view ) : ?>
        <?php
        // ── ACDC 3.25.14 — Spécifique Par apprenant : réponses NAD + liste NAD de l'apprenant
        global $wpdb;
        $solo_learner_id = ! empty( $registration->learner_id ) ? (int) $registration->learner_id : 0;
        $last_nad = null;
        if ( $solo_learner_id ) {
          $last_nad = $wpdb->get_row( $wpdb->prepare(
            "SELECT * FROM {$this->need_analysis_table}
             WHERE apprenant_id = %d AND statut IN ('traite','soumise') AND is_model = 0
             ORDER BY updated_at DESC, id DESC LIMIT 1",
            $solo_learner_id
          ) );
        }

        if ( $last_nad && ! empty( $last_nad->reponses ) ) :
          $rep_decoded = json_decode( $last_nad->reponses, true );
          if ( ! is_array( $rep_decoded ) ) { $rep_decoded = array(); }

          // Récupérer les blocs utilisés dans CETTE analyse (dans l'ordre)
          $nad_bloc_ids = array();
          if ( ! empty( $last_nad->blocs_ids ) ) {
            $decoded_bids = json_decode( $last_nad->blocs_ids, true );
            if ( is_array( $decoded_bids ) ) { $nad_bloc_ids = array_map( 'intval', $decoded_bids ); }
          }
          // Récupérer toutes les questions de ces blocs avec le bon libellé, dans l'ordre
          $questions_ordered = array();
          if ( ! empty( $nad_bloc_ids ) ) {
            $ph_bids = implode( ',', array_fill( 0, count( $nad_bloc_ids ), '%d' ) );
            $questions_ordered = $wpdb->get_results( $wpdb->prepare(
              "SELECT code, libelle FROM {$this->need_question_table}
               WHERE bloc_id IN ($ph_bids)
               ORDER BY FIELD(bloc_id, $ph_bids), ordre ASC, id ASC",
              ...$nad_bloc_ids, ...$nad_bloc_ids
            ) );
          }
          // Fallback : toutes les questions connues si blocs_ids absent
          if ( empty( $questions_ordered ) ) {
            $questions_ordered = $wpdb->get_results(
              "SELECT code, libelle FROM {$this->need_question_table} ORDER BY bloc_id ASC, ordre ASC, id ASC"
            );
          }
