          if ( ! empty( $cps->trainer_id ) && ! in_array( (int) $cps->trainer_id, $seen_trainer_ids, true ) ) {
            global $wpdb;
            $t = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$this->trainer_table} WHERE id = %d", (int) $cps->trainer_id ) );
            if ( $t ) {
              $linked_trainers[] = $t;
              $seen_trainer_ids[] = (int) $cps->trainer_id;
            }
          }
        }
