        <?php
        /* ── Bloc PSH synthétique — données issues du NAD lié au dossier ── */
        global $wpdb;
        $psh_nad_handicap        = '';
        $psh_nad_handicap_detail = '';
        $psh_nad_difficultes     = '';
        $psh_nad_found           = false;
        if ( ! empty( $registration->id ) ) {
          $nad_row = $wpdb->get_row( $wpdb->prepare(
            "SELECT reponses FROM {$this->need_analysis_table} WHERE dossier_id = %d AND statut = 'traite' ORDER BY id DESC LIMIT 1",
            (int) $registration->id
          ) );
          if ( $nad_row && ! empty( $nad_row->reponses ) ) {
            $nad_rep = json_decode( $nad_row->reponses, true );
            if ( is_array( $nad_rep ) ) {
              $psh_nad_found           = true;
              $psh_nad_handicap        = isset( $nad_rep['com_handicap'] )        ? (string) $nad_rep['com_handicap']        : '';
              $psh_nad_handicap_detail = isset( $nad_rep['com_handicap_detail'] ) ? (string) $nad_rep['com_handicap_detail'] : '';
              $psh_nad_difficultes     = isset( $nad_rep['app_difficultes'] )     ? (string) $nad_rep['app_difficultes']     : '';
            }
          }
        }
        $psh_is_oui      = ( 'Oui' === $psh_nad_handicap );
        $psh_has_dys     = ( '' !== trim( $psh_nad_difficultes ) );
        $psh_alert_level = $psh_is_oui ? 'high' : ( $psh_has_dys ? 'medium' : 'none' );
        $psh_border      = 'high' === $psh_alert_level ? '#e06d6d' : ( 'medium' === $psh_alert_level ? '#f0b45e' : '#35b37e' );
        $psh_bg          = 'high' === $psh_alert_level ? '#fff5f5' : ( 'medium' === $psh_alert_level ? '#fffbf0' : '#f0faf5' );
        $psh_badge_txt   = 'high' === $psh_alert_level ? '⚠️ Situation de handicap déclarée' : ( 'medium' === $psh_alert_level ? '⚠️ Difficultés spécifiques signalées (Dys / autre)' : '✅ Aucune situation PSH signalée' );
        ?>
        <div style="background:<?php echo esc_attr( $psh_bg ); ?>;border:1px solid <?php echo esc_attr( $psh_border ); ?>;border-left:5px solid <?php echo esc_attr( $psh_border ); ?>;border-radius:10px;padding:16px 20px;margin-bottom:18px;">
          <div style="display:flex;align-items:center;gap:10px;margin-bottom:<?php echo ( $psh_nad_found && ( $psh_is_oui || $psh_has_dys ) ) ? '12px' : '0'; ?>;">
            <strong style="font-size:14px;color:#0f2c52;">Synthèse PSH — Recueil des besoins</strong>
            <span style="display:inline-block;padding:3px 12px;border-radius:20px;font-size:11px;font-weight:700;background:<?php echo esc_attr( $psh_border ); ?>;color:#fff;"><?php echo esc_html( $psh_badge_txt ); ?></span>
            <?php if ( ! $psh_nad_found ) : ?>
            <span style="font-size:12px;color:#8a96a8;font-style:italic;">Aucun recueil des besoins soumis pour ce dossier.</span>
            <?php endif; ?>
          </div>
          <?php if ( $psh_nad_found ) : ?>
          <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px 20px;">
            <div>
              <div style="font-size:11px;font-weight:700;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px;">Besoin d'adaptation handicap (NAD)</div>
              <div style="font-size:13px;color:#0f2c52;font-weight:<?php echo $psh_is_oui ? '700' : '400'; ?>;color:<?php echo $psh_is_oui ? '#e06d6d' : '#35b37e'; ?>;">
                <?php echo esc_html( $psh_nad_handicap ?: '—' ); ?>
              </div>
              <?php if ( $psh_nad_handicap_detail ) : ?>
              <div style="font-size:12px;color:#4b5d76;margin-top:4px;font-style:italic;"><?php echo esc_html( $psh_nad_handicap_detail ); ?></div>
              <?php endif; ?>
            </div>
            <div>
              <div style="font-size:11px;font-weight:700;color:#6b7280;text-transform:uppercase;letter-spacing:.05em;margin-bottom:4px;">Difficultés spécifiques — Dys / TDAH (NAD)</div>
              <div style="font-size:13px;color:<?php echo $psh_has_dys ? '#b27000' : '#35b37e'; ?>;font-weight:<?php echo $psh_has_dys ? '600' : '400'; ?>;">
                <?php echo $psh_has_dys ? esc_html( $psh_nad_difficultes ) : '<span style="color:#35b37e;">Aucune difficulté signalée</span>'; ?>
              </div>
            </div>
          </div>
          <?php endif; ?>
