            /* ── Tableau structuré sous-traitants dossier — ACDC 3.24.16 ── */
            $dsc_items    = $this->get_dossier_subcontractors( (int) $registration->id );
            $sc_registry  = get_option( 'acdc_of_subcontractors', array() );
            if ( ! is_array( $sc_registry ) ) { $sc_registry = array(); }
            $dsc_post_action = isset( $_REQUEST['dsc_post_action'] ) ? sanitize_key( wp_unslash( $_REQUEST['dsc_post_action'] ) ) : '';
            $dsc_pid_action  = isset( $_REQUEST['dsc_pid_action'] )  ? sanitize_key( wp_unslash( $_REQUEST['dsc_pid_action'] ) )  : '';
            if ( 'save' === $dsc_post_action && ! is_admin() ) {
              $this->handle_save_dossier_subcontractor(); return;
            }
            if ( 'delete' === $dsc_pid_action ) {
              $this->handle_delete_dossier_subcontractor(); return;
            }
            $dsc_action  = isset( $_GET['dsc_action'] ) ? sanitize_key( wp_unslash( $_GET['dsc_action'] ) ) : '';
            $dsc_edit_id = isset( $_GET['dsc_edit'] ) ? sanitize_key( wp_unslash( $_GET['dsc_edit'] ) ) : '';
            $dsc_base    = is_admin() ? admin_url( 'admin.php?page=acdc-of-dashboard' ) : $this->portal_page_url( array( 'tab' => 'training_files' ) );
            $dsc_view_url = add_query_arg( array( 'action' => 'view', 'item_id' => (int) $registration->id, 'subtab' => 'compliance' ), $dsc_base );
            $dsc_save_url = is_admin() ? admin_url( 'admin-post.php' ) : $this->portal_page_url( array( 'tab' => 'training_files', 'action' => 'view', 'item_id' => (int) $registration->id, 'subtab' => 'compliance', 'dsc_post_action' => 'save' ) );
            $dsc_edit_item = array();
            if ( $dsc_edit_id ) {
              foreach ( $dsc_items as $di ) {
                if ( ( $di['id'] ?? '' ) === $dsc_edit_id ) { $dsc_edit_item = $di; break; }
              }
            }
            ?>
            <?php if ( 'add' === $dsc_action || $dsc_edit_id ) : ?>
            <div class="tf-ug-panel" style="margin-bottom:14px;">
              <div class="tf-ug-head"><span class="tf-ug-title"><?php echo $dsc_edit_id ? 'Modifier le sous-traitant' : 'Ajouter un sous-traitant à ce dossier'; ?></span></div>
              <form method="post" action="<?php echo esc_url( $dsc_save_url ); ?>" class="acdc-form" style="padding:14px 18px;">
                <?php if ( is_admin() ) : ?><input type="hidden" name="action" value="acdc_save_dossier_subcontractor"><?php endif; ?>
                <?php wp_nonce_field( 'acdc_save_dossier_subcontractor' ); ?>
                <input type="hidden" name="registration_id" value="<?php echo esc_attr( (string) $registration->id ); ?>">
                <input type="hidden" name="dsc[id]" value="<?php echo esc_attr( $dsc_edit_item['id'] ?? '' ); ?>">
                <div class="acdc-contract-grid">
                  <div class="acdc-contract-label">Sous-traitant <span class="acdc-required">*</span></div>
                  <div>
                    <?php if ( ! empty( $sc_registry ) ) : ?>
                    <select name="dsc[nom]" class="acdc-input">
                      <option value="">— Sélectionner ou saisir ci-dessous —</option>
                      <?php foreach ( $sc_registry as $sc_r ) : ?>
                      <option value="<?php echo esc_attr( $sc_r['nom'] ?? '' ); ?>" <?php selected( ( $dsc_edit_item['nom'] ?? '' ), $sc_r['nom'] ?? '' ); ?>><?php echo esc_html( $sc_r['nom'] ?? '' ); ?></option>
                      <?php endforeach; ?>
                      <option value="__autre__" <?php selected( ! empty( $dsc_edit_item['nom'] ) && ! in_array( $dsc_edit_item['nom'], array_column( $sc_registry, 'nom' ), true ) ? $dsc_edit_item['nom'] : '', '__autre__' ); ?>>Autre (saisir manuellement)</option>
                    </select>
                    <input type="text" id="dsc_nom_libre_<?php echo (int) $registration->id; ?>" name="dsc[nom]" class="acdc-input" style="margin-top:6px;<?php echo ! empty( $dsc_edit_item['nom'] ) && ! empty( $sc_registry ) && ! in_array( $dsc_edit_item['nom'], array_column( $sc_registry, 'nom' ), true ) ? '' : 'display:none;'; ?>" placeholder="Nom du sous-traitant" value="<?php echo ! empty( $dsc_edit_item['nom'] ) && ! in_array( $dsc_edit_item['nom'], array_column( $sc_registry, 'nom' ), true ) ? esc_attr( $dsc_edit_item['nom'] ) : ''; ?>">
                    <script>
                    (function(){
                      var sel = document.querySelector('select[name="dsc[nom]"]');
                      var inp = document.getElementById('dsc_nom_libre_<?php echo (int) $registration->id; ?>');
                      if (!sel || !inp) return;
                      sel.addEventListener('change', function(){
                        if (sel.value === '__autre__') { inp.style.display=''; inp.required=true; inp.name='dsc[nom]'; sel.name='dsc[nom_sel]'; }
                        else { inp.style.display='none'; inp.required=false; inp.name='dsc[nom_libre]'; sel.name='dsc[nom]'; }
                      });
                    })();
                    </script>
                    <?php else : ?>
                    <input type="text" name="dsc[nom]" class="acdc-input" required value="<?php echo esc_attr( $dsc_edit_item['nom'] ?? '' ); ?>" placeholder="Nom du sous-traitant">
