                  <div><input type="date" name="dsc[date_fin]" class="acdc-input" value="<?php echo esc_attr( $dsc_edit_item['date_fin'] ?? '' ); ?>"></div>
                  <div class="acdc-contract-label">Montant HT (€)</div>
                  <div><input type="text" name="dsc[montant_ht]" class="acdc-input" value="<?php echo esc_attr( $dsc_edit_item['montant_ht'] ?? '' ); ?>" placeholder="Ex : 1200"></div>
