                  $del_url = wp_nonce_url( add_query_arg( array( 'action' => 'view', 'item_id' => (int) $registration->id, 'subtab' => 'compliance', 'dsc_pid_action' => 'delete', 'dsc_reg' => (int) $registration->id, 'dsc_pid' => rawurlencode( $diid ) ), is_admin() ? admin_url( 'admin-post.php?action=acdc_delete_dossier_subcontractor' ) : $this->portal_page_url( array( 'tab' => 'training_files', 'action' => 'view', 'item_id' => (int) $registration->id, 'subtab' => 'compliance', 'dsc_pid_action' => 'delete' ) ) ), 'acdc_delete_dossier_subcontractor_' . $diid );
                  $edit_url = add_query_arg( array( 'action' => 'view', 'item_id' => (int) $registration->id, 'subtab' => 'compliance', 'dsc_edit' => rawurlencode( $diid ) ), $dsc_base );
                  $today_ts = current_time( 'timestamp' );
                  $expired  = ! empty( $di['date_fin'] ) && strtotime( $di['date_fin'] ) < $today_ts;
                ?>
                <tr>
                  <td style="font-weight:600;"><?php echo esc_html( $di['nom'] ?? '' ); ?></td>
                  <td style="font-size:12px;color:#555;"><?php echo esc_html( $di['role'] ?? '—' ); ?></td>
                  <td style="font-size:12px;white-space:nowrap;">
                    <?php if ( $di['date_debut'] ?? '' ) echo esc_html( date_i18n( 'd/m/Y', strtotime( $di['date_debut'] ) ) ); ?>
                    <?php if ( $di['date_fin'] ?? '' ) : ?>
                    → <span style="<?php echo $expired ? 'color:#dc2626;font-weight:700;' : ''; ?>"><?php echo esc_html( date_i18n( 'd/m/Y', strtotime( $di['date_fin'] ) ) ); ?><?php echo $expired ? ' ⚠️' : ''; ?></span>
