  }  private function render_front_register_training_tab( $action, $item_id ) {
    // ACDC 3.25.31 — Route portal pour renvoi e-mail extranet (évite admin-post.php bloqué par WAF)
    if ( ! is_admin() && isset( $_GET['trf_action'] ) && 'resend_extranet' === $_GET['trf_action'] ) {
      $rid    = isset( $_GET['registration_id'] ) ? absint( wp_unslash( $_GET['registration_id'] ) ) : 0;
      $rnonce = isset( $_REQUEST['_wpnonce'] ) ? sanitize_text_field( wp_unslash( $_REQUEST['_wpnonce'] ) ) : '';
      if ( is_user_logged_in() && $this->is_admin_manager() && wp_verify_nonce( $rnonce, 'acdc_resend_learner_extranet_email_' . $rid ) ) {
        $this->handle_resend_learner_extranet_email();
      } else {
        $return = $this->portal_page_url( array( 'tab' => 'register_training', 'action' => 'edit', 'item_id' => $rid ) );
        wp_safe_redirect( add_query_arg( array( 'notice' => rawurlencode( 'Lien expiré. Veuillez réessayer.' ), 'notice_type' => 'error' ), $return ) );
        exit;
      }
    }
    if ( ! is_admin() && isset( $_GET['trf_action'] ) && 'delete_file' === $_GET['trf_action'] ) {
      $rid    = isset( $_GET['registration_id'] ) ? absint( wp_unslash( $_GET['registration_id'] ) ) : 0;
      $rnonce = isset( $_REQUEST['_wpnonce'] ) ? sanitize_text_field( wp_unslash( $_REQUEST['_wpnonce'] ) ) : '';
      if ( is_user_logged_in() && $this->is_admin_manager() && wp_verify_nonce( $rnonce, 'acdc_delete_training_file_' . $rid ) ) {
        $this->handle_delete_training_file( true );
      } else {
        wp_safe_redirect( $this->portal_page_url( array( 'tab' => 'trf_inscriptions', 'notice' => rawurlencode( 'Lien expiré. Veuillez réessayer.' ), 'notice_type' => 'error' ) ) );
        exit;
      }
    }
    if ( 'bulk_from_contract' === $action ) {
      $contract_id = isset( $_GET['contract_id'] ) ? absint( wp_unslash( $_GET['contract_id'] ) ) : 0;
      $registration = $this->get_training_registration_default_record();
      if ( $contract_id ) {
        $contract = $this->get_registration_contract( $contract_id );
        if ( $contract ) {
          global $wpdb;

          // Données de base depuis la convention
          $registration->autofill_contract_id    = (int) $contract->id;
          $registration->autofill_contract_label = (string) $contract->title;
          $registration->formation_id            = ! empty( $contract->formation_id ) ? (int) $contract->formation_id : 0;
          $registration->formation_title         = ! empty( $contract->formation_title ) ? (string) $contract->formation_title : '';
          $registration->company_id              = ! empty( $contract->company_id ) ? (int) $contract->company_id : 0;
          $registration->price_ht                = ! empty( $contract->price_ht ) ? (string) $contract->price_ht : '';
          $registration->source_prospect_id      = ! empty( $contract->source_prospect_id ) ? (int) $contract->source_prospect_id : 0;

          // Label entreprise
          if ( $registration->company_id ) {
            $co = $wpdb->get_row( $wpdb->prepare( "SELECT name FROM {$this->company_table} WHERE id = %d", $registration->company_id ) );
            if ( $co ) { $registration->company_label = (string) $co->name; }
          }

          // Apprenants depuis la convention (learner_ids)
          if ( ! empty( $contract->learner_ids ) ) {
            $registration->learner_ids = (string) $contract->learner_ids;
            $lids = array_values( array_filter( array_map( 'absint', explode( ',', $contract->learner_ids ) ) ) );
            // Vérifier que ces IDs existent bien dans learner_table
            $valid_lids = array();
            foreach ( $lids as $lid ) {
              $lr = $wpdb->get_row( $wpdb->prepare( "SELECT id, first_name, usage_last_name, last_name FROM {$this->learner_table} WHERE id = %d", $lid ) );
              if ( $lr ) {
                $valid_lids[] = (int) $lr->id;
                // Préremplir le premier apprenant valide trouvé
                if ( ! $registration->learner_id ) {
                  $registration->learner_id    = (int) $lr->id;
                  $registration->learner_label = trim( (string) $lr->first_name . ' ' . ( ! empty( $lr->usage_last_name ) ? $lr->usage_last_name : $lr->last_name ) );
                  $registration->belongs_to_group = 'Non';
                }
              }
            }
            $registration->learner_ids = implode( ',', $valid_lids );
          }

          // Formateur depuis la proposition liée (via source_prospect_id + formation_id)
          $proposal_table = $wpdb->prefix . 'acdc_of_proposals';
          if ( $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $proposal_table ) ) === $proposal_table ) {
            $proposal = null;
            if ( $registration->source_prospect_id && $registration->formation_id ) {
              $proposal = $wpdb->get_row( $wpdb->prepare(
                "SELECT trainer_ids FROM {$proposal_table} WHERE source_prospect_id = %d AND formation_id = %d ORDER BY created_at DESC LIMIT 1",
                $registration->source_prospect_id, $registration->formation_id
              ) );
            }
            if ( ! $proposal && $registration->source_prospect_id ) {
              $proposal = $wpdb->get_row( $wpdb->prepare(
                "SELECT trainer_ids FROM {$proposal_table} WHERE source_prospect_id = %d ORDER BY created_at DESC LIMIT 1",
                $registration->source_prospect_id
              ) );
            }
            if ( $proposal && ! empty( $proposal->trainer_ids ) ) {
              $tids = array_filter( array_map( 'absint', explode( ',', $proposal->trainer_ids ) ) );
              if ( ! empty( $tids ) ) {
                $first_tid = reset( $tids );
                $tr = $wpdb->get_row( $wpdb->prepare( "SELECT id, first_name, last_name FROM {$this->trainer_table} WHERE id = %d", $first_tid ) );
                if ( $tr ) {
                  $registration->trainer_id    = (int) $tr->id;
                  $registration->trainer_label = trim( (string) $tr->first_name . ' ' . (string) $tr->last_name );
                }
              }
            }
          }
        }
      }
      $this->render_front_training_registration_form( $registration, false );
      return;
    }
    if ( ! in_array( $action, array( 'new', 'edit', 'view' ), true ) ) {
      $action = 'new';
    }
    $registration = $item_id ? $this->get_training_registration( $item_id ) : null;
    if ( ! $registration ) {
      $registration = $this->get_training_registration_default_record();
    }
    $this->render_front_training_registration_form( $registration, 'view' === $action );
  }
  private function render_front_dashboard_tab() {
    global $wpdb;

    /* ---- Collecte des donn&#233;es ---- */
    $counts              = $this->get_counts();
    $survey_todo         = $this->get_dashboard_questionnaire_todo_counts();
    $qz_pending          = method_exists( $this, 'get_qz_pending_counts' ) ? $this->get_qz_pending_counts() : array( 'quiz' => 0, 'positioning' => 0, 'assessment' => 0 );
    $nad_pending         = method_exists( $this, 'nad_count_pending_analyses' ) ? (int) $this->nad_count_pending_analyses() : 0;

   /* Conventions en attente de signature */
    $sig_statuses = "'pending','sent','envoyée'";
    $sig_pending  = (int) $wpdb->get_var( "SELECT COUNT(*) FROM {$this->registration_contract_table} WHERE signature_status IN ($sig_statuses)" );
    $sig_overdue  = (int) $wpdb->get_var( $wpdb->prepare(
      "SELECT COUNT(*) FROM {$this->registration_contract_table} WHERE signature_status IN ($sig_statuses) AND signature_sent_at IS NOT NULL AND signature_sent_at < %s",
      date( 'Y-m-d H:i:s', strtotime( '-7 days' ) )
    ) );
    $prospect_overdue    = method_exists( $this, 'get_overdue_prospect_followup_count' ) ? (int) $this->get_overdue_prospect_followup_count() : 0;
    $prospect_inactive   = method_exists( $this, 'get_inactive_prospect_count' ) ? (int) $this->get_inactive_prospect_count( 10 ) : 0;

    /* ACDC 3.22.18 — H4 : Réclamations sans accusé de réception */
    $complaints_unack = 0;
    if ( ! empty( $this->complaint_table ) ) {
      $tbl_exists = $wpdb->get_var( $wpdb->prepare( 'SHOW TABLES LIKE %s', $this->complaint_table ) );
      if ( $tbl_exists ) {
        $complaints_unack = (int) $wpdb->get_var( 'SELECT COUNT(*) FROM ' . $this->complaint_table . ' WHERE acknowledged_at IS NULL' );
      }
    }

    /* Stats satisfaction (enquêtes à chaud) */
    $hot_stats = $this->get_survey_context_dashboard_stats( 'hot_survey', 0 );
    $satisfaction_score = $hot_stats['average_score'];
    $response_rate      = $hot_stats['response_rate'];

    /* Stats taux de r&#233;ussite &#233;valuations */
    $eval_rows  = $this->get_questionnaire_session_summary_rows( array( 'source_type' => 'evaluation' ) );
    $eval_stats = $this->get_questionnaire_session_stats_from_rows( $eval_rows );
    // ACDC 3.25.115 — taux de réussite réel (pass-rate évaluations), la clé success_rate n'existait pas.
    $eval_pass_row = $wpdb->get_row(
      "SELECT COUNT(*) AS total, SUM(CASE WHEN p.final_score IS NOT NULL AND p.final_score >= 70 THEN 1 ELSE 0 END) AS reussi
       FROM {$this->questionnaire_participant_table} p
       INNER JOIN {$this->questionnaire_session_table} s ON s.id = p.session_id
       WHERE s.source_type = 'evaluation' AND p.responded_at IS NOT NULL"
    );
    $success_rate = ( $eval_pass_row && (int) $eval_pass_row->total > 0 )
      ? (int) round( ( (int) $eval_pass_row->reussi / (int) $eval_pass_row->total ) * 100 )
      : null;

    /* Sessions &#224; venir (4 max) */
    $today = current_time( 'Y-m-d' );
    $upcoming_sessions = array();
    if ( ! empty( $this->session_table ) ) {
      $upcoming_sessions = (array) $wpdb->get_results( $wpdb->prepare(
        "SELECT s.*, f.title AS formation_title, f.duration AS formation_duration,
                (SELECT COUNT(*) FROM {$this->learner_table} l WHERE l.session_id = s.id) AS learner_count
         FROM {$this->session_table} s
         LEFT JOIN {$this->formation_table} f ON f.id = s.formation_id
         WHERE s.start_date >= %s
         ORDER BY s.start_date ASC, s.id ASC
         LIMIT 4",
        $today
      ) );
    }

    /* ACDC 3.21.67 — Expirations Qualiopi formateurs */
    $trainer_expiring_soon  = 0; // documents expirant dans 1-30 jours
    $trainer_expired        = 0; // documents déjà expirés (days <= 0)
    if ( method_exists( $this, 'get_acdc_qualiopi_upcoming_expirations' ) && ! empty( $this->trainer_table ) ) {
      $all_trainers = (array) $wpdb->get_results( "SELECT * FROM {$this->trainer_table}" );
      $now_ts = current_time( 'timestamp' );
      foreach ( $all_trainers as $tr ) {
        $expirations = $this->get_acdc_qualiopi_upcoming_expirations( $tr, 30 );
        foreach ( $expirations as $exp ) {
          $exp_ts = strtotime( (string) $exp['expires_at'] );
          if ( ! $exp_ts ) { continue; }
          $days_left = (int) floor( ( $exp_ts - $now_ts ) / DAY_IN_SECONDS );
          if ( $days_left < 0 ) {
            $trainer_expired++;
          } else {
            $trainer_expiring_soon++;
          }
        }
      }
    }

    /* ---- Définition des alertes (items > 0 uniquement) ---- */
    $all_alerts = array(
      array(
        'value'  => (int) $qz_pending['positioning'],
        'label'  => 'Tests de positionnement non trait&#233;s',
        'url'    => $this->portal_page_url( array( 'tab' => 'qz_results_positioning', 'qz_pending_only' => '1' ) ),
        'level'  => 'crit',
      ),
      array(
        'value'  => (int) $qz_pending['assessment'],
        'label'  => '&#201;valuations des acquis non trait&#233;es',
        'url'    => $this->portal_page_url( array( 'tab' => 'qz_results_assessment', 'qz_pending_only' => '1' ) ),
        'level'  => 'crit',
      ),
      array(
        'value'  => (int) $qz_pending['quiz'],
        'label'  => 'Quiz en attente de traitement',
        'url'    => $this->portal_page_url( array( 'tab' => 'qz_live' ) ),
        'level'  => 'warn',
      ),
      array(
        'value'  => $sig_overdue,
        'label'  => 'Signatures en retard (+ 7 jours)',
        'url'    => $this->portal_page_url( array( 'tab' => 'registration_contract' ) ),
        'level'  => 'crit',
      ),
      array(
        'value'  => $sig_pending,
        'label'  => 'Conventions en attente de signature',
        'url'    => $this->portal_page_url( array( 'tab' => 'registration_contract' ) ),
        'level'  => 'warn',
      ),
      array(
        'value'  => $nad_pending,
        'label'  => 'Analyses du besoin &#224; traiter',
        'url'    => $this->portal_page_url( array( 'tab' => 'need_analyses', 'nad_subtab' => 'alerts' ) ),
        'level'  => 'warn',
      ),
      array(
        'value'  => $prospect_overdue,
        'label'  => 'Prospects en suivi en retard',
        'url'    => $this->portal_page_url( array( 'tab' => 'prospect_followup', 'dashboard_alerts' => '1' ) ),
        'level'  => 'warn',
      ),
      array(
        'value'  => $prospect_inactive,
        'label'  => 'Prospects sans activité depuis 10 jours',
        'url'    => $this->portal_page_url( array( 'tab' => 'prospect_followup', 'inactive' => '1' ) ),
        'level'  => 'warn',
      ),
      array(
        'value'  => (int) $survey_todo['hot'],
        'label'  => 'Enqu&#234;tes &#224; chaud &#224; traiter',
        'url'    => $this->get_questionnaire_dashboard_results_url( 'hot_survey' ),
        'level'  => 'warn',
      ),
      array(
        'value'  => (int) $survey_todo['cold'],
        'label'  => 'Enqu&#234;tes &#224; froid &#224; traiter',
        'url'    => $this->get_questionnaire_dashboard_results_url( 'cold_survey' ),
        'level'  => 'warn',
      ),
      array(
        'value'  => (int) $survey_todo['mid'],
        'label'  => 'Enqu&#234;tes interm&#233;diaires &#224; traiter',
        'url'    => $this->get_questionnaire_dashboard_results_url( 'mid_survey' ),
        'level'  => 'warn',
      ),
      array(
        'value'  => (int) $survey_todo['trainer'],
        'label'  => 'Enqu&#234;tes formateur &#224; traiter',
        'url'    => $this->get_questionnaire_dashboard_results_url( 'trainer_survey' ),
        'level'  => 'warn',
      ),
      array(
        'value'  => (int) $survey_todo['company'],
        'label'  => 'Enqu&#234;tes entreprise &#224; traiter',
        'url'    => $this->get_questionnaire_dashboard_results_url( 'company_survey' ),
        'level'  => 'warn',
      ),
      array(
        'value'  => (int) $survey_todo['funder'],
        'label'  => 'Enquêtes financeur à traiter',
        'url'    => $this->get_questionnaire_dashboard_results_url( 'funder_survey' ),
        'level'  => 'warn',
      ),
      // ACDC 3.21.67 — Expirations Qualiopi formateurs
      array(
        'value'  => $trainer_expired,
        'label'  => 'Documents formateurs expirés',
        'url'    => $this->portal_page_url( array( 'tab' => 'trainers' ) ),
        'level'  => 'crit',
      ),
      array(
        'value'  => $trainer_expiring_soon,
        'label'  => 'Documents formateurs expirant dans 30 jours',
        'url'    => $this->portal_page_url( array( 'tab' => 'trainers' ) ),
        'level'  => 'warn',
      ),
      /* ACDC 3.22.18 — H4 : Réclamations sans accusé de réception (ind. 31 Qualiopi) */
      array(
        'value'  => $complaints_unack,
        'label'  => 'Réclamations sans accusé de réception (ind. 31)',
        'url'    => $this->portal_page_url( array( 'tab' => 'complaints', 'cpl_filter' => 'unack' ) ),
        'level'  => 'crit',
      ),
    );

    /* Ne garder que les alertes actives (valeur > 0) */
    $active_alerts = array_values( array_filter( $all_alerts, function( $a ) {
      return $a['value'] > 0;
    } ) );

    /* Workflow complet pour la checklist (tous items, toujours affich&#233;s) */
    $workflow_items = array(
      array( 'label' => '&#201;margement',            'value' => 0,                          'tab' => 'quality' ),
      array( 'label' => 'Quiz',                       'value' => (int) $qz_pending['quiz'],  'tab' => 'qz_live' ),
      array( 'label' => 'Tests de positionnement',    'value' => (int) $qz_pending['positioning'], 'tab' => 'qz_results_positioning' ),
      array( 'label' => '&#201;valuations des acquis','value' => (int) $qz_pending['assessment'],  'tab' => 'qz_results_assessment' ),
      array( 'label' => 'Analyses du besoin',         'value' => $nad_pending,               'tab' => 'need_analyses' ),
      array( 'label' => 'Convention / Contrat',       'value' => $sig_pending,               'tab' => 'registration_contract' ),
      array( 'label' => 'Convocation',                'value' => 0,                          'tab' => 'documents' ),
      array( 'label' => 'Enqu&#234;tes (toutes)',     'value' => array_sum( array_values( $survey_todo ) ), 'tab' => 'hot_surveys' ),
      array( 'label' => 'Doc. fin de formation',      'value' => 0,                          'tab' => 'documents' ),
    );

    /* KPIs Qualiopi (statut vert/orange) */
    $qualiopi_status = array(
      array( 'label' => 'Enqu&#234;tes &#224; chaud',   'ok' => $hot_stats['responses'] > 0 && $hot_stats['response_rate'] !== null && (int) $hot_stats['response_rate'] >= 50 ),
      array( 'label' => '&#201;margement',               'ok' => true ),
      array( 'label' => 'Tests positionnement',          'ok' => (int) $qz_pending['positioning'] === 0 ),
      array( 'label' => 'Enqu&#234;tes &#224; froid',   'ok' => (int) $survey_todo['cold'] === 0 ),
    );

    /* URLs utiles */
    $base_url   = is_admin() ? admin_url( 'admin.php?page=acdc-of-dashboard' ) : $this->portal_page_url( array() );
    $stats_url  = $this->portal_page_url( array( 'tab' => 'statistics_performance' ) );
    $sessions_url = $this->portal_page_url( array( 'tab' => 'sessions' ) );
    $audit_url  = $this->portal_page_url( array( 'tab' => 'audit' ) );
    ?>

