  }  private function render_front_need_analyses_tab( $action, $item_id ) {
    // ACDC 3.21.13-hotfix2 — Afficher les notices de création NAD si présentes
    global $wpdb;
    $nad_notices = $wpdb->get_col( "SELECT option_name FROM {$wpdb->options} WHERE option_name LIKE '_transient_acdc_nad_creation_notice_%'" );
    foreach ( $nad_notices as $opt_name ) {
      $key = str_replace( '_transient_', '', $opt_name );
      $msg = get_transient( $key );
      if ( $msg ) {
        $is_warning = strpos( $msg, '⚠️' ) !== false;
        echo '<div class="acdc-notice ' . ( $is_warning ? 'acdc-notice-warning' : 'acdc-notice-success' ) . '" style="margin-bottom:16px;">' . esc_html( $msg ) . '</div>';
        delete_transient( $key );
      }
    }

    // Routing sous-onglet nad_subtab (paramètre prefixé — jamais 'tab' brut).
    $nad_subtab  = isset( $_GET['nad_subtab'] )  ? sanitize_text_field( wp_unslash( $_GET['nad_subtab'] ) )  : '';
    $nad_block_id= isset( $_GET['nad_block_id'] )? absint( wp_unslash( $_GET['nad_block_id'] ) ) : 0;
    $base_url    = is_admin() ? admin_url( 'admin.php?page=acdc-of-need-analyses' ) : $this->portal_page_url( array( 'tab' => 'need_analyses' ) );

    /* ACDC 3.25.239 — LE SOUS-ONGLET « ALERTES » NE S'OUVRAIT JAMAIS.
       Son routage était écrit tout en haut de la méthode, AVANT les trois
       lignes ci-dessus qui définissent $nad_subtab et $base_url. La comparaison
       portait donc sur une variable inexistante — toujours fausse — et le lien
       du menu retombait silencieusement sur la liste des analyses. Défaut
       antérieur à mes livraisons, révélé par l'analyse statique. Le routage
       rejoint ici ses semblables, après la définition de ce qu'il lit. */
    if ( 'alerts' === $nad_subtab ) {
      $this->render_nad_alerts_tab( $base_url );
      return;
    }

    // ACDC 3.21.29-hotfix4 — Renvoi manuel via portail (évite le passage par wp-admin/admin-post.php).
    if ( isset( $_GET['nad_action'] ) && 'resend' === $_GET['nad_action'] && isset( $_GET['nad_id'] ) ) {
      $rid = absint( $_GET['nad_id'] );
      $rnonce = isset( $_REQUEST['_wpnonce'] ) ? sanitize_text_field( wp_unslash( $_REQUEST['_wpnonce'] ) ) : '';
      if ( is_user_logged_in() && wp_verify_nonce( $rnonce, 'acdc_nad_resend_' . $rid ) ) {
        $this->handle_nad_resend_inline( $rid, $base_url );
      } else {
        wp_safe_redirect( add_query_arg( array( 'notice' => rawurlencode( 'Lien expiré. Veuillez réessayer.' ), 'notice_type' => 'error' ), $base_url ) );
        exit;
      }
    }

    // ACDC 3.21.29-hotfix4b — Suppression de question de bloc via portail.
    if ( isset( $_GET['nad_action'] ) && 'delete_question' === $_GET['nad_action'] && isset( $_GET['nad_question_id'] ) ) {
      $qid     = absint( $_GET['nad_question_id'] );
      $bid     = isset( $_GET['nad_block_id'] ) ? absint( $_GET['nad_block_id'] ) : 0;
      $qnonce  = isset( $_REQUEST['_wpnonce'] ) ? sanitize_text_field( wp_unslash( $_REQUEST['_wpnonce'] ) ) : '';
      if ( current_user_can( 'manage_options' ) && wp_verify_nonce( $qnonce, 'acdc_delete_need_question_' . $qid ) ) {
        global $wpdb;
        $q = $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$this->need_question_table} WHERE id = %d", $qid ) );
        if ( $q ) {
          $wpdb->delete( $this->need_question_table, array( 'id' => $qid ) );
          $bloc_id_redir = $bid ?: (int) $q->bloc_id;
          wp_safe_redirect( add_query_arg( array( 'nad_subtab' => 'block_detail', 'nad_block_id' => $bloc_id_redir, 'notice' => rawurlencode( 'Question supprimée.' ), 'notice_type' => 'success' ), $base_url ) );
        } else {
          wp_safe_redirect( add_query_arg( array( 'nad_subtab' => 'blocks', 'notice' => rawurlencode( 'Question introuvable.' ), 'notice_type' => 'error' ), $base_url ) );
        }
        exit;
      } else {
        wp_safe_redirect( add_query_arg( array( 'notice' => rawurlencode( 'Action non autorisée.' ), 'notice_type' => 'error' ), $base_url ) );
        exit;
      }
    }

    // ---- Sous-écrans bibliothèque ----
    if ( 'blocks' === $nad_subtab || 'block_new' === $nad_subtab || 'block_edit' === $nad_subtab ) {
      $this->render_nad_blocks_list( $base_url, $nad_subtab, $nad_block_id );
      return;
    }
    if ( 'block_detail' === $nad_subtab || 'question_new' === $nad_subtab || 'question_edit' === $nad_subtab ) {
      $this->render_nad_block_detail( $base_url, $nad_subtab, $nad_block_id );
      return;
    }

    // ---- Écran principal — liste des analyses ----
    $search   = isset( $_GET['q'] ) ? sanitize_text_field( wp_unslash( $_GET['q'] ) ) : '';
    $analyses = $this->get_need_analyses( $search, true );
    $analysis = $item_id ? $this->get_need_analysis( $item_id ) : null;
    $profils_map    = array( 'particulier' => 'Particulier', 'apprenant' => 'Apprenant', 'salarie' => 'Salarié', 'entreprise' => 'Entreprise', 'independant' => 'Indépendant' );
    $thematiques_map= $this->get_thematiques_map();
    $statuts_map    = array( 'brouillon' => 'Brouillon', 'nouveau' => 'Nouveau', 'a_traiter' => 'À traiter', 'traite' => 'Traité', 'archive' => 'Archivé', 'expire' => 'Expiré' );
    ?>
    <section class="acdc-section-head">
      <div>
        <?php if ( 'view' === $action ) : ?>
          <h2>Voir l'analyse du besoin</h2>
          <p>Consultation des réponses et de l'historique des actions.</p>
        <?php elseif ( 'edit' === $action ) : ?>
          <h2>Modifier l'analyse du besoin</h2>
          <p>Modification des paramètres et des blocs de l'analyse.</p>
        <?php elseif ( 'new' === $action ) : ?>
          <h2>Créer une analyse du besoin</h2>
          <p>Définissez les blocs et les sources liées à cette analyse.</p>
        <?php else : ?>
          <h2>Analyses du besoin</h2>
          <p>Création, consultation et modification des analyses du besoin.</p>
        <?php endif; ?>
      </div>
      <div class="acdc-inline-wrap">
        <?php if ( in_array( $action, array( 'view', 'edit', 'new' ), true ) ) : ?>
          <a class="acdc-button acdc-button-soft" href="<?php echo esc_url( $base_url ); ?>">← Retour à la liste</a>
        <?php else : ?>
          <a class="acdc-button acdc-button-soft" href="<?php echo esc_url( add_query_arg( array( 'nad_subtab' => 'blocks' ), $base_url ) ); ?>">Bibliothèque des blocs</a>
          <button type="button" class="acdc-button acdc-button-soft" data-acdc-open-modal="acdc-create-need-analysis-from-model-modal">Créer depuis le modèle</button>
          <a class="acdc-button acdc-button-primary" href="<?php echo esc_url( add_query_arg( array( 'action' => 'new' ), $base_url ) ); ?>">Créer une analyse du besoin</a>
        <?php endif; ?>
      </div>
    </section>
    <?php if ( in_array( $action, array( 'new', 'edit', 'view' ), true ) ) : ?>
      <?php $this->render_front_need_analysis_form( $analysis, 'view' === $action ); ?>
    <?php endif; ?>
    <?php if ( ! in_array( $action, array( 'new', 'edit', 'view' ), true ) ) : ?>
    <div class="acdc-panel acdc-mb-18">
      <form method="get" action="">
        <?php if ( is_admin() ) : ?><input type="hidden" name="page" value="acdc-of-need-analyses"><?php endif; ?>
        <input type="hidden" name="tab" value="need_analyses">
        <div class="acdc-inline-wrap acdc-inline-wrap-center">
          <input type="search" name="q" value="<?php echo esc_attr( $search ); ?>" placeholder="Rechercher" style="max-width:420px;">
          <button type="submit" class="acdc-button acdc-button-soft">Rechercher</button>
        </div>
      </form>
    </div>
    <div class="acdc-panel">
      <div class="acdc-table-wrap" style="overflow-x:auto;">
        <table class="acdc-table acdc-nad-analyses-table" style="min-width:1400px;">
          <thead>
            <tr>
              <th style="min-width:800px;">Intitulé</th>
              <th>Profil</th>
              <th>Thématique</th>
              <th>Statut</th>
              <th>Source</th>
              <th style="white-space:nowrap;">Envoyé le</th>
              <th style="white-space:nowrap;">Prochain envoi</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
          <?php if ( ! empty( $analyses ) ) : foreach ( $analyses as $entry ) :
            $e_profil     = ! empty( $entry->profil )     ? ( isset( $profils_map[ $entry->profil ] )     ? $profils_map[ $entry->profil ]     : esc_html( $entry->profil ) )     : ( ! empty( $entry->analysis_type ) ? esc_html( $entry->analysis_type ) : '—' );
            $e_thematique = ! empty( $entry->thematique ) ? ( isset( $thematiques_map[ $entry->thematique ] ) ? $thematiques_map[ $entry->thematique ] : esc_html( $entry->thematique ) ) : '—';
            $e_statut     = ! empty( $entry->statut )     ? ( isset( $statuts_map[ $entry->statut ] )     ? $statuts_map[ $entry->statut ]     : esc_html( $entry->statut ) )     : ( (int) $entry->is_model ? 'Modèle' : '—' );
            $e_source     = ! empty( $entry->source_type ) ? ucfirst( $entry->source_type ) : ( (int) $entry->is_model ? 'Modèle' : 'Manuel' );
            $badge_class  = array( 'brouillon' => 'is-draft', 'nouveau' => 'is-info', 'a_traiter' => 'is-warning', 'traite' => 'is-success', 'archive' => 'is-muted', 'expire' => 'is-error' );
            $bc = isset( $badge_class[ $entry->statut ] ) ? $badge_class[ $entry->statut ] : 'is-draft';
            // ACDC 3.21.29-hotfix4 — Données enrichies
            $nad_badge_classes = array( 'brouillon' => 'quality-neutral', 'nouveau' => 'info', 'a_traiter' => 'warning', 'traite' => 'success', 'archive' => 'quality-neutral' );
            $bc_pill      = isset( $nad_badge_classes[ $entry->statut ] ) ? $nad_badge_classes[ $entry->statut ] : 'quality-neutral';
            $e_dest_nom   = trim( ( (string) ( $entry->repondant_prenom ?? '' ) ) . ' ' . ( (string) ( $entry->repondant_nom ?? '' ) ) );
            $e_dest_email = ! empty( $entry->repondant_email ) ? (string) $entry->repondant_email : '';
            $r1 = ! empty( $entry->relance_1_at );
            $r2 = ! empty( $entry->relance_2_at );
            $r3 = ! empty( $entry->relance_3_at );
            // Dernier envoi réel : le plus récent parmi sent_at et les relances
            $all_dates = array_filter( array(
              $entry->sent_at       ?? '',
              $entry->relance_1_at  ?? '',
              $entry->relance_2_at  ?? '',
              $entry->relance_3_at  ?? '',
            ) );
            $last_sent_raw = ! empty( $all_dates ) ? max( $all_dates ) : '';
            $e_sent        = $last_sent_raw ? mysql2date( 'j M Y', $last_sent_raw ) : '';
            // Compteur : envoi initial (sent_at) + relances, plafonné à 3
            $nb_relances   = min( 3, ( ! empty( $entry->sent_at ) ? 1 : 0 ) + (int) $r1 + (int) $r2 + (int) $r3 );
            $e_prochain   = '';
            if ( empty( $entry->sent_at ) && ! empty( $entry->scheduled_send_at ) ) {
              $e_prochain = mysql2date( 'j M Y', $entry->scheduled_send_at );
            }
            $resend_url = '';
            if ( 'traite' !== $entry->statut && ! empty( $entry->repondant_email ) ) {
              $resend_base = is_admin()
                ? admin_url( 'admin.php?page=acdc-of-need-analyses' )
                : $this->portal_page_url( array( 'tab' => 'need_analyses' ) );
              $resend_url = wp_nonce_url(
                add_query_arg( array( 'nad_action' => 'resend', 'nad_id' => (int) $entry->id ), $resend_base ),
                'acdc_nad_resend_' . (int) $entry->id
              );
            }
            $nad_statut_filter = isset( $_GET['nad_statut'] ) ? sanitize_text_field( wp_unslash( $_GET['nad_statut'] ) ) : '';
            if ( $nad_statut_filter && $entry->statut !== $nad_statut_filter ) { continue; }
            ?>
            <tr>
              <td style="min-width:800px;max-width:800px;">
                <a href="<?php echo esc_url( add_query_arg( array( 'action' => 'view', 'item_id' => (int) $entry->id ), $base_url ) ); ?>" style="color:#0f2c52;text-decoration:none;"><?php echo esc_html( $entry->title ); ?></a>
                <?php echo (int) $entry->is_model ? ' <em style="color:#8a6d2a;font-size:11px;">(modèle)</em>' : ''; ?>
                <?php if ( $e_dest_nom || $e_dest_email || ! empty( $entry->company_name ) ) : ?>
                  <div style="margin-top:3px;">
                    <?php if ( ! empty( $entry->company_name ) ) : ?>
                      <span style="font-size:12px;color:#0f2c52;font-weight:600;"><?php echo esc_html( $entry->company_name ); ?></span>
                      <?php if ( $e_dest_nom || $e_dest_email ) : ?><br><?php endif; ?>
                    <?php endif; ?>
                    <?php if ( $e_dest_nom ) : ?><span style="font-size:12px;color:#4b5d76;"><?php echo esc_html( $e_dest_nom ); ?></span><?php endif; ?>
                    <?php if ( $e_dest_email ) : ?><span style="font-size:11px;color:#8a6d2a;margin-left:6px;"><?php echo esc_html( $e_dest_email ); ?></span><?php endif; ?>
                  </div>
                <?php endif; ?>
              </td>
              <td><?php echo esc_html( $e_profil ); ?></td>
              <td><?php echo esc_html( $e_thematique ); ?></td>
              <td><span class="acdc-badge <?php echo esc_attr( $bc_pill ); ?>" style="margin-bottom:0;"><?php echo esc_html( $e_statut ); ?></span></td>
              <td><?php echo esc_html( $e_source ); ?></td>
              <td style="font-size:13px;white-space:nowrap;">
                <?php if ( $e_sent ) : ?>
                  <?php echo esc_html( $e_sent ); ?>
                  <?php if ( $nb_relances > 0 ) : ?><br><span style="font-size:11px;color:#8a6d2a;font-weight:600;"><?php echo $nb_relances; ?>/3 relances</span><?php endif; ?>
                <?php else : ?>—<?php endif; ?>
              </td>
              <td style="font-size:13px;white-space:nowrap;">
                <?php if ( $e_prochain ) : ?>
                  <span style="color:#c2410c;font-weight:600;"><?php echo esc_html( $e_prochain ); ?></span>
                <?php elseif ( 'a_traiter' === $entry->statut && $e_sent ) : ?>
                  <span style="font-size:11px;color:#6b7280;">Auto (48h)</span>
                <?php else : ?>—<?php endif; ?>
              </td>
              <td>
                <div class="acdc-groups-actions-inline">
                  <a class="acdc-row-action-icon acdc-row-view-link" href="<?php echo esc_url( add_query_arg( array( 'action' => 'view', 'item_id' => (int) $entry->id ), $base_url ) ); ?>" title="Voir" aria-label="Voir l'analyse du besoin" data-acdc-iconized="1">
                    <?php echo $this->render_inline_icon( 'eye', 25 ); ?>
                    <span class="acdc-action-hub-sr screen-reader-text">Voir</span>
                  </a>
                  <a class="acdc-row-action-icon acdc-row-edit-link" href="<?php echo esc_url( add_query_arg( array( 'action' => 'edit', 'item_id' => (int) $entry->id ), $base_url ) ); ?>" title="Modifier" aria-label="Modifier l'analyse du besoin" data-acdc-iconized="1">
                    <?php echo $this->render_inline_icon( 'edit', 25 ); ?>
                    <span class="acdc-action-hub-sr screen-reader-text">Modifier</span>
                  </a>
                  <?php if ( $resend_url ) : ?>
                  <a class="acdc-row-action-icon" href="<?php echo esc_url( $resend_url ); ?>" title="Renvoyer manuellement" aria-label="Renvoyer l'analyse du besoin" data-acdc-iconized="1" onclick="return confirm('Envoyer une relance pour cette analyse ?');">
                    <?php echo $this->render_inline_icon( 'send', 25 ); ?>
                    <span class="acdc-action-hub-sr screen-reader-text">Renvoyer</span>
                  </a>
                  <?php endif; ?>
                  <a class="acdc-row-action-icon acdc-row-delete-link" href="<?php echo esc_url( wp_nonce_url( admin_url( 'admin-post.php?action=acdc_delete_need_analysis&analysis_id=' . (int) $entry->id . ( is_admin() ? '&page=acdc-of-need-analyses' : '' ) ), 'acdc_delete_need_analysis_' . (int) $entry->id ) ); ?>" title="Supprimer" aria-label="Supprimer l'analyse du besoin" onclick="return confirm('Supprimer cette analyse du besoin ?');" data-acdc-iconized="1">
                    <?php echo $this->render_inline_icon( 'trash', 25 ); ?>
                    <span class="acdc-action-hub-sr screen-reader-text">Supprimer</span>
                  </a>
                </div>
              </td>
            </tr>
          <?php endforeach; else : ?>
            <tr><td colspan="8">Aucune analyse du besoin enregistrée.</td></tr>
          <?php endif; ?>
          </tbody>
        </table>
      </div>
    </div>
    <?php if ( 'list' === $action ) : ?>
    <div class="acdc-modal-shell" id="acdc-create-need-analysis-from-model-modal" hidden>
      <div class="acdc-modal-backdrop" data-acdc-close-modal></div>
      <div class="acdc-modal-dialog acdc-modal-dialog-medium">
        <div class="acdc-modal-header"><h4>Créer depuis le modèle</h4><button type="button" class="acdc-modal-close" data-acdc-close-modal>&times;</button></div>
        <div class="acdc-modal-body acdc-pad-24">
          <form class="acdc-form acdc-contract-builder-form" method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>">
            <?php wp_nonce_field( 'acdc_create_need_analysis_from_model' ); ?>
            <input type="hidden" name="action" value="acdc_create_need_analysis_from_model">
            <?php if ( is_admin() ) : ?><input type="hidden" name="page" value="acdc-of-need-analyses"><?php endif; ?>
            <p><label>Profil concerné *</label>
              <select name="analysis_profil" required>
                <option value="">Choisir un profil</option>
                <option value="particulier">Particulier</option>
                <option value="apprenant">Apprenant</option>
                <option value="salarie">Salarié</option>
                <option value="entreprise">Entreprise</option>
                <option value="independant">Indépendant</option>
              </select></p>
            <p><label>Thématique de formation *</label>
              <select name="analysis_thematique" required>
                <option value="">Choisir une thématique</option>
                <?php foreach ( $this->get_thematiques_map() as $_tv => $_tl ) : ?>
                <option value="<?php echo esc_attr($_tv); ?>"><?php echo esc_html($_tl); ?></option>
                <?php endforeach; ?>
              </select></p>
            <p><label>Formation liée (facultatif)</label>
              <?php
              global $wpdb;
              $formations = $wpdb->get_results( "SELECT id, title FROM {$wpdb->prefix}acdc_of_formations ORDER BY title ASC LIMIT 200" );
              ?>
              <select name="analysis_formation_id">
                <option value="">Aucune</option>
                <?php foreach ( $formations as $f ) : ?>
                  <option value="<?php echo (int) $f->id; ?>"><?php echo esc_html( $f->title ); ?></option>
                <?php endforeach; ?>
              </select></p>
            <!-- ACDC 3.21.11 — Sources liées dès la création -->
            <p><label>Prospect source (optionnel)</label>
              <select name="modal_source_prospect">
                <option value="">— Aucun —</option>
                <?php
                $md_prospects = $wpdb->get_results( "SELECT id, CONCAT(first_name,' ',last_name) AS label, email FROM {$wpdb->prefix}acdc_of_prospects ORDER BY last_name ASC LIMIT 300" );
                foreach ( $md_prospects as $_p ) : ?>
                  <option value="<?php echo (int)$_p->id; ?>"><?php echo esc_html(trim($_p->label)); ?><?php if($_p->email) echo ' — '.esc_html($_p->email); ?></option>
                <?php endforeach; ?>
              </select></p>
            <p><label>Apprenant (optionnel)</label>
              <select name="modal_apprenant_id">
                <option value="">— Aucun —</option>
                <?php
                $md_apprenants = $wpdb->get_results( "SELECT id, CONCAT(first_name,' ',last_name) AS label, email FROM {$wpdb->prefix}acdc_of_learners ORDER BY last_name ASC LIMIT 300" );
                foreach ( $md_apprenants as $_a ) : ?>
                  <option value="<?php echo (int)$_a->id; ?>"><?php echo esc_html(trim($_a->label)); ?><?php if($_a->email) echo ' — '.esc_html($_a->email); ?></option>
                <?php endforeach; ?>
              </select></p>
            <p><label>Entreprise commanditaire (optionnel)</label>
              <select name="modal_entreprise_id">
                <option value="">— Aucune —</option>
                <?php
                $md_entreprises = $wpdb->get_results( "SELECT id, name AS label FROM {$wpdb->prefix}acdc_of_companies ORDER BY name ASC LIMIT 300" );
                foreach ( $md_entreprises as $_e ) : ?>
                  <option value="<?php echo (int)$_e->id; ?>"><?php echo esc_html($_e->label); ?></option>
                <?php endforeach; ?>
              </select></p>
            <p class="acdc-actions-end acdc-mt-18">
              <button type="button" class="acdc-button acdc-button-soft" data-acdc-close-modal>Annuler</button>
              <button type="submit" class="acdc-button acdc-button-primary">Créer l'analyse</button>
            </p>
          </form>
        </div>
      </div>
    </div>
    <?php endif; ?>
    <?php endif; // Fin masquage liste en mode vue/édition/nouveau ?>
    <?php
  }

