  private function render_nad_alerts_tab( $base_url ) {
    $notice      = isset( $_GET['notice'] )      ? sanitize_text_field( wp_unslash( $_GET['notice'] ) )      : '';
    $notice_type = isset( $_GET['notice_type'] ) ? sanitize_text_field( wp_unslash( $_GET['notice_type'] ) ) : 'success';
    $analyses    = $this->nad_get_alert_analyses();
    $them_map    = $this->get_thematiques_map();
    $profils_map = array( 'particulier' => 'Particulier', 'apprenant' => 'Apprenant', 'salarie' => 'Salarié', 'entreprise' => 'Entreprise', 'independant' => 'Indépendant' );
    ?>
    <section class="acdc-section-head">
      <div>
        <h2>Analyses du besoin &mdash; En attente</h2>
        <p>Analyses envoyées mais non encore soumises par les destinataires. Relancez en un clic.</p>
      </div>
      <a class="acdc-button acdc-button-soft" href="<?php echo esc_url( $base_url ); ?>">&#8592; Toutes les analyses</a>
    </section>
    <?php if ( $notice ) : ?>
      <div class="acdc-notice <?php echo 'error' === $notice_type ? 'acdc-notice-error' : 'acdc-notice-success'; ?>"><?php echo esc_html( $notice ); ?></div>
    <?php endif; ?>
    <div class="acdc-panel">
      <?php if ( empty( $analyses ) ) : ?>
        <div style="padding:48px;text-align:center;">
          <div style="font-size:40px;margin-bottom:12px;">✓</div>
          <p style="color:#0f2c52;font-weight:700;font-size:16px;margin:0 0 6px;">Aucune analyse en attente</p>
          <p style="color:#4b5d76;font-size:14px;">Toutes les analyses ont ete soumises ou ne sont pas encore envoyees.</p>
        </div>
      <?php else : ?>
      <div class="acdc-table-wrap" style="overflow-x:auto;">
        <table class="acdc-table" style="min-width:1100px;">
          <thead>
            <tr>
              <th>Envoye le</th>
              <th>Intitule</th>
              <th>Destinataire</th>
              <th>Profil</th>
              <th>Thematique</th>
              <th>Statut</th>
              <th style="text-align:center;">1re relance</th>
              <th style="text-align:center;">2e relance</th>
              <th style="text-align:center;">3e relance</th>
              <th style="text-align:center;">Action</th>
            </tr>
          </thead>
          <tbody>
          <?php foreach ( $analyses as $a ) :
            $r1 = ! empty( $a->relance_1_at );
            $r2 = ! empty( $a->relance_2_at );
            $r3 = ! empty( $a->relance_3_at );
            $all_sent = $r1 && $r2 && $r3;
            $statut_labels = array( 'brouillon' => 'Brouillon', 'nouveau' => 'Envoye - en attente', 'a_traiter' => 'Relance', 'traite' => 'Soumis', 'archive' => 'Archive' );
            $statut_dots   = array( 'nouveau' => 'is-info', 'a_traiter' => 'is-warning', 'traite' => 'is-success', 'brouillon' => 'is-draft', 'archive' => 'is-muted', 'expire' => 'is-error' );
            $st_label = isset( $statut_labels[ $a->statut ] ) ? $statut_labels[ $a->statut ] : ucfirst( (string) $a->statut );
            $st_dot   = isset( $statut_dots[ $a->statut ] )   ? $statut_dots[ $a->statut ]   : 'is-info';
            $relance_num = ! $r1 ? 1 : ( ! $r2 ? 2 : ( ! $r3 ? 3 : 0 ) );
            $relance_url = $relance_num ? wp_nonce_url(
              add_query_arg( array( 'action' => 'acdc_nad_manual_relance', 'analysis_id' => (int) $a->id ), admin_url( 'admin-post.php' ) ),
              'acdc_nad_manual_relance_' . (int) $a->id
            ) : '';
          ?>
            <tr<?php echo $all_sent ? ' style="opacity:.55;"' : ''; ?>>
              <td style="white-space:nowrap;font-size:13px;"><?php echo $a->sent_at ? esc_html( mysql2date( 'd/m/Y', $a->sent_at ) ) : '&mdash;'; ?></td>
              <td><a href="<?php echo esc_url( add_query_arg( array( 'action' => 'view', 'item_id' => (int) $a->id ), $base_url ) ); ?>" style="color:#0f2c52;font-weight:600;text-decoration:none;font-size:13px;"><?php echo esc_html( mb_strimwidth( (string)$a->title, 0, 55, '...' ) ); ?></a></td>
              <td style="font-size:13px;">
                <?php echo esc_html( trim( ( (string)($a->repondant_prenom ?? '') ) . ' ' . ( (string)($a->repondant_nom ?? '') ) ) ); ?>
                <?php if ( ! empty( $a->repondant_email ) ) : ?><div style="color:#8a6d2a;font-size:11px;"><?php echo esc_html( $a->repondant_email ); ?></div><?php endif; ?>
              </td>
              <td style="font-size:13px;"><?php echo ! empty( $a->profil ) ? esc_html( $profils_map[ $a->profil ] ?? $a->profil ) : '&mdash;'; ?></td>
              <td style="font-size:13px;"><?php echo ! empty( $a->thematique ) ? esc_html( $them_map[ $a->thematique ] ?? $a->thematique ) : '&mdash;'; ?></td>
              <td><span class="acdc-doc-dot <?php echo esc_attr( $st_dot ); ?>"></span><?php echo esc_html( $st_label ); ?></td>
              <td style="text-align:center;font-size:12px;white-space:nowrap;"><?php echo $r1 ? '<span style="color:#8a6d2a;font-weight:600;">' . esc_html( mysql2date( 'd/m/Y', $a->relance_1_at ) ) . '</span>' : '<span style="color:#b0b8c4;">&mdash;</span>'; ?></td>
              <td style="text-align:center;font-size:12px;white-space:nowrap;"><?php echo $r2 ? '<span style="color:#8a6d2a;font-weight:600;">' . esc_html( mysql2date( 'd/m/Y', $a->relance_2_at ) ) . '</span>' : '<span style="color:#b0b8c4;">&mdash;</span>'; ?></td>
              <td style="text-align:center;font-size:12px;white-space:nowrap;"><?php echo $r3 ? '<span style="color:#8a6d2a;font-weight:600;">' . esc_html( mysql2date( 'd/m/Y', $a->relance_3_at ) ) . '</span>' : '<span style="color:#b0b8c4;">&mdash;</span>'; ?></td>
              <td style="text-align:center;">
                <?php if ( $relance_num && $relance_url ) : ?>
                  <a href="<?php echo esc_url( $relance_url ); ?>" class="acdc-button acdc-button-soft" style="padding:6px 12px;height:auto;font-size:12px;font-weight:700;">&#8635; Relance <?php echo $relance_num; ?></a>
                <?php elseif ( $all_sent ) : ?>
                  <span style="color:#b0b8c4;font-size:12px;">3/3 envoyees</span>
                <?php endif; ?>
              </td>
            </tr>
          <?php endforeach; ?>
          </tbody>
        </table>
      </div>
      <div style="padding:12px 20px;border-top:1px solid #f0e6dc;font-size:12px;color:#4b5d76;">
        <?php echo count( $analyses ); ?> analyse(s) en attente &middot; Les relances automatiques partent 48h apres le dernier envoi.
      </div>
      <?php endif; ?>
    </div>
    <?php
  }

  private function render_nad_blocks_list( $base_url, $nad_subtab, $nad_block_id ) {
    $notice      = isset( $_GET['notice'] )      ? sanitize_text_field( wp_unslash( $_GET['notice'] ) )      : '';
    $notice_type = isset( $_GET['notice_type'] ) ? sanitize_text_field( wp_unslash( $_GET['notice_type'] ) ) : 'success';
    $filter_type = isset( $_GET['filter_type'] ) ? sanitize_text_field( wp_unslash( $_GET['filter_type'] ) ) : '';
    $blocks = $this->get_need_blocks( '' !== $filter_type ? array( 'type_bloc' => $filter_type ) : array() );
    $types = array( '' => 'Tous les blocs', 'commun' => 'Communs', 'profil' => 'Par profil', 'thematique' => 'Par thématique', 'formation' => 'Par formation', 'personnalise' => 'Personnalisés' );
    ?>
    <section class="acdc-section-head">
      <div>
        <h2>Bibliothèque des blocs</h2>
        <p>Blocs de questions modulaires — communs, profils, thématiques et personnalisés.</p>
      </div>
      <div class="acdc-inline-wrap">
        <a class="acdc-button acdc-button-soft" href="<?php echo esc_url( $base_url ); ?>">← Retour aux analyses</a>
        <a class="acdc-button acdc-button-soft" href="<?php echo esc_url( wp_nonce_url( add_query_arg( array( 'nad_subtab' => 'blocks', 'nad_reset_blocs' => '1' ), $base_url ), 'acdc_reset_nad_system_blocs' ) ); ?>" onclick="return confirm('Réinitialiser tous les blocs et questions système ? Les blocs personnalisés ne seront pas affectés.');">↺ Réinitialiser les blocs système</a>
        <a class="acdc-button acdc-button-primary" href="<?php echo esc_url( add_query_arg( array( 'nad_subtab' => 'block_new' ), $base_url ) ); ?>">Créer un bloc</a>
      </div>
    </section>
    <?php
    // ACDC 3.21.16 — Traitement reset blocs système
    if ( ! empty( $_GET['nad_reset_blocs'] ) && check_admin_referer( 'acdc_reset_nad_system_blocs' ) ) {
      $this->reset_nad_system_blocks();
      wp_safe_redirect( add_query_arg( array( 'nad_subtab' => 'blocks', 'notice' => rawurlencode( 'Blocs système réinitialisés avec succès.' ), 'notice_type' => 'success' ), $base_url ) );
      exit;
    }
    ?>
    <?php if ( '' !== $notice ) : ?>
      <div class="acdc-notice <?php echo 'error' === $notice_type ? 'acdc-notice-error' : 'acdc-notice-success'; ?>"><?php echo esc_html( $notice ); ?></div>
    <?php endif; ?>
    <?php if ( 'block_new' === $nad_subtab || 'block_edit' === $nad_subtab ) : ?>
      <?php
      $editing_bloc = ( 'block_edit' === $nad_subtab && $nad_block_id ) ? $this->get_need_block( $nad_block_id ) : null;
      ?>
      <div class="acdc-panel acdc-mb-18">
        <div class="acdc-panel-header"><h3><?php echo $editing_bloc ? 'Modifier le bloc' : 'Créer un bloc'; ?></h3></div>
        <div class="acdc-panel-body acdc-pad-24">
          <form class="acdc-form" method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>">
            <?php wp_nonce_field( 'acdc_save_need_block' ); ?>
            <input type="hidden" name="action" value="acdc_save_need_block">
