  private function render_nad_block_detail( $base_url, $nad_subtab, $nad_block_id ) {
    $notice       = isset( $_GET['notice'] )       ? sanitize_text_field( wp_unslash( $_GET['notice'] ) )       : '';
    $notice_type  = isset( $_GET['notice_type'] )  ? sanitize_text_field( wp_unslash( $_GET['notice_type'] ) )  : 'success';
    $nad_qid      = isset( $_GET['nad_question_id'] ) ? absint( wp_unslash( $_GET['nad_question_id'] ) ) : 0;
    $bloc         = $nad_block_id ? $this->get_need_block( $nad_block_id ) : null;
    if ( ! $bloc ) {
      echo '<div class="acdc-notice acdc-notice-error">Bloc introuvable.</div>';
      echo '<p><a class="acdc-button acdc-button-soft" href="' . esc_url( add_query_arg( array( 'nad_subtab' => 'blocks' ), $base_url ) ) . '">← Retour</a></p>';
      return;
    }
    $questions    = $this->get_need_questions( (int) $bloc->id );
    $editing_q    = ( 'question_edit' === $nad_subtab && $nad_qid ) ? $this->get_need_question( $nad_qid ) : null;
    $show_q_form  = in_array( $nad_subtab, array( 'question_new', 'question_edit' ), true );
    $types_rep    = array( 'texte_court' => 'Texte court', 'texte_long' => 'Texte long', 'choix_unique' => 'Choix unique', 'choix_multiple' => 'Cases à cocher', 'nombre' => 'Nombre', 'date' => 'Date', 'email' => 'E-mail', 'telephone' => 'Téléphone', 'consentement' => 'Consentement', 'url' => 'Adresse web' );
