  private function render_front_need_analysis_form( $analysis = null, $read_only = false ) {
    /* ----------------------------------------------------------------
     * ACDC 3.21.12 — Formulaire unifié : métadonnées + blocs + réponses
     * ---------------------------------------------------------------- */
    global $wpdb;
    $base_url = is_admin()
      ? admin_url( 'admin.php?page=acdc-of-need-analyses' )
      : $this->portal_page_url( array( 'tab' => 'need_analyses' ) );

    /* --- Initialisation legacy blocks (ancien système) --- */
    $legacy_blocks = array();
    if ( $analysis && ! empty( $analysis->blocks_json ) ) {
      $decoded = json_decode( $analysis->blocks_json, true );
      if ( is_array( $decoded ) ) { $legacy_blocks = $decoded; }
    }

    /* --- Blocs sélectionnés (nouveau système) --- */
    $selected_bloc_ids = array();
    if ( $analysis && ! empty( $analysis->blocs_ids ) ) {
      $decoded_ids = json_decode( $analysis->blocs_ids, true );
      if ( is_array( $decoded_ids ) ) { $selected_bloc_ids = array_map( 'intval', $decoded_ids ); }
    }

    /* --- Réponses stockées (overrides manuels) --- */
    $reponses = array();
    if ( $analysis && ! empty( $analysis->reponses ) ) {
      $decoded_rep = json_decode( $analysis->reponses, true );
      if ( is_array( $decoded_rep ) ) { $reponses = $decoded_rep; }
    }

    /* --- Prefill dynamique --- */
    $nad_prefill = $analysis ? $this->get_nad_prefill_values( $analysis ) : array();

    /* --- Sources pour les sélecteurs --- */
    $nad_prospects   = $wpdb->get_results( "SELECT id, CONCAT(first_name,' ',last_name) AS label, email FROM {$wpdb->prefix}acdc_of_prospects ORDER BY last_name ASC LIMIT 300" );
    $nad_apprenants  = $wpdb->get_results( "SELECT id, CONCAT(first_name,' ',last_name) AS label, email FROM {$wpdb->prefix}acdc_of_learners ORDER BY last_name ASC LIMIT 300" );
    $nad_entreprises = $wpdb->get_results( "SELECT id, name AS label FROM {$wpdb->prefix}acdc_of_companies ORDER BY name ASC LIMIT 300" );
    $nad_formations  = $wpdb->get_results( "SELECT id, title AS label FROM {$wpdb->prefix}acdc_of_formations WHERE COALESCE(is_draft,0)=0 ORDER BY title ASC LIMIT 300" );
    $nad_dossiers    = $wpdb->get_results( "SELECT id, title AS label, start_date FROM {$wpdb->prefix}acdc_of_registration_contracts ORDER BY created_at DESC LIMIT 300" );

    /* --- Tous les blocs disponibles (pour le picker) --- */
    $all_blocs = $this->get_need_blocks( array( 'actif' => 1 ) );

    /* --- Blocs sélectionnés avec leurs objets (triés selon selected_bloc_ids) --- */
    $selected_blocs = array();
    if ( ! empty( $selected_bloc_ids ) ) {
      $blocs_map = array();
      foreach ( $all_blocs as $b ) { $blocs_map[ (int) $b->id ] = $b; }
      foreach ( $selected_bloc_ids as $bid ) {
        if ( isset( $blocs_map[ $bid ] ) ) { $selected_blocs[] = $blocs_map[ $bid ]; }
      }
    }

    /* --- Infos analyse --- */
    $analysis_type = $analysis ? (string) $analysis->analysis_type : 'Entreprise';
    $profils_map   = array( 'particulier' => 'Particulier', 'apprenant' => 'Apprenant', 'salarie' => 'Salarié', 'entreprise' => 'Entreprise', 'independant' => 'Indépendant' );
    $them_map      = $this->get_thematiques_map();
    $statuts_map   = array( 'brouillon' => 'Brouillon', 'nouveau' => 'Nouveau', 'a_traiter' => 'À traiter', 'traite' => 'Traité', 'archive' => 'Archivé', 'expire' => 'Expiré' );
    $types_rep_labels = array( 'texte_court' => 'text', 'texte_long' => 'textarea', 'choix_unique' => 'radio', 'choix_multiple' => 'checkbox', 'nombre' => 'number', 'date' => 'date', 'email' => 'email', 'telephone' => 'tel', 'consentement' => 'checkbox_single', 'url' => 'url' );

    /* ---- MODE VUE (read_only) ---- */
    if ( $read_only ) : ?>
    <div class="acdc-panel acdc-mb-18">
      <div class="acdc-qz-results-hero" style="background:linear-gradient(135deg,#fef6e4 0%,#fbf8f7 100%);border:1px solid #f0e6dc;border-radius:12px;padding:24px 28px;margin-bottom:20px;">
        <p class="acdc-hero-eyebrow" style="color:#8a6d2a;text-transform:uppercase;font-size:12px;font-weight:700;letter-spacing:.06em;margin:0 0 6px;">
          <?php echo $analysis && ! empty( $analysis->profil ) ? esc_html( $profils_map[ $analysis->profil ] ?? $analysis->profil ) : 'Analyse du besoin'; ?>
          <?php if ( $analysis && ! empty( $analysis->thematique ) ) : ?> — <?php echo esc_html( $them_map[ $analysis->thematique ] ?? $analysis->thematique ); ?><?php endif; ?>
        </p>
        <h2 style="color:#0f2c52;font-size:22px;font-weight:800;margin:0 0 8px;"><?php echo esc_html( $analysis->title ); ?></h2>
        <p style="color:#4b5d76;font-size:14px;margin:0 0 16px;">
          <?php $statut_v = $analysis->statut ?? 'brouillon'; echo esc_html( $statuts_map[ $statut_v ] ?? $statut_v ); ?>
          — Modifié le <?php echo esc_html( mysql2date( 'j F Y', $analysis->updated_at ) ); ?>
        </p>
        <a class="acdc-button acdc-button-soft" href="<?php echo esc_url( add_query_arg( array( 'action' => 'edit', 'item_id' => (int) $analysis->id ), $base_url ) ); ?>">Modifier</a>
        <a class="acdc-button acdc-button-soft" href="<?php echo esc_url( $base_url ); ?>" style="margin-left:8px;">← Retour</a>
      </div>
      <?php if ( ! empty( $nad_prefill ) ) : ?>
      <div style="background:#fbf8f7;border:1px solid #f0e6dc;border-radius:10px;padding:18px 24px;margin-bottom:20px;">
        <p style="font-weight:700;font-size:13px;color:#8a6d2a;margin:0 0 12px;text-transform:uppercase;letter-spacing:.05em;">Sources liées</p>
        <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:8px 20px;">
          <?php foreach ( array( 'source.label' => 'Répondant', 'source.email' => 'E-mail', 'entreprise.name' => 'Entreprise', 'formation.titre' => 'Formation', 'dossier.date_debut' => 'Date début', 'dossier.financeur' => 'Financeur' ) as $_path => $_lbl ) :
            $_val = $nad_prefill[ $_path ] ?? '';
            if ( '' === $_val ) continue; ?>
            <p style="margin:0;font-size:13px;"><span style="color:#8a6d2a;font-weight:600;"><?php echo esc_html( $_lbl ); ?> :</span> <?php echo esc_html( $_val ); ?></p>
          <?php endforeach; ?>
        </div>
      </div>
      <?php endif; ?>
      <?php if ( ! empty( $selected_blocs ) ) :
        foreach ( $selected_blocs as $bloc ) :
          $questions = $this->get_need_questions( (int) $bloc->id, true );
          if ( empty( $questions ) ) continue; ?>
          <div style="margin-bottom:24px;">
            <h3 style="color:#0f2c52;font-size:16px;font-weight:700;margin:0 0 14px;padding-bottom:8px;border-bottom:2px solid #d6a353;"><?php echo esc_html( $bloc->nom ); ?></h3>
            <div style="display:grid;gap:12px;">
              <?php foreach ( $questions as $q ) :
                $val_stored = $reponses[ $q->code ] ?? null;
                $val_prefill = $this->nad_resolve_prefill( $q->source_prefill, $nad_prefill );
                $val = ( $val_stored !== null && $val_stored !== '' ) ? $val_stored : $val_prefill;
                if ( '' === (string) $val ) continue; ?>
                <div style="display:grid;grid-template-columns:1fr 2fr;gap:12px;padding:10px 0;border-bottom:1px solid #f0e6dc;">
                  <p style="margin:0;font-size:13px;color:#4b5d76;font-weight:600;"><?php echo esc_html( $q->libelle ); ?><?php if ( (int) $q->obligatoire ) echo ' <span style="color:#d6a353;">*</span>'; ?></p>
                  <p style="margin:0;font-size:13px;color:#0f2c52;"><?php echo is_array( $val ) ? esc_html( implode( ', ', $val ) ) : nl2br( esc_html( (string) $val ) ); ?><?php if ( $val_stored === null && $val_prefill !== '' ) echo ' <em style="color:#8a6d2a;font-size:11px;">(prérempli)</em>'; ?></p>
                </div>
              <?php endforeach; ?>
            </div>
          </div>
        <?php endforeach;
      elseif ( ! empty( $legacy_blocks ) ) : ?>
        <p style="color:#4b5d76;font-size:13px;font-style:italic;">Cette analyse utilise l'ancien format. Modifiez-la pour activer le nouveau système de blocs.</p>
      else : ?>
        <p style="color:#4b5d76;">Aucun bloc ajouté à cette analyse.</p>
      <?php endif; ?>
      <?php if ( $analysis && ! empty( $analysis->synthese ) ) : ?>
      <div style="margin-top:24px;background:#fbf8f7;border:1px solid #f0e6dc;border-radius:10px;padding:18px 24px;">
        <p style="font-weight:700;color:#0f2c52;margin:0 0 8px;">Synthèse</p>
        <div style="color:#4b5d76;font-size:14px;"><?php echo wp_kses_post( nl2br( $analysis->synthese ) ); ?></div>
      </div>
      <?php endif; ?>
      <?php
      // ACDC 3.21.29-hotfix4 — Historique des actions
      $hist = array();
      if ( ! empty( $analysis->created_at ) ) {
        $hist[] = array( 'date' => $analysis->created_at, 'label' => 'Analyse créée', 'color' => '#4b5d76', 'icon' => '📋' );
      }
      if ( ! empty( $analysis->sent_at ) ) {
        $hist[] = array( 'date' => $analysis->sent_at, 'label' => 'Formulaire envoyé à ' . esc_html( $analysis->repondant_email ?: '—' ), 'color' => '#1e4777', 'icon' => '✉️' );
      }
      if ( ! empty( $analysis->relance_1_at ) ) {
        $hist[] = array( 'date' => $analysis->relance_1_at, 'label' => 'Relance 1 envoyée', 'color' => '#c2410c', 'icon' => '🔁' );
      }
      if ( ! empty( $analysis->relance_2_at ) ) {
        $hist[] = array( 'date' => $analysis->relance_2_at, 'label' => 'Relance 2 envoyée', 'color' => '#c2410c', 'icon' => '🔁' );
      }
      if ( ! empty( $analysis->relance_3_at ) ) {
        $hist[] = array( 'date' => $analysis->relance_3_at, 'label' => 'Relance 3 envoyée (dernière)', 'color' => '#c2410c', 'icon' => '🔁' );
      }
      if ( 'traite' === ( $analysis->statut ?? '' ) && ! empty( $analysis->updated_at ) ) {
        $hist[] = array( 'date' => $analysis->updated_at, 'label' => 'Analyse soumise par le répondant', 'color' => '#15803d', 'icon' => '✅' );
      }
      if ( ! empty( $analysis->scheduled_send_at ) && empty( $analysis->sent_at ) ) {
        $hist[] = array( 'date' => $analysis->scheduled_send_at, 'label' => 'Envoi programmé', 'color' => '#8a6d2a', 'icon' => '🕐', 'futur' => true );
      }
      ?>
