      <div style="margin-top:24px;background:#fbf8f7;border:1px solid #f0e6dc;border-radius:10px;padding:18px 24px;">
        <p style="font-weight:700;font-size:13px;color:#8a6d2a;margin:0 0 14px;text-transform:uppercase;letter-spacing:.05em;">Historique des actions</p>
        <div style="position:relative;">
          <?php foreach ( $hist as $ev ) : ?>
          <div style="display:flex;align-items:flex-start;gap:14px;padding:10px 0;border-bottom:1px solid #f0e6dc;">
            <span style="font-size:18px;line-height:1;flex-shrink:0;"><?php echo $ev['icon']; ?></span>
            <div style="flex:1;">
              <p style="margin:0;font-size:13px;font-weight:600;color:<?php echo esc_attr( $ev['color'] ); ?>;"><?php echo esc_html( $ev['label'] ); ?></p>
              <p style="margin:2px 0 0;font-size:12px;color:#9ca3af;"><?php echo ! empty( $ev['futur'] ) ? '⏳ ' : ''; ?><?php echo esc_html( mysql2date( 'j F Y à H\hi', $ev['date'] ) ); ?></p>
            </div>
          </div>
          <?php endforeach; ?>
        </div>
      </div>
      <?php endif; ?>
      <?php
      // ACDC 3.21.29-hotfix4 — Réponses du répondant (statut traité uniquement)
      if ( 'traite' === ( $analysis->statut ?? '' ) && ! empty( $reponses ) ) :
        global $wpdb;
        // Récupérer toutes les questions dont le code est dans les réponses, triées par bloc + ordre
        $rep_codes  = array_keys( $reponses );
        $placeholders = implode( ',', array_fill( 0, count( $rep_codes ), '%s' ) );
        $q_rows = $wpdb->get_results(
          $wpdb->prepare(
            "SELECT q.*, b.nom AS bloc_nom, b.id AS bloc_id_val
             FROM {$this->need_question_table} q
             LEFT JOIN {$this->need_block_table} b ON q.bloc_id = b.id
             WHERE q.code IN ($placeholders)
             ORDER BY b.ordre ASC, b.id ASC, q.ordre ASC, q.id ASC",
            ...$rep_codes
          )
        );
        // Grouper par bloc
        $reponses_par_bloc = array();
        foreach ( $q_rows as $qr ) {
          $bkey = (string) ( $qr->bloc_id_val ?? '0' );
          if ( ! isset( $reponses_par_bloc[ $bkey ] ) ) {
            $reponses_par_bloc[ $bkey ] = array( 'nom' => $qr->bloc_nom ?? 'Questions', 'questions' => array() );
          }
          $reponses_par_bloc[ $bkey ]['questions'][] = $qr;
        }
        // Codes sans question trouvée (réponses libres / legacy)
        $codes_trouves = array_column( $q_rows, 'code' );
        $codes_orphelins = array_diff( $rep_codes, $codes_trouves );
        ?>
        <div style="margin-top:24px;background:#fff;border:1px solid #f0e6dc;border-radius:10px;overflow:hidden;">
          <div style="background:#fbf8f7;padding:14px 24px;border-bottom:1px solid #f0e6dc;">
            <p style="font-weight:700;font-size:13px;color:#8a6d2a;margin:0;text-transform:uppercase;letter-spacing:.05em;">✅ Réponses du répondant</p>
          </div>
          <?php foreach ( $reponses_par_bloc as $bloc_group ) : ?>
          <div style="padding:16px 24px 8px;">
            <p style="font-size:13px;font-weight:700;color:#0f2c52;margin:0 0 10px;padding-bottom:6px;border-bottom:2px solid #d6a353;"><?php echo esc_html( $bloc_group['nom'] ); ?></p>
            <?php foreach ( $bloc_group['questions'] as $qr ) :
              $val = $reponses[ $qr->code ] ?? '';
              if ( '' === (string) $val ) continue;
              ?>
              <div style="display:grid;grid-template-columns:1fr 2fr;gap:8px 16px;padding:8px 0;border-bottom:1px solid #f7f0e8;">
                <p style="margin:0;font-size:13px;color:#4b5d76;font-weight:600;"><?php echo esc_html( $qr->libelle ); ?></p>
                <p style="margin:0;font-size:13px;color:#0f2c52;"><?php echo is_array( $val ) ? esc_html( implode( ', ', $val ) ) : nl2br( esc_html( (string) $val ) ); ?></p>
              </div>
            <?php endforeach; ?>
          </div>
          <?php endforeach; ?>
          <?php if ( ! empty( $codes_orphelins ) ) : ?>
          <div style="padding:16px 24px 8px;">
            <p style="font-size:13px;font-weight:700;color:#0f2c52;margin:0 0 10px;padding-bottom:6px;border-bottom:2px solid #d6a353;">Autres réponses</p>
            <?php foreach ( $codes_orphelins as $ocode ) :
              $val = $reponses[ $ocode ] ?? '';
              if ( '' === (string) $val ) continue;
              ?>
              <div style="display:grid;grid-template-columns:1fr 2fr;gap:8px 16px;padding:8px 0;border-bottom:1px solid #f7f0e8;">
                <p style="margin:0;font-size:13px;color:#4b5d76;font-weight:600;"><?php echo esc_html( $ocode ); ?></p>
                <p style="margin:0;font-size:13px;color:#0f2c52;"><?php echo is_array( $val ) ? esc_html( implode( ', ', $val ) ) : nl2br( esc_html( (string) $val ) ); ?></p>
              </div>
            <?php endforeach; ?>
          </div>
          <?php endif; ?>
        </div>
      <?php endif; ?>
    </div>
    <?php return; endif;

    /* ---- MODE ÉDITION ---- */
