              <option value="">— Ajouter un bloc —</option>
              <?php foreach ( $all_blocs as $b ) :
                $nb = $this->get_need_questions_count_by_bloc( (int) $b->id );
                if ( $nb === 0 ) continue;
                $already = in_array( (int) $b->id, $selected_bloc_ids, true ) ? ' ✓' : '';
                ?>
                <option value="<?php echo (int)$b->id;?>" data-nom="<?php echo esc_attr($b->nom);?>" data-nb="<?php echo(int)$nb;?>"><?php echo esc_html($b->nom.$already);?> (<?php echo(int)$nb;?> q.)</option>
              <?php endforeach;?>
            </select>
            <button type="button" class="acdc-button acdc-button-soft" id="nad-add-bloc-btn">+ Ajouter ce bloc</button>
          </div>
