    <!-- Template JS pour les blocs AJAX -->
    <script id="nad-bloc-questions-data" type="application/json">
    <?php
    $blocs_data = array();
    foreach ( $all_blocs as $b ) {
      $questions = $this->get_need_questions( (int) $b->id, true );
      if ( empty( $questions ) ) continue;
      $blocs_data[ (int) $b->id ] = array(
        'id'   => (int) $b->id,
        'nom'  => $b->nom,
        'type' => $b->type_bloc,
        'questions' => array_map( function( $q ) {
          $opts = null;
          if ( ! empty( $q->options ) ) {
            $decoded = json_decode( $q->options, true );
            if ( is_array( $decoded ) ) { $opts = $decoded; }
          }
          return array(
            'id'            => (int) $q->id,
            'code'          => $q->code,
            'libelle'       => $q->libelle,
            'type_reponse'  => $q->type_reponse,
            'obligatoire'   => (bool) $q->obligatoire,
            'options'       => $opts,
            'aide'          => $q->aide,
            'placeholder'   => $q->placeholder,
            'source_prefill'=> $q->source_prefill,
          );
        }, $questions ),
      );
    }
    echo wp_json_encode( $blocs_data, JSON_UNESCAPED_UNICODE );
    ?>
    </script>
    <script>
    (function(){
      var blocsData     = JSON.parse(document.getElementById('nad-bloc-questions-data').textContent || '{}');
      var prefillValues = <?php echo wp_json_encode( $nad_prefill, JSON_UNESCAPED_UNICODE ); ?>;
      var storedRep     = <?php echo wp_json_encode( $reponses, JSON_UNESCAPED_UNICODE ); ?>;
      var container     = document.getElementById('nad-blocs-container');
      var idsInput      = document.getElementById('nad-blocs-ids-json');
      var picker        = document.getElementById('nad-bloc-picker');
      var addBtn        = document.getElementById('nad-add-bloc-btn');
      var emptyMsg      = document.getElementById('nad-empty-msg');
      var selectedIds   = <?php echo wp_json_encode( $selected_bloc_ids ); ?>;

      function getIds() { return selectedIds.slice(); }
      function saveIds() { idsInput.value = JSON.stringify(selectedIds); }

      function renderField(q, value) {
        var t = q.type_reponse;
        var ph = q.placeholder ? ' placeholder="'+escHtml(q.placeholder)+'"' : '';
        var req = q.obligatoire ? ' required' : '';
        var nm = 'reponses['+q.code+']';
        if (t === 'texte_long') {
          return '<textarea name="'+nm+'" rows="3"'+ph+req+'>'+escHtml(value||'')+'</textarea>';
        }
        if (t === 'choix_unique' && q.options) {
          var s = '<select name="'+nm+'"'+req+'><option value="">— Choisir —</option>';
          q.options.forEach(function(o){s+='<option value="'+escHtml(o)+'"'+(value===o?' selected':'')+'>'+escHtml(o)+'</option>';});
          return s+'</select>';
        }
        if (t === 'choix_multiple' && q.options) {
          var s = '<div style="display:flex;flex-wrap:wrap;gap:8px;">';
          q.options.forEach(function(o){
            var vals = Array.isArray(value)?value:(value?[value]:[]);
            var chk = vals.indexOf(o)>-1?' checked':'';
            s+='<label style="display:flex;align-items:center;gap:6px;font-size:13px;"><input type="checkbox" name="'+nm+'[]" value="'+escHtml(o)+'"'+chk+'> '+escHtml(o)+'</label>';
          });
          return s+'</div>';
        }
        if (t === 'consentement') {
          return '<label style="display:flex;align-items:flex-start;gap:8px;"><input type="checkbox" name="'+nm+'" value="1"'+(value?'checked':'')+req+'> <span style="font-size:13px;">J\'accepte</span></label>';
        }
        var inputType = {nombre:'number',date:'date',email:'email',telephone:'tel',url:'url'}[t]||'text';
        return '<input type="'+inputType+'" name="'+nm+'" value="'+escHtml(value||'')+'"'+ph+req+'>';
      }

      function buildBlocCard(blocId) {
        var bloc = blocsData[blocId];
        if (!bloc) return null;
        var card = document.createElement('div');
        card.className = 'nad-bloc-card';
        card.setAttribute('data-bloc-id', blocId);
        card.style.cssText = 'border:1px solid #f0e6dc;border-radius:10px;margin-bottom:14px;overflow:hidden;';
        var header = '<div style="background:#fbf2e3;padding:12px 16px;display:flex;align-items:center;justify-content:space-between;">';
        header += '<strong style="color:#0f2c52;font-size:14px;">'+escHtml(bloc.nom)+'</strong>';
        header += '<div style="display:flex;gap:8px;">';
        header += '<button type="button" class="acdc-button acdc-button-soft nad-move-up" style="padding:4px 10px;height:auto;font-size:12px;" title="Monter">↑</button>';
        header += '<button type="button" class="acdc-button acdc-button-soft nad-move-down" style="padding:4px 10px;height:auto;font-size:12px;" title="Descendre">↓</button>';
        header += '<button type="button" class="acdc-button nad-remove-bloc" style="padding:4px 10px;height:auto;font-size:12px;background:#fee;color:#c00;border:1px solid #fcc;" title="Retirer">✕</button>';
        header += '</div></div>';
        var body = '<div style="padding:16px;">';
        bloc.questions.forEach(function(q){
          var stored = storedRep[q.code] !== undefined ? storedRep[q.code] : null;
          var prefilled = q.source_prefill && prefillValues[q.source_prefill] ? prefillValues[q.source_prefill] : '';
          var value = stored !== null ? stored : prefilled;
          var badge = (stored===null && prefilled!=='') ? ' <em style="color:#8a6d2a;font-size:11px;">(prérempli)</em>' : '';
          body += '<div style="margin-bottom:14px;">';
          body += '<label style="display:block;font-size:13px;font-weight:600;color:#0f2c52;margin-bottom:6px;">'+escHtml(q.libelle)+(q.obligatoire?' <span style="color:#d6a353;">*</span>':'')+badge+'</label>';
          if (q.aide) { body += '<p style="font-size:12px;color:#4b5d76;margin:0 0 6px;">'+escHtml(q.aide)+'</p>'; }
          body += renderField(q, value);
          body += '</div>';
        });
        body += '</div>';
        card.innerHTML = header + body;
        card.querySelector('.nad-remove-bloc').addEventListener('click', function(){
          var idx = selectedIds.indexOf(blocId);
          if (idx>-1) { selectedIds.splice(idx,1); saveIds(); }
          card.remove();
          if (container.querySelectorAll('.nad-bloc-card').length===0 && emptyMsg) { emptyMsg.style.display=''; }
        });
        card.querySelector('.nad-move-up').addEventListener('click', function(){
          var prev = card.previousElementSibling;
          if (prev && prev.classList.contains('nad-bloc-card')) {
            container.insertBefore(card, prev);
            var ia = selectedIds.indexOf(blocId);
            var ib = selectedIds.indexOf(parseInt(prev.getAttribute('data-bloc-id')));
            if (ia>-1&&ib>-1){var t=selectedIds[ia];selectedIds[ia]=selectedIds[ib];selectedIds[ib]=t;}
            saveIds();
          }
        });
        card.querySelector('.nad-move-down').addEventListener('click', function(){
          var next = card.nextElementSibling;
          if (next && next.classList.contains('nad-bloc-card')) {
            container.insertBefore(next, card);
            var ia = selectedIds.indexOf(blocId);
            var ib = selectedIds.indexOf(parseInt(next.getAttribute('data-bloc-id')));
            if (ia>-1&&ib>-1){var t=selectedIds[ia];selectedIds[ia]=selectedIds[ib];selectedIds[ib]=t;}
            saveIds();
          }
        });
        return card;
      }

      function escHtml(s) {
        if (!s) return '';
        return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
      }

      if (addBtn) {
        addBtn.addEventListener('click', function(){
          var id = parseInt(picker.value);
          if (!id || !blocsData[id]) return;
          if (selectedIds.indexOf(id) > -1) { alert('Ce bloc est déjà ajouté.'); return; }
          selectedIds.push(id);
          saveIds();
          var card = buildBlocCard(id);
          if (card) {
            if (emptyMsg) { emptyMsg.style.display='none'; }
            container.appendChild(card);
          }
          picker.value = '';
        });
      }
    })();
    </script>
    <?php
  }

  /* -----------------------------------------------------------------------
   * ACDC 3.21.12 — Rendu d'une carte de bloc avec ses questions (PHP).
   * Utilisé uniquement pour les blocs déjà en base (reload de page).
