  /* =====================================================================
   * ACDC 3.21.13 — Shortcode formulaire public [acdc_nad_formulaire]
   * ===================================================================== */
  public function render_nad_formulaire_shortcode( $atts ) {
    $token = isset( $_GET['adb_token'] ) ? sanitize_text_field( wp_unslash( $_GET['adb_token'] ) ) : '';
    ob_start();
    if ( '' === $token ) {
      $this->render_nad_public_invalid();
    } else {
      global $wpdb;
      $analysis = $wpdb->get_row( $wpdb->prepare(
        "SELECT * FROM {$this->need_analysis_table} WHERE token_public = %s LIMIT 1", $token
      ) );
      if ( ! $analysis ) {
        $this->render_nad_public_invalid();
      // ACDC 3.25.113 — comparer en heure WP (token stocké en local).
      } elseif ( ! empty( $analysis->token_expire_at ) && strtotime( $analysis->token_expire_at ) < current_time( 'timestamp' ) ) {
        $this->render_nad_public_expired();
      } elseif ( 'traite' === $analysis->statut ) {
        $this->render_nad_public_done( $analysis );
      } else {
        $this->render_nad_public_form( $analysis, $token );
      }
    }
    return ob_get_clean();
  }

