  private function render_nad_public_form( $analysis, $token ) {
    // Charger blocs + questions
    $blocs_ids = array();
    if ( ! empty( $analysis->blocs_ids ) ) {
      $decoded = json_decode( $analysis->blocs_ids, true );
      if ( is_array( $decoded ) ) { $blocs_ids = array_map( 'intval', $decoded ); }
    }
    // ACDC 3.21.29-hotfix4 — Fallback : si blocs_ids vide, recalculer dynamiquement.
    if ( empty( $blocs_ids ) ) {
      $profil_fb     = ! empty( $analysis->profil )     ? (string) $analysis->profil     : 'commun';
      $thematique_fb = ! empty( $analysis->thematique ) ? (string) $analysis->thematique : '';
      $blocs_ids = $this->nad_auto_select_blocs( $profil_fb, $thematique_fb );
      if ( empty( $blocs_ids ) ) {
        $all_active = $this->get_need_blocks( array( 'actif' => 1 ) );
        foreach ( $all_active as $fb ) { $blocs_ids[] = (int) $fb->id; }
      }
    }
    $prefill  = $this->get_nad_prefill_values( $analysis );
    $reponses = array();
    if ( ! empty( $analysis->reponses ) ) {
      $r = json_decode( $analysis->reponses, true );
      if ( is_array( $r ) ) { $reponses = $r; }
    }
    // ACDC 3.21.29-hotfix4 — Exclure le bloc 'demarrage' quand le profil est déjà connu.
    // Ce bloc sert uniquement à identifier profil + thématique sur une analyse manuelle sans contexte.
    // Pour une analyse issue d'une convention, ces infos sont déjà définies → bloc inutile et déroutant.
    $skip_demarrage = ! empty( $analysis->profil );

    // ACDC 3.21.29-hotfix4b — Questions exclues selon le profil.
    // com_handicap / com_handicap_detail : question individuelle non applicable à un commanditaire entreprise.
    $profil_analyse = ! empty( $analysis->profil ) ? (string) $analysis->profil : '';
    $codes_exclus   = array();
    if ( 'entreprise' === $profil_analyse || 'independant' === $profil_analyse ) {
      $codes_exclus = array( 'com_handicap', 'com_handicap_detail' );
    }
    $sections = array();
    foreach ( $blocs_ids as $bid ) {
      $bloc = $this->get_need_block( $bid );
      if ( ! $bloc ) { continue; }
      if ( $skip_demarrage && 'demarrage' === $bloc->code ) { continue; }
      $questions = $this->get_need_questions( $bid, false ); // false = inclure questions inactives
      if ( ! empty( $codes_exclus ) ) {
        $questions = array_values( array_filter( $questions, function( $q ) use ( $codes_exclus ) {
          return ! in_array( (string) $q->code, $codes_exclus, true );
        } ) );
      }
      if ( empty( $questions ) ) { continue; }
      $sections[] = array( 'bloc' => $bloc, 'questions' => $questions );
    }

    // ACDC 3.21.29-hotfix4 — Si sections toujours vides malgré des blocs_ids (IDs obsolètes après
    // un reset des blocs système), recalculer dynamiquement via le profil + thématique.
    if ( empty( $sections ) ) {
      $profil_fb     = ! empty( $analysis->profil )     ? (string) $analysis->profil     : 'commun';
      $thematique_fb = ! empty( $analysis->thematique ) ? (string) $analysis->thematique : '';
      $fallback_ids  = $this->nad_auto_select_blocs( $profil_fb, $thematique_fb );
      if ( empty( $fallback_ids ) ) {
        // Dernier recours : tous les blocs actifs
        $all_active = $this->get_need_blocks( array( 'actif' => 1 ) );
        foreach ( $all_active as $fb ) { $fallback_ids[] = (int) $fb->id; }
      }
      foreach ( $fallback_ids as $bid ) {
        $bloc = $this->get_need_block( $bid );
        if ( ! $bloc ) { continue; }
        if ( $skip_demarrage && 'demarrage' === $bloc->code ) { continue; }
        $questions = $this->get_need_questions( $bid, false );
        if ( empty( $questions ) ) { continue; }
        $sections[] = array( 'bloc' => $bloc, 'questions' => $questions );
      }
    }

    // ---- DEBUG TEMPORAIRE 3.21.29-hotfix4 — SUPPRIMÉ ----

    // ACDC 3.21.29-hotfix4 — La question de consentement doit toujours être en dernière position.
    // On l'extrait de son bloc d'origine et on la place après toutes les autres sections.
    $consent_questions = array();
    $consent_bloc      = null;
    foreach ( $sections as $si => &$section ) {
      $kept = array();
      foreach ( $section['questions'] as $q ) {
        if ( 'consentement' === $q->type_reponse ) {
          $consent_questions[] = $q;
          if ( ! $consent_bloc ) { $consent_bloc = $section['bloc']; }
        } else {
          $kept[] = $q;
        }
      }
      $section['questions'] = $kept;
    }
    unset( $section );
    // Supprimer les sections devenues vides après extraction du consentement
    $sections = array_values( array_filter( $sections, function( $s ) { return ! empty( $s['questions'] ); } ) );
    // Ajouter le consentement comme dernière section
    if ( ! empty( $consent_questions ) && $consent_bloc ) {
      $sections[] = array( 'bloc' => $consent_bloc, 'questions' => $consent_questions );
    }

    $total_sections = count( $sections );
    $branding = $this->acdc_get_transactional_email_branding();
    $form_title = ! empty( $analysis->title ) ? (string) $analysis->title : 'Analyse du besoin';
    $prenom = ! empty( $analysis->repondant_prenom ) ? (string) $analysis->repondant_prenom : '';
    // ACDC 3.21.29-hotfix4b — Pour les profils entreprise/indépendant, l'entité est la destinataire, pas la personne.
    $greeting_name = $prenom;
    if ( 'entreprise' === $profil_analyse || 'independant' === $profil_analyse ) {
      $entreprise_name = ! empty( $prefill['entreprise.name'] ) ? (string) $prefill['entreprise.name'] : '';
      if ( $entreprise_name ) {
        $greeting_name = $entreprise_name;
      }
    }
    ?>
