    .nad-input{width:100%;padding:11px 14px;border:1.5px solid #dde3ec;border-radius:8px;font-size:14px;color:#1a2640;background:#fafbfd;transition:border-color .18s,box-shadow .18s;font-family:inherit;line-height:1.5;}
