    /* Consentement */
    .nad-consent{display:flex;align-items:flex-start;gap:12px;padding:14px 16px;background:#fdf6ec;border:1.5px solid #e8d4a8;border-radius:8px;}
    .nad-consent input{margin-top:2px;accent-color:#c49340;width:17px;height:17px;flex-shrink:0;}
    .nad-consent-text{font-size:13px;color:#4b5d76;line-height:1.6;}
    /* Navigation */
    .nad-nav{display:flex;gap:12px;justify-content:space-between;align-items:center;margin-top:20px;padding-top:20px;border-top:1px solid #f3ede4;flex-wrap:wrap;}
    .nad-btn{display:inline-flex;align-items:center;gap:8px;padding:12px 28px;border-radius:8px;font-size:15px;font-weight:700;cursor:pointer;border:none;font-family:inherit;transition:background .18s,transform .1s;line-height:1;}
