    <script>
    function nadGoTo(idx, total) {
      var sections = document.querySelectorAll('.nad-section');
      sections.forEach(function(s){ s.classList.remove('is-active'); });
      var target = document.getElementById('nad-section-' + idx);
      if (target) {
        target.classList.add('is-active');
        target.scrollIntoView({ behavior: 'smooth', block: 'start' });
      }
      var fill  = document.getElementById('nad-progress-fill');
      var label = document.getElementById('nad-progress-label');
      if (fill)  { fill.style.width = Math.round(((idx+1)/total)*100) + '%'; }
      if (label) { label.textContent = 'Étape ' + (idx+1) + ' sur ' + total; }
    }
    document.getElementById('nad-public-form').addEventListener('submit', function(e) {
      e.preventDefault();
      var form    = e.target;
      var errBox  = document.getElementById('nad-error-msg');
      var btn     = form.querySelector('.nad-btn-submit');
      var fd      = new FormData(form);
      var data    = new URLSearchParams();
      for (var pair of fd.entries()) { data.append(pair[0], pair[1]); }
      btn.disabled = true;
      btn.textContent = 'Envoi en cours…';
      errBox.style.display = 'none';
      fetch('<?php echo esc_url( admin_url( 'admin-ajax.php' ) ); ?>', {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: data.toString(),
      })
      .then(function(r){ return r.json(); })
      .then(function(res) {
        if (res.success) {
          form.closest('.nad-body').innerHTML = '<div class="nad-success"><div class="nad-success-icon">✓</div><h3>Merci <?php echo esc_js( $prenom ); ?> !</h3><p>Votre analyse du besoin a bien été enregistrée.<br>Votre organisme de formation en prendra connaissance et personnalisera votre parcours.</p></div>';
        } else {
          errBox.textContent = res.data ? res.data.message : 'Une erreur est survenue.';
          errBox.style.display = 'block';
          btn.disabled = false;
          btn.textContent = '✓ Envoyer mon analyse du besoin';
        }
      })
      .catch(function() {
        errBox.textContent = 'Erreur réseau. Vérifiez votre connexion et réessayez.';
        errBox.style.display = 'block';
        btn.disabled = false;
        btn.textContent = '✓ Envoyer mon analyse du besoin';
      });
    });
    // Highlight options on radio/checkbox change
    document.querySelectorAll('.nad-option input').forEach(function(input) {
      input.addEventListener('change', function() {
        var name = this.name;
        if (this.type === 'radio') {
          document.querySelectorAll('.nad-option input[name="' + name + '"]').forEach(function(i){
            i.closest('.nad-option').classList.toggle('is-selected', i.checked);
          });
        } else {
          this.closest('.nad-option').classList.toggle('is-selected', this.checked);
        }
      });
    });
    </script>
    </body>
    </html>
    <?php
    // On a rendu le HTML complet — on demande à WP de ne pas ajouter son thème
    // en interceptant la sortie via output buffer géré par le shortcode
  }

