    $bloc_id = (int) $bloc->id;
    ?>
    <div class="nad-bloc-card" data-bloc-id="<?php echo $bloc_id; ?>" style="border:1px solid #f0e6dc;border-radius:10px;margin-bottom:14px;overflow:hidden;">
      <div style="background:#fbf2e3;padding:12px 16px;display:flex;align-items:center;justify-content:space-between;">
        <strong style="color:#0f2c52;font-size:14px;"><?php echo esc_html( $bloc->nom ); ?></strong>
        <?php if ( ! $read_only ) : ?>
        <div style="display:flex;gap:8px;">
          <button type="button" class="acdc-button acdc-button-soft nad-move-up" style="padding:4px 10px;height:auto;font-size:12px;">↑</button>
          <button type="button" class="acdc-button acdc-button-soft nad-move-down" style="padding:4px 10px;height:auto;font-size:12px;">↓</button>
          <button type="button" class="acdc-button nad-remove-bloc" style="padding:4px 10px;height:auto;font-size:12px;background:#fee;color:#c00;border:1px solid #fcc;">✕</button>
        </div>
        <?php endif; ?>
      </div>
      <div style="padding:16px;">
        <?php foreach ( $questions as $q ) :
          $stored   = isset( $reponses[ $q->code ] ) ? $reponses[ $q->code ] : null;
          $prefilled = $this->nad_resolve_prefill( $q->source_prefill, $nad_prefill );
          $value    = ( $stored !== null && $stored !== '' ) ? $stored : $prefilled;
          $badge    = ( $stored === null && $prefilled !== '' ) ? ' <em style="color:#8a6d2a;font-size:11px;">(prérempli)</em>' : '';
          ?>
          <div style="margin-bottom:14px;">
            <label style="display:block;font-size:13px;font-weight:600;color:#0f2c52;margin-bottom:6px;">
              <?php echo wp_kses( $q->libelle . ( (int) $q->obligatoire ? ' <span style="color:#d6a353;">*</span>' : '' ) . $badge, array( 'span' => array( 'style' => array() ), 'em' => array( 'style' => array() ) ) ); ?>
            </label>
            <?php if ( $q->aide ) : ?>
            <p style="font-size:12px;color:#4b5d76;margin:0 0 6px;"><?php echo esc_html( $q->aide ); ?></p>
            <?php endif; ?>
            <?php $this->render_nad_question_field( $q, $value, $read_only ); ?>
          </div>
        <?php endforeach; ?>
      </div>
    </div>
    <?php
  }

  /* -----------------------------------------------------------------------
   * ACDC 3.21.12 — Rendu d'un champ de question.
   * -------------------------------------------------------------------- */
  private function render_nad_question_field( $q, $value, $read_only = false ) {
    $name = 'reponses[' . esc_attr( $q->code ) . ']';
    $ph   = $q->placeholder ? ' placeholder="' . esc_attr( $q->placeholder ) . '"' : '';
    $req  = ( (int) $q->obligatoire && ! $read_only ) ? ' required' : '';
    $dis  = $read_only ? ' disabled' : '';
    $t    = $q->type_reponse;

    if ( 'texte_long' === $t ) :
      ?><textarea name="<?php echo $name; ?>" rows="3"<?php echo $ph . $req . $dis; ?>><?php echo esc_textarea( (string) $value ); ?></textarea><?php
    elseif ( ( 'choix_unique' === $t ) && ! empty( $q->options ) ) :
      $opts = json_decode( $q->options, true );
      if ( is_array( $opts ) ) :
        ?><select name="<?php echo $name; ?>"<?php echo $req . $dis; ?>><option value="">— Choisir —</option><?php
        foreach ( $opts as $opt ) :
          ?><option value="<?php echo esc_attr( $opt ); ?>"<?php if ( $value === $opt ) echo ' selected'; ?>><?php echo esc_html( $opt ); ?></option><?php
        endforeach;
        ?></select><?php
      endif;
    elseif ( 'choix_unique_thematiques' === $t ) :
      $thematiques_dyn = $this->get_thematiques( true );
      ?><select name="<?php echo $name; ?>"<?php echo $req . $dis; ?>><option value="">— Choisir —</option><?php
      foreach ( $thematiques_dyn as $th ) :
        ?><option value="<?php echo esc_attr( $th->label ); ?>"<?php if ( $value === $th->label ) echo ' selected'; ?>><?php if ( ! empty( $th->icon_emoji ) ) echo esc_html( $th->icon_emoji ) . ' '; echo esc_html( $th->label ); ?></option><?php
      endforeach;
      ?></select><?php
    elseif ( 'choix_multiple' === $t && ! empty( $q->options ) ) :
      $opts = json_decode( $q->options, true );
      $vals = is_array( $value ) ? $value : ( $value ? array( $value ) : array() );
      if ( is_array( $opts ) ) :
        ?><div style="display:flex;flex-wrap:wrap;gap:8px;"><?php
        foreach ( $opts as $opt ) :
          ?><label style="display:flex;align-items:center;gap:6px;font-size:13px;">
            <input type="checkbox" name="<?php echo $name; ?>[]" value="<?php echo esc_attr( $opt ); ?>"<?php if ( in_array( $opt, $vals, true ) ) echo ' checked'; ?><?php echo $dis; ?>>
            <?php echo esc_html( $opt ); ?>
          </label><?php
        endforeach;
        ?></div><?php
      endif;
    elseif ( 'consentement' === $t ) :
      ?><label style="display:flex;align-items:flex-start;gap:8px;">
        <input type="checkbox" name="<?php echo $name; ?>" value="1"<?php if ( $value ) echo ' checked'; ?><?php echo $req . $dis; ?>>
        <span style="font-size:13px;">J'accepte</span>
      </label><?php
    else :
      $input_type = array( 'nombre' => 'number', 'date' => 'date', 'email' => 'email', 'telephone' => 'tel', 'url' => 'url' );
      $type = isset( $input_type[ $t ] ) ? $input_type[ $t ] : 'text';
      ?><input type="<?php echo esc_attr( $type ); ?>" name="<?php echo $name; ?>" value="<?php echo esc_attr( (string) $value ); ?>"<?php echo $ph . $req . $dis; ?>><?php
    endif;
  }



  private function render_front_needs_tab( $action, $item_id ) {
    $companies = $this->get_companies();
    $contacts  = $this->get_contacts();
    $need      = $item_id ? $this->get_need( $item_id ) : null;

