    <script>
    (function(){
      /* Filtres JS temps réel uniquement — le menu 3 points est géré par admin.js */
      var searchEl  = document.getElementById('acdc-needs-search');
      var filterSt  = document.getElementById('acdc-needs-filter-status');
      var filterPr  = document.getElementById('acdc-needs-filter-priority');
      var filterTh  = document.getElementById('acdc-needs-filter-theme');
      var table     = document.getElementById('acdc-needs-list-table');
      function applyFilters(){
        if(!table) return;
        var q  = searchEl ? searchEl.value.toLowerCase() : '';
        var st = filterSt ? filterSt.value : '';
        var pr = filterPr ? filterPr.value : '';
        var th = filterTh ? filterTh.value : '';
        table.querySelectorAll('tbody tr[data-need-status]').forEach(function(row){
          var ok = (!q || (row.dataset.needCompany||'').indexOf(q)>-1 || (row.dataset.needContact||'').indexOf(q)>-1 || (row.dataset.needTheme||'').toLowerCase().indexOf(q)>-1 || (row.dataset.needInterlocutor||'').indexOf(q)>-1)
            && (!st || row.dataset.needStatus===st)
            && (!pr || row.dataset.needPriority===pr)
            && (!th || row.dataset.needTheme===th);
          row.style.display = ok ? '' : 'none';
        });
      }
      if(searchEl) searchEl.addEventListener('input', applyFilters);
      if(filterSt) filterSt.addEventListener('change', applyFilters);
      if(filterPr) filterPr.addEventListener('change', applyFilters);
      if(filterTh) filterTh.addEventListener('change', applyFilters);
    })();
    </script>
    <?php
  }  private function render_front_need_view( $need ) {
    if ( ! $need ) {
      echo '<div class="acdc-panel"><p style="padding:24px;color:#1E4777;">Recueil introuvable.</p></div>';
      return;
    }
    $prospect = ! empty( $need->source_prospect_id ) ? $this->get_prospect( (int) $need->source_prospect_id ) : null;
    $back_url = is_admin()
      ? admin_url( 'admin.php?page=acdc-of-needs' )
      : $this->portal_page_url( array( 'tab' => 'needs' ) );
    $edit_url = is_admin()
      ? admin_url( 'admin.php?page=acdc-of-needs&action=edit&item_id=' . (int) $need->id . ( ! empty( $need->source_prospect_id ) ? '&prospect_id=' . (int) $need->source_prospect_id : '' ) )
      : $this->portal_page_url( array_filter( array( 'tab' => 'needs', 'action' => 'edit', 'item_id' => (int) $need->id, 'prospect_id' => ! empty( $need->source_prospect_id ) ? (int) $need->source_prospect_id : 0 ) ) );
    $label = function( $v ) { $v = trim( (string) $v ); return '' !== $v ? esc_html( $v ) : '<span style="color:#9ca3af;">—</span>'; };
    ?>
    <?php if ( $prospect ) : ?>
      <div style="margin-bottom:18px;padding:12px 16px;border:1px solid var(--acdc-border);border-radius:10px;background:#fff8e8;color:#0C2D52;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;">
        <div><strong>Prospect lié :</strong> <?php echo esc_html( trim( $prospect->first_name . ' ' . $prospect->last_name ) ?: ( ! empty( $prospect->company_name ) ? $prospect->company_name : 'Prospect #' . (int) $prospect->id ) ); ?></div>
        <a class="acdc-button acdc-button-soft" href="<?php echo esc_url( is_admin() ? admin_url( 'admin.php?page=acdc-of-prospects&action=edit&item_id=' . (int) $prospect->id ) : $this->portal_page_url( array( 'tab' => 'prospects', 'action' => 'edit', 'item_id' => (int) $prospect->id ) ) ); ?>">Voir le prospect</a>
      </div>
    <?php endif; ?>

    <div class="acdc-panel acdc-mb-18">
      <div class="acdc-needs-section-title">1. Identification</div>
      <div class="acdc-nv-grid">
        <div><span class="acdc-nv-label">Thématique</span><span class="acdc-nv-value"><?php echo $label( $need->theme ); ?></span></div>
        <div><span class="acdc-nv-label">Canal de recueil</span><span class="acdc-nv-value"><?php echo $label( $need->collection_channel ); ?></span></div>
        <div><span class="acdc-nv-label">Date du recueil</span><span class="acdc-nv-value"><?php echo $label( ! empty( $need->collection_date ) ? mysql2date( 'd/m/Y', $need->collection_date ) : '' ); ?></span></div>
        <div><span class="acdc-nv-label">Interlocuteur ACDC</span><span class="acdc-nv-value"><?php echo $label( $need->acdc_interlocutor ); ?></span></div>
        <div><span class="acdc-nv-label">Statut</span><span class="acdc-nv-value"><?php echo $label( $need->status ); ?></span></div>
        <div><span class="acdc-nv-label">Priorité</span><span class="acdc-nv-value"><?php echo $label( $need->priority_level ); ?></span></div>
        <?php if ( ! empty( $need->sent_at ) ) : ?>
        <div><span class="acdc-nv-label">Envoyé le</span><span class="acdc-nv-value"><?php echo esc_html( mysql2date( 'd/m/Y H\hi', $need->sent_at ) ); ?></span></div>
        <?php endif; ?>
      </div>
    </div>

    <div class="acdc-panel acdc-mb-18">
      <div class="acdc-needs-section-title">2. Besoin</div>
      <?php
      /* ACDC 3.25.233 — UN CHAMP VIDE DOIT SE VOIR, PAS DISPARAÎTRE.
         Ces blocs s'effaçaient quand ils n'étaient pas remplis : impossible de
         distinguer « la question n'a pas eu de réponse » de « la question
         n'existe pas ». Sur un recueil des besoins, l'absence de réponse EST
         une information — c'est elle qui dit ce qu'il reste à demander au
         prospect avant de bâtir la proposition. */
      $nv_text = function( $label_text, $value ) {
        echo '<div class="acdc-nv-block"><span class="acdc-nv-label">' . esc_html( $label_text ) . '</span><div class="acdc-nv-text">';
        echo '' !== trim( (string) $value ) ? nl2br( esc_html( $value ) ) : '<span style="color:#9ca3af;">Non renseigné</span>';
        echo '</div></div>';
      };
      $nv_text( 'Besoin exprimé', $need->expressed_need );
      $nv_text( 'Besoin reformulé', $need->reframed_need );
