  }  private function render_front_calendar_tab() {
    $year = isset( $_GET['year'] ) ? absint( $_GET['year'] ) : (int) current_time( 'Y' );
    $month = isset( $_GET['month'] ) ? absint( $_GET['month'] ) : (int) current_time( 'n' );
    if ( $month < 1 || $month > 12 ) {
      $month = (int) current_time( 'n' );
    }
    if ( $year < 2000 || $year > 2100 ) {
      $year = (int) current_time( 'Y' );
    }

    $first_day_ts = gmmktime( 12, 0, 0, $month, 1, $year );
    $days_in_month = (int) gmdate( 't', $first_day_ts );
    $first_weekday = (int) gmdate( 'N', $first_day_ts );
    $grid_start_ts = strtotime( '-' . ( $first_weekday - 1 ) . ' days', $first_day_ts );
    $grid_end_ts  = strtotime( '+41 days', $grid_start_ts );
    $today_key   = current_time( 'Y-m-d' );

    $events = $this->get_prospect_rdv_events( $year, $month );
    $events_by_day = array();
    foreach ( $events as $event ) {
      if ( empty( $event->rdv_at ) ) {
        continue;
      }
      $day_key = mysql2date( 'Y-m-d', $event->rdv_at );
      if ( ! isset( $events_by_day[ $day_key ] ) ) {
        $events_by_day[ $day_key ] = array();
      }
      $events_by_day[ $day_key ][] = $event;
    }

    $prev_ts = strtotime( '-1 month', $first_day_ts );
    $next_ts = strtotime( '+1 month', $first_day_ts );
    $prev_url = is_admin() ? admin_url( 'admin.php?page=acdc-of-calendar&month=' . gmdate( 'n', $prev_ts ) . '&year=' . gmdate( 'Y', $prev_ts ) ) : $this->portal_page_url( array( 'tab' => 'calendar', 'month' => gmdate( 'n', $prev_ts ), 'year' => gmdate( 'Y', $prev_ts ) ) );
    $next_url = is_admin() ? admin_url( 'admin.php?page=acdc-of-calendar&month=' . gmdate( 'n', $next_ts ) . '&year=' . gmdate( 'Y', $next_ts ) ) : $this->portal_page_url( array( 'tab' => 'calendar', 'month' => gmdate( 'n', $next_ts ), 'year' => gmdate( 'Y', $next_ts ) ) );
    $today_url = is_admin() ? admin_url( 'admin.php?page=acdc-of-calendar&month=' . current_time( 'n' ) . '&year=' . current_time( 'Y' ) ) : $this->portal_page_url( array( 'tab' => 'calendar', 'month' => current_time( 'n' ), 'year' => current_time( 'Y' ) ) );
    $prospects_url = is_admin() ? admin_url( 'admin.php?page=acdc-of-prospects' ) : $this->portal_page_url( array( 'tab' => 'prospects' ) );
    ?>
    <section class="acdc-section-head acdc-calendar-head">
      <div>
        <h2>Calendrier prospects</h2>
        <p>Vue mensuelle des rendez-vous enregistrés dans les fiches prospects.</p>
      </div>
      <div class="acdc-inline-wrap">
        <a class="acdc-button acdc-button-soft" href="<?php echo esc_url( $prospects_url ); ?>">Voir les prospects</a>
      </div>
    </section>

    <div class="acdc-calendar-toolbar acdc-panel">
      <div class="acdc-calendar-nav-buttons">
        <a class="acdc-calendar-nav-button" href="<?php echo esc_url( $prev_url ); ?>" aria-label="Mois précédent">&#171;</a>
        <a class="acdc-calendar-nav-button" href="<?php echo esc_url( $today_url ); ?>" aria-label="Mois en cours">•</a>
        <a class="acdc-calendar-nav-button" href="<?php echo esc_url( $next_url ); ?>" aria-label="Mois suivant">&#187;</a>
      </div>
      <h3 class="acdc-calendar-title">RDV Prospects - <?php echo esc_html( $this->get_calendar_month_label( $first_day_ts ) ); ?></h3>
    </div>

    <div class="acdc-calendar-board acdc-panel">
      <div class="acdc-calendar-weekdays">
        <?php foreach ( $this->build_calendar_day_names() as $day_name ) : ?>
          <div class="acdc-calendar-weekday"><?php echo esc_html( $day_name ); ?></div>
        <?php endforeach; ?>
      </div>
      <div class="acdc-calendar-grid">
        <?php for ( $day_ts = $grid_start_ts; $day_ts <= $grid_end_ts; $day_ts = strtotime( '+1 day', $day_ts ) ) : ?>
          <?php
          $day_key  = gmdate( 'Y-m-d', $day_ts );
          $is_current_month = (int) gmdate( 'n', $day_ts ) === $month;
          $is_today = $day_key === $today_key;
          $day_events = isset( $events_by_day[ $day_key ] ) ? $events_by_day[ $day_key ] : array();
          $classes = array( 'acdc-calendar-day' );
          if ( ! $is_current_month ) {
            $classes[] = 'is-outside';
          }
          if ( $is_today ) {
            $classes[] = 'is-today';
          }
          if ( ! empty( $day_events ) ) {
            $classes[] = 'has-events';
          }
          ?>
          <div class="<?php echo esc_attr( implode( ' ', $classes ) ); ?>">
            <div class="acdc-calendar-day-number"><?php echo esc_html( gmdate( 'j', $day_ts ) ); ?></div>
            <?php if ( ! empty( $day_events ) ) : ?>
              <div class="acdc-calendar-events">
                <?php foreach ( $day_events as $event ) : ?>
                  <?php
                  $event_url = is_admin()
                    ? admin_url( 'admin.php?page=acdc-of-prospect-followup&action=view&item_id=' . (int) $event->prospect_id )
                    : ( is_admin() ? $this->admin_prospect_followup_url( array( 'action' => 'view', 'item_id' => (int) $event->prospect_id ) ) : $this->portal_page_url( array( 'tab' => 'prospect_followup', 'action' => 'view', 'item_id' => (int) $event->prospect_id ) ) );
                  $event_title = trim( $event->first_name . ' ' . $event->last_name );
                  if ( '' === $event_title ) {
                    $event_title = $event->company_name ? $event->company_name : 'Prospect sans nom';
                  }
                  $assigned_color = ! empty( $event->assigned_to ) ? $this->get_calendar_color_for_assignee_label( (string) $event->assigned_to ) : '';
                  $assigned_text_color = ! empty( $assigned_color ) ? $this->get_calendar_text_color_for_background( $assigned_color ) : '';
                  $event_style = '';
                  $event_meta_style = '';
                  $event_classes = array( 'acdc-calendar-event' );
                  $is_past_event = false;
                  if ( ! empty( $event->rdv_at ) ) {
                    $event_timestamp = strtotime( (string) $event->rdv_at );
                    if ( false !== $event_timestamp ) {
                      $is_past_event = $event_timestamp < current_time( 'timestamp' );
                    }
                  }
                  if ( $is_past_event ) {
                    $event_classes[] = 'is-past';
                  }
                  if ( ! empty( $assigned_color ) ) {
                    if ( $is_past_event ) {
                      $event_style = $this->get_calendar_past_event_style( $assigned_color, $assigned_text_color ? $assigned_text_color : '#0C2D52' );
                    } else {
                      $event_style = sprintf( 'background:%1$s;border-color:%1$s;color:%2$s;', esc_attr( $assigned_color ), esc_attr( $assigned_text_color ? $assigned_text_color : '#FFFFFF' ) );
                    }
                    $event_meta_style = sprintf( 'color:%s;', esc_attr( $assigned_text_color ? $assigned_text_color : ( $is_past_event ? '#0C2D52' : '#FFFFFF' ) ) );
                  } elseif ( $is_past_event ) {
                    $event_style = 'background:repeating-linear-gradient(-45deg, rgba(197,162,83,0.14) 0, rgba(197,162,83,0.14) 8px, rgba(197,162,83,0.24) 8px, rgba(197,162,83,0.24) 16px);border-color:rgba(197,162,83,0.45);color:#0C2D52;';
                    $event_meta_style = 'color:#0C2D52;';
                  }
                  ?>
                  <a class="<?php echo esc_attr( implode( ' ', $event_classes ) ); ?>" href="<?php echo esc_url( $event_url ); ?>"<?php echo '' !== $event_style ? ' style="' . esc_attr( $event_style ) . '"' : ''; ?>>
                    <span class="acdc-calendar-event-time"<?php echo '' !== $event_meta_style ? ' style="' . esc_attr( $event_meta_style ) . '"' : ''; ?>><?php echo esc_html( mysql2date( 'H\hi', $event->rdv_at ) ); ?></span>
                    <span class="acdc-calendar-event-title"><?php echo esc_html( $event_title ); ?></span>
                    <?php if ( ! empty( $event->desired_training ) ) : ?>
                      <span class="acdc-calendar-event-meta"<?php echo '' !== $event_meta_style ? ' style="' . esc_attr( $event_meta_style ) . '"' : ''; ?>><?php echo esc_html( $event->desired_training ); ?></span>
                    <?php endif; ?>
                  </a>
                <?php endforeach; ?>
              </div>
            <?php endif; ?>
          </div>
        <?php endfor; ?>
      </div>
    </div>
    <?php
  }  private function render_access_state_icon( $state ) {
    if ( true === $state ) {
      return '<span style="color:#2bbf6a;font-weight:700;">✓</span>';
    }
    if ( 'partial' === $state ) {
      return '<span style="color:#c78b18;font-weight:700;">&#8226;&#8226;</span>';
    }
    return '<span style="color:#e04f5f;font-weight:700;">&#10005;</span>';
  }  private function render_front_trainers_tab( $action, $item_id ) {
    $search = isset( $_GET['q'] ) ? sanitize_text_field( wp_unslash( $_GET['q'] ) ) : '';
    $trainers = $this->get_trainers( $search );
    $trainer = $item_id ? $this->get_trainer( $item_id ) : null;
    $new_url = is_admin() ? admin_url( 'admin.php?page=acdc-of-trainers&action=new' ) : $this->portal_page_url( array( 'tab' => 'trainers', 'action' => 'new' ) );
    $page_title = $this->acdc_get_action_page_title( $action, 'Formateurs', 'Créer un formateur', 'Modifier un formateur', 'Voir un formateur' );
    ?>
    <section class="acdc-section-head">
      <div>
        <h2><?php echo esc_html( $page_title ); ?></h2>
        <p>Gestion des profils formateurs, de leurs accès et des informations affichées aux apprenants.</p>
      </div>
      <div class="acdc-inline-wrap">
        <a class="acdc-button acdc-button-soft" href="<?php echo esc_url( wp_nonce_url( admin_url( 'admin-post.php?action=acdc_export_trainers_csv' ), 'acdc_export_trainers_csv' ) ); ?>">⬇ Exporter CSV</a>
        <?php if ( 'view' === $action && $trainer && ! empty( $trainer->email ) ) : ?>
        <button type="button" class="acdc-button acdc-button-soft" data-acdc-modal-open="acdc-direct-email-modal-trainer-<?php echo (int) $trainer->id; ?>">&#x2709; Envoyer un e-mail</button>
        <?php endif; ?>
        <a class="acdc-button acdc-button-primary" href="<?php echo esc_url( $new_url ); ?>">Créer un formateur</a>
      </div>
    </section>
    <?php
    if ( in_array( $action, array( 'new', 'edit', 'view' ), true ) ) {
      $this->render_front_trainer_form( $trainer, 'view' === $action );
    }
    /* ACDC 3.20.99 — Barre de recherche et tableau de la liste : affichés uniquement
       en mode liste (action vide). Sur les pages create/edit/view, on ne montre que
       le formulaire pour ne pas alourdir visuellement et concentrer l'attention. */
    if ( ! in_array( $action, array( 'new', 'edit', 'view' ), true ) ) :
    ?>
    <div class="acdc-panel acdc-mb-18">
      <form method="get" action="">
        <?php if ( is_admin() ) : ?><input type="hidden" name="page" value="acdc-of-trainers"><?php endif; ?>
        <input type="hidden" name="tab" value="trainers">
        <div class="acdc-inline-wrap acdc-inline-wrap-center">
          <input type="search" name="q" value="<?php echo esc_attr( $search ); ?>" placeholder="Rechercher" style="max-width:420px;">
          <button type="submit" class="acdc-button acdc-button-soft">Rechercher</button>
        </div>
      </form>
    </div>
    <div class="acdc-panel">
      <div class="acdc-table-wrap">
        <table class="acdc-table" data-acdc-table-id="trainers-list">
          <thead><tr><th>Photo de profil</th><th>Genre</th><th>Prénom</th><th>Nom</th><th>E-mail</th><th>Téléphone</th><th>Rôle</th><th>Type de formateur</th><th>SIRET</th><th>E-mails de rappel de séance</th><th>E-mails de début de séance</th><th>Alerte contact</th><th>Alertes Qualiopi</th><th>Accès</th><th>Actions</th></tr></thead>
          <tbody>
          <?php
          $now_ts_tr = current_time( 'timestamp' );
          if ( ! empty( $trainers ) ) : foreach ( $trainers as $entry ) :
            // ACDC 3.21.67 — Calcul statut expiration Qualiopi pour cette ligne
            $tr_expired = 0;
            $tr_expiring = 0;
            if ( method_exists( $this, 'get_acdc_qualiopi_upcoming_expirations' ) ) {
              $tr_exps = $this->get_acdc_qualiopi_upcoming_expirations( $entry, 30 );
              foreach ( $tr_exps as $exp ) {
                $exp_ts = strtotime( (string) $exp['expires_at'] );
                if ( ! $exp_ts ) { continue; }
                $days_left = (int) floor( ( $exp_ts - $now_ts_tr ) / DAY_IN_SECONDS );
                if ( $days_left < 0 ) { $tr_expired++; } else { $tr_expiring++; }
              }
            }
            if ( $tr_expired > 0 ) {
              $tr_alert_html = "<span style=\"display:inline-flex;align-items:center;gap:4px;padding:3px 9px;border-radius:20px;font-size:11px;font-weight:700;background:#fee2e2;color:#991b1b;\" title=\"{$tr_expired} document(s) expiré(s)\">&#9679; {$tr_expired} expiré" . ( $tr_expired > 1 ? 's' : '' ) . "</span>";
            } elseif ( $tr_expiring > 0 ) {
              $tr_alert_html = "<span style=\"display:inline-flex;align-items:center;gap:4px;padding:3px 9px;border-radius:20px;font-size:11px;font-weight:700;background:#fef3c7;color:#92400e;\" title=\"{$tr_expiring} document(s) expirant dans 30 jours\">&#9679; {$tr_expiring} bientôt</span>";
            } else {
              $tr_alert_html = '<span style="color:#2bbf6a;font-weight:700;">✓</span>';
            }
          ?>
            <tr>
              <td><?php if ( ! empty( $entry->photo_url ) ) : ?><img src="<?php echo esc_url( $entry->photo_url ); ?>" alt="" style="width:36px;height:36px;border-radius:999px;object-fit:cover;"><?php else : ?>—<?php endif; ?></td>
              <td><?php echo esc_html( $entry->gender ?: '—' ); ?></td>
              <td><?php echo esc_html( $entry->first_name ?: '—' ); ?></td>
              <td><?php echo esc_html( $entry->last_name ?: '—' ); ?></td>
              <td><?php echo esc_html( $entry->email ?: '—' ); ?></td>
              <td><?php echo esc_html( $entry->phone ?: '—' ); ?></td>
              <td><?php echo esc_html( $entry->role_name ?: '—' ); ?></td>
              <td><?php echo esc_html( $entry->trainer_type ?: '—' ); ?></td>
              <td><?php echo esc_html( $entry->siret ?: '—' ); ?></td>
              <td><?php echo ! empty( $entry->session_reminder_enabled ) ? '<span style="color:#2bbf6a;font-weight:700;">✓</span>' : '—'; ?></td>
              <td><?php echo ! empty( $entry->session_start_enabled ) ? '<span style="color:#2bbf6a;font-weight:700;">✓</span>' : '—'; ?></td>
              <td><?php echo esc_html( $entry->contact_alert_at ? mysql2date( 'd/m/Y H:i', $entry->contact_alert_at ) : '—' ); ?></td>
              <td><?php echo $tr_alert_html; ?></td>
              <td><?php echo ! empty( $entry->access_enabled ) ? '<span style="color:#2bbf6a;font-weight:700;">✓</span>' : '<span style="color:#e04f5f;font-weight:700;">&#10005;</span>'; ?></td>
              <td><?php $base = is_admin() ? admin_url( 'admin.php?page=acdc-of-trainers' ) : $this->portal_page_url( array( 'tab' => 'trainers' ) ); ?>
                <div class="acdc-groups-actions-inline">
                  <a class="acdc-row-action-icon acdc-row-view-link" href="<?php echo esc_url( add_query_arg( array( 'action' => 'view', 'item_id' => $entry->id ), $base ) ); ?>" title="Voir" aria-label="Voir le formateur">
                    <?php echo $this->render_inline_icon( 'eye', 25 ); ?>
                  </a>
                  <a class="acdc-row-action-icon acdc-row-edit-link" href="<?php echo esc_url( add_query_arg( array( 'action' => 'edit', 'item_id' => $entry->id ), $base ) ); ?>" title="Modifier" aria-label="Modifier le formateur">
                    <?php echo $this->render_inline_icon( 'edit', 25 ); ?>
                  </a>
                  <a class="acdc-row-action-icon acdc-row-delete-link" href="<?php echo esc_url( wp_nonce_url( admin_url( 'admin-post.php?action=acdc_delete_trainer&trainer_id=' . $entry->id . ( is_admin() ? '&page=acdc-of-trainers' : '' ) ), 'acdc_delete_trainer_' . $entry->id ) ); ?>" title="Supprimer" aria-label="Supprimer le formateur" onclick="return confirm('Supprimer ce formateur ?');">
                    <?php echo $this->render_inline_icon( 'trash', 25 ); ?>
                  </a>
                  <!-- ACDC 3.22.7 — Menu 3 points : actions supplémentaires dont "Créer un contrat" -->
                  <div class="acdc-row-menu" data-acdc-row-menu>
                    <button type="button" class="acdc-row-menu-toggle" data-acdc-row-menu-toggle aria-expanded="false" title="Plus d'actions"><?php echo $this->render_inline_icon( 'more-horizontal', 25 ); ?></button>
                    <div class="acdc-row-menu-dropdown" data-acdc-row-menu-dropdown hidden>
                      <?php if ( 'Externe' === (string) $entry->trainer_type ) : ?>
                      <a href="<?php echo esc_url( add_query_arg( array( 'action' => 'edit', 'item_id' => $entry->id, 'show_contract_form' => '1' ), $base ) ); ?>">📋 Créer un contrat</a>
                      <?php endif; ?>
                      <a href="<?php echo esc_url( add_query_arg( array( 'action' => 'edit', 'item_id' => $entry->id ), $base ) ); ?>">✏️ Modifier</a>
                      <a href="<?php echo esc_url( wp_nonce_url( admin_url( 'admin-post.php?action=acdc_delete_trainer&trainer_id=' . $entry->id . ( is_admin() ? '&page=acdc-of-trainers' : '' ) ), 'acdc_delete_trainer_' . $entry->id ) ); ?>" style="color:#dc2626;" onclick="return confirm('Supprimer ce formateur ?');">🗑 Supprimer</a>
                    </div>
