        <input type="hidden" name="trainer_id" value="<?php echo (int) $trainer->id; ?>">
        <?php if ( $is_admin ) : ?><input type="hidden" name="page" value="acdc-of-trainers"><?php endif; ?>

        <strong style="display:block;margin-bottom:10px;color:var(--acdc-text,#1E4777);font-size:14px;">Ajouter un document</strong>

        <div class="acdc-tdoc-form-row">
          <div>
            <label for="acdc_tdoc_category_<?php echo (int) $trainer->id; ?>">Catégorie *</label>
