    <?php /* ACDC 3.20.94 — Script d'ouverture/fermeture des dialogs d'édition de document.
             Délégation d'événement sur le document : un seul listener pour tous les boutons,
             quel que soit le nombre de documents. Compatible recharge AJAX éventuelle. */ ?>
    <script>
    (function(){
      if ( window.acdcTdocEditDialogBound ) { return; }
      window.acdcTdocEditDialogBound = true;
      document.addEventListener('click', function(e){
        var openBtn = e.target.closest('[data-acdc-doc-edit]');
        if ( openBtn ) {
          var id = openBtn.getAttribute('data-acdc-doc-edit');
          var dlg = document.querySelector('dialog[data-acdc-doc-dialog="' + id + '"]');
          if ( dlg && typeof dlg.showModal === 'function' ) {
            dlg.showModal();
          } else if ( dlg ) {
            // Fallback navigateurs très anciens : affichage sans modale.
            dlg.setAttribute('open', 'open');
          }
          return;
        }
        var cancelBtn = e.target.closest('[data-acdc-doc-cancel]');
        if ( cancelBtn ) {
          var dlg2 = cancelBtn.closest('dialog');
          if ( dlg2 ) {
            if ( typeof dlg2.close === 'function' ) { dlg2.close(); }
            else { dlg2.removeAttribute('open'); }
          }
        }
      });
    })();
    </script>
    <?php
    /* ACDC 3.22.7 — Bloc Contrats formateurs intégré dans la bibliothèque. */
    if ( isset( $this->trainer_contract_table ) ) {
      global $wpdb;
      $contracts_docs = (array) $wpdb->get_results( $wpdb->prepare(
        "SELECT id, label, formation_ref, formation_id, date_start, date_end, statut, signature_status, contract_pdf_url, signed_document_url FROM {$this->trainer_contract_table} WHERE trainer_id = %d ORDER BY date_start DESC",
        (int) $trainer->id
      ) );
      if ( ! empty( $contracts_docs ) ) : ?>
    <div class="acdc-needs-section" style="margin-top:20px;">
      <div class="acdc-needs-section-title">📋 Contrats formateurs</div>
      <ul class="acdc-tdoc-list" style="margin-top:10px;">
        <?php foreach ( $contracts_docs as $cd ) :
          $is_signed  = 'signée' === (string) $cd->signature_status;
          /* ACDC 3.25.150 — F11 : le dossier /uploads des contrats est désormais interdit
             d'accès direct. On passe donc par le service authentifié, sinon le lien
             renvoie 403 même pour un gestionnaire connecté. */
          $cd_has_pdf = $is_signed ? ! empty( $cd->signed_document_url ) : ! empty( $cd->contract_pdf_url );
          $pdf_url    = $cd_has_pdf ? $this->acdc_trainer_contract_view_url( (int) $cd->id, $is_signed && ! empty( $cd->signed_document_url ) ) : '';
          $badge_col  = $is_signed ? '#1a7d3b' : ( '' !== (string) $cd->signature_status ? '#a06b00' : '#5a6577' );
          $badge_bg   = $is_signed ? '#e7f4ec'  : ( '' !== (string) $cd->signature_status ? '#fff3d6'  : '#f0f4fa' );
          $badge_lbl  = $is_signed ? 'Signé'    : ( '' !== (string) $cd->signature_status ? ucfirst( (string) $cd->signature_status ) : 'Non signé' );
          $periode    = '';
          if ( ! empty( $cd->date_start ) ) { $periode .= date_i18n( 'd/m/Y', strtotime( $cd->date_start ) ); }
          if ( ! empty( $cd->date_end )   ) { $periode .= ' → ' . date_i18n( 'd/m/Y', strtotime( $cd->date_end ) ); }
        ?>
        <li class="acdc-tdoc-item">
          <div class="acdc-tdoc-item-main">
            <span class="acdc-tdoc-item-title"><?php echo esc_html( $cd->label ); ?></span>
            <span class="acdc-tdoc-item-meta">
              <?php if ( '' !== $periode ) : ?><?php echo esc_html( $periode ); ?> — <?php endif; ?>
              <span style="display:inline-block;font-size:11px;font-weight:600;padding:1px 7px;border-radius:999px;background:<?php echo esc_attr( $badge_bg ); ?>;color:<?php echo esc_attr( $badge_col ); ?>;"><?php echo esc_html( $badge_lbl ); ?></span>
            </span>
          </div>
          <?php if ( '' !== $pdf_url ) : ?>
          <div class="acdc-tdoc-actions">
            <a href="<?php echo esc_url( $pdf_url ); ?>" target="_blank" rel="noopener" class="acdc-tdoc-btn">📄 Voir</a>
          </div>
          <?php endif; ?>
        </li>
        <?php endforeach; ?>
      </ul>
    </div>
      <?php endif;
    }
