  /**
   * ACDC 3.22.1 — Bloc "Contrats & missions" de la fiche formateur.
   * Affiche le tableau des missions, le formulaire CRUD inline et la modale de génération PDF.
   *
   * @param object $trainer
   * @param bool   $read_only
   */
  protected function render_trainer_contracts_section( $trainer, $read_only = false ) {
    global $wpdb;
    $tid      = (int) $trainer->id;
    $is_admin = is_admin();
    $contracts = (array) $wpdb->get_results( $wpdb->prepare(
      "SELECT * FROM {$this->trainer_contract_table} WHERE trainer_id = %d ORDER BY date_start DESC, id DESC",
      $tid
    ) );
    $total_h  = 0; $total_m = 0;
    foreach ( $contracts as $c ) { $total_h += (float) $c->nb_heures; $total_m += (float) $c->montant_ht; }
    // Récupère le contract_id à éditer depuis l'URL (si redirection retour après erreur)
    $edit_contract_id = isset( $_GET['edit_contract_id'] ) ? absint( $_GET['edit_contract_id'] ) : 0;
    $edit_contract    = $edit_contract_id ? $wpdb->get_row( $wpdb->prepare( "SELECT * FROM {$this->trainer_contract_table} WHERE id = %d AND trainer_id = %d", $edit_contract_id, $tid ) ) : null;
    $is_externe       = isset( $trainer->trainer_type ) && 'Externe' === (string) $trainer->trainer_type;
    // URL de base retour
    $back_url = $is_admin ? admin_url( 'admin.php?page=acdc-of-trainers&action=edit&item_id=' . $tid ) : $this->portal_page_url( array( 'tab' => 'trainers', 'action' => 'edit', 'item_id' => $tid ) );
    ?>
