      .acdc-tc-add-form .acdc-tc-row{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:10px}
      .acdc-tc-add-form .acdc-tc-row-3{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:10px}
      @media(max-width:900px){.acdc-tc-add-form .acdc-tc-row,.acdc-tc-add-form .acdc-tc-row-3{grid-template-columns:1fr 1fr}}
      @media(max-width:600px){.acdc-tc-add-form .acdc-tc-row,.acdc-tc-add-form .acdc-tc-row-3{grid-template-columns:1fr}}
