  }  private function render_front_quiz_form( $quiz = null, $read_only = false ) {
    $mode = isset( $_GET['mode'] ) ? sanitize_text_field( wp_unslash( $_GET['mode'] ) ) : '';
    if ( $quiz && ! empty( $quiz->correction_type ) ) {
      $mode = $quiz->correction_type;
    }
    if ( '' === $mode ) {
      $mode = 'Correction automatique';
    }
    $questions = array();
    if ( $quiz && ! empty( $quiz->question_blocks ) ) {
      $decoded = json_decode( $quiz->question_blocks, true );
      if ( is_array( $decoded ) ) {
        $questions = $decoded;
      }
    }
    foreach ( $questions as &$question ) {
      $choices = $this->parse_question_choices( $question );
      if ( ! isset( $question['answers'] ) || ! is_array( $question['answers'] ) ) {
        $question['answers'] = wp_list_pluck( $choices, 'label' );
      }
      if ( ! isset( $question['correct_answers'] ) || ! is_array( $question['correct_answers'] ) ) {
        $question['correct_answers'] = array();
        foreach ( $choices as $choice_index => $choice ) {
          if ( ! empty( $choice['is_correct'] ) ) {
            $question['correct_answers'][] = (string) $choice_index;
          }
        }
      } else {
        $question['correct_answers'] = array_map( 'strval', $question['correct_answers'] );
      }
    }
    unset( $question );
    if ( empty( $questions ) ) {
      $questions[] = array( 'label' => '', 'type' => '', 'options' => '', 'answers' => array( '', '' ), 'correct_answers' => array() );
    }
    $scoring = array();
    if ( $quiz && ! empty( $quiz->scoring_blocks ) ) {
      $decoded = json_decode( $quiz->scoring_blocks, true );
      if ( is_array( $decoded ) ) {
        $scoring = $decoded;
      }
    }
    if ( empty( $scoring ) ) {
      $scoring[] = array( 'type' => '', 'threshold' => '', 'label' => '' );
    }
    $value = function( $key, $default = '' ) use ( $quiz, $mode ) {
      if ( 'correction_type' === $key ) {
        return $quiz && isset( $quiz->$key ) && '' !== $quiz->$key ? $quiz->$key : $mode;
      }
      return $quiz && isset( $quiz->$key ) ? $quiz->$key : $default;
    };
    $is_auto = 'Correction automatique' === $value( 'correction_type', $mode );
    ?>
    <style>.acdc-form .acdc-field-invalid{border-color:var(--acdc-danger)!important;box-shadow:0 0 0 2px rgba(224,109,109,.12);} .acdc-form .acdc-field-help-error{display:block;margin-top:6px;color:var(--acdc-danger)!important;font-size:12px;line-height:1.45;}</style>
    <style>.acdc-needs-form .acdc-field-invalid{border-color:var(--acdc-danger)!important;box-shadow:0 0 0 2px rgba(224,109,109,.12);} .acdc-needs-form .acdc-field-help-error{display:block;margin-top:6px;color:var(--acdc-danger)!important;font-size:12px;line-height:1.45;}</style>
    <form class="acdc-form acdc-needs-form" method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>">
      <?php wp_nonce_field( 'acdc_save_quiz' ); ?>
      <input type="hidden" name="action" value="acdc_save_quiz">
      <input type="hidden" name="quiz_id" value="<?php echo $quiz ? esc_attr( $quiz->id ) : 0; ?>">
      <input type="hidden" name="quiz[correction_type]" value="<?php echo esc_attr( $value( 'correction_type', $mode ) ); ?>">
      <?php if ( is_admin() ) : ?><input type="hidden" name="page" value="acdc-of-quiz"><?php endif; ?>
      <div class="acdc-panel acdc-needs-section">
        <div class="acdc-needs-section-title">Informations</div>
        <div class="acdc-grid-2cols" style="grid-template-columns:240px minmax(0,1fr);">
          <p><label>Durée du questionnaire *</label></p>
          <div>
            <input type="number" min="1" name="quiz[duration_minutes]" required value="<?php echo esc_attr( $value( 'duration_minutes', 5 ) ); ?>" <?php echo $read_only ? 'readonly' : ''; ?> placeholder="Durée du questionnaire">
            <small>Le temps doit être déclaré en minutes</small>
          </div>
        </div>
      </div>
      <div class="acdc-panel acdc-needs-section">
        <div class="acdc-needs-section-title">Questionnaire</div>
        <div class="acdc-grid-2cols" style="grid-template-columns:240px minmax(0,1fr);">
          <p><label>Intitulé *</label></p>
          <p><input type="text" name="quiz[title]" required value="<?php echo esc_attr( $value( 'title' ) ); ?>" <?php echo $read_only ? 'readonly' : ''; ?> placeholder="Intitulé"></p>
          <p><label>Description</label></p>
