                    <select class="acdc-quiz-question-type" name="questions[<?php echo esc_attr( $index ); ?>][type]" <?php echo $read_only ? 'disabled' : ''; ?>>
                      <?php foreach ( $this->get_quiz_question_type_options() as $key => $label ) : ?>
                        <option value="<?php echo esc_attr( $key ); ?>" <?php selected( $question_type, $key ); ?>><?php echo esc_html( $label ); ?></option>
                      <?php endforeach; ?>
                    </select>
