                  <div class="acdc-quiz-choice-builder"<?php echo in_array( $question_type, array( 'Question ouverte', 'Notation' ), true ) ? ' style="display:none;"' : ''; ?>>
                    <div class="acdc-quiz-choice-builder-head" style="display:flex;justify-content:space-between;gap:12px;align-items:center;margin:10px 0 8px;">
                      <strong>Réponses proposées</strong>
                      <?php if ( ! $read_only ) : ?><button type="button" class="acdc-button acdc-button-soft acdc-quiz-add-answer">Ajouter une réponse</button><?php endif; ?>
                    </div>
                    <div class="acdc-quiz-answers-wrap">
                      <?php foreach ( $question_answers as $answer_index => $answer_label ) : ?>
                        <div class="acdc-quiz-answer-row" data-answer-index="<?php echo esc_attr( $answer_index ); ?>" style="display:grid;grid-template-columns:110px minmax(0,1fr) auto;gap:12px;align-items:center;margin-bottom:10px;">
                          <label style="display:flex;align-items:center;gap:8px;margin:0;">
                            <input type="<?php echo 'Choix multiples' === $question_type ? 'checkbox' : 'radio'; ?>" class="acdc-quiz-correct-input" name="questions[<?php echo esc_attr( $index ); ?>][correct_answers]<?php echo 'Choix multiples' === $question_type ? '[' . esc_attr( $answer_index ) . ']' : ''; ?>" value="<?php echo esc_attr( $answer_index ); ?>" <?php checked( in_array( (string) $answer_index, $question_correct, true ) ); ?> <?php echo $read_only ? 'disabled' : ''; ?>>
                            <span>Bonne réponse</span>
                          </label>
                          <input type="text" name="questions[<?php echo esc_attr( $index ); ?>][answers][<?php echo esc_attr( $answer_index ); ?>]" value="<?php echo esc_attr( $answer_label ); ?>" <?php echo $read_only ? 'readonly' : ''; ?> placeholder="Réponse <?php echo esc_attr( $answer_index + 1 ); ?>">
                          <?php if ( ! $read_only ) : ?><button type="button" class="acdc-button acdc-button-soft acdc-quiz-remove-answer">Supprimer</button><?php else : ?><span></span><?php endif; ?>
                        </div>
                      <?php endforeach; ?>
                    </div>
                  </div>
                  <div class="acdc-quiz-guidance-block"<?php echo in_array( $question_type, array( 'Question ouverte', 'Notation' ), true ) ? '' : ' style="display:none;"'; ?>>
                    <textarea name="questions[<?php echo esc_attr( $index ); ?>][options]" rows="3" <?php echo $read_only ? 'readonly' : ''; ?> placeholder="Consigne ou aide pour cette question"><?php echo esc_textarea( isset( $question['options'] ) ? $question['options'] : '' ); ?></textarea>
                    <small><?php echo 'Notation' === $question_type ? 'La notation 1 à 5 est générée automatiquement. Ajoutez ici uniquement une consigne si nécessaire.' : 'Ajoutez ici la consigne de réponse libre.'; ?></small>
                  </div>
                  <?php if ( ! $read_only ) : ?><p><button type="button" class="acdc-button acdc-remove-question acdc-button-soft">Supprimer la question</button></p><?php endif; ?>
                </div>
              <?php endforeach; ?>
            </div>
            <?php if ( ! $read_only ) : ?><button type="button" id="acdc-add-question" class="acdc-button acdc-button-primary">Ajouter une nouvelle question</button><?php endif; ?>
          </div>
        </div>
      </div>
      <div class="acdc-panel acdc-needs-section">
        <div class="acdc-needs-section-title"><?php echo $is_auto ? 'Résultats' : 'Questionnaire'; ?></div>
        <div class="acdc-grid-2cols" style="grid-template-columns:240px minmax(0,1fr);">
          <?php if ( $is_auto ) : ?>
            <p><label>Type de notation *</label></p>
            <div>
              <div id="acdc-quiz-scoring-wrap">
                <?php foreach ( $scoring as $index => $row ) : ?>
                  <div class="acdc-panel acdc-panel-block">
                    <div class="acdc-grid-score-row">
                      <select name="scoring[<?php echo esc_attr( $index ); ?>][type]" <?php echo $read_only ? 'disabled' : ''; ?>>
                        <?php foreach ( $this->get_quiz_notation_type_options() as $key => $label ) : ?>
                          <option value="<?php echo esc_attr( $key ); ?>" <?php selected( isset( $row['type'] ) ? $row['type'] : '', $key ); ?>><?php echo esc_html( $label ); ?></option>
                        <?php endforeach; ?>
                      </select>
                      <input type="text" name="scoring[<?php echo esc_attr( $index ); ?>][threshold]" value="<?php echo esc_attr( isset( $row['threshold'] ) ? $row['threshold'] : '' ); ?>" <?php echo $read_only ? 'readonly' : ''; ?> placeholder="Seuil">
                      <input type="text" name="scoring[<?php echo esc_attr( $index ); ?>][label]" value="<?php echo esc_attr( isset( $row['label'] ) ? $row['label'] : '' ); ?>" <?php echo $read_only ? 'readonly' : ''; ?> placeholder="Libellé affiché">
                    </div>
                    <?php if ( ! $read_only ) : ?><p><button type="button" class="acdc-button acdc-remove-score acdc-button-soft">Supprimer ce type</button></p><?php endif; ?>
                  </div>
                <?php endforeach; ?>
              </div>
              <?php if ( ! $read_only ) : ?><button type="button" id="acdc-add-score" class="acdc-button acdc-button-primary">Ajouter un type de notation</button><?php endif; ?>
              <p><small>“Acquis/Non acquis” : indiquez le nombre de bonnes réponses nécessaires. “Niveaux” : créez plusieurs niveaux et leur seuil.</small></p>
            </div>
          <?php else : ?>
            <p><label>Alerte notation</label></p>
            <div>
              <input type="text" name="quiz[alert_notation]" value="<?php echo esc_attr( $value( 'alert_notation' ) ); ?>" <?php echo $read_only ? 'readonly' : ''; ?> placeholder="Alerte notation">
              <p><small>Par question, en dessous de combien d’étoiles souhaitez-vous recevoir une alerte ?</small></p>
            </div>
          <?php endif; ?>
        </div>
        <?php if ( ! $read_only ) : ?>
          <p class="acdc-actions-end-wrap">
            <a class="acdc-button" href="<?php echo esc_url( is_admin() ? admin_url( 'admin.php?page=acdc-of-quiz' ) : $this->portal_page_url( array( 'tab' => 'quiz' ) ) ); ?>" class="acdc-button acdc-button-soft">Annuler</a>
            <button type="submit" class="acdc-button acdc-button-accent" name="save_and_add" value="1">Créer & ajouter un autre</button>
            <button type="submit" class="acdc-button acdc-button-soft" name="save_and_prepare_session" value="1"><?php echo $quiz ? 'Modifier et préparer une session' : 'Créer et préparer une session'; ?></button>
            <button type="submit" class="acdc-button acdc-button-primary"><?php echo $quiz ? 'Modifier un quiz' : 'Créer un quiz'; ?></button>
          </p>
        <?php else : ?>
          <p><a class="acdc-button acdc-button-primary" href="<?php echo esc_url( is_admin() ? admin_url( 'admin.php?page=acdc-of-quiz&action=edit&item_id=' . (int) $quiz->id ) : $this->portal_page_url( array( 'tab' => 'quiz', 'action' => 'edit', 'item_id' => (int) $quiz->id ) ) ); ?>">Modifier ce quiz</a></p>
        <?php endif; ?>
      </div>
      <?php if ( $quiz ) { $this->render_questionnaire_source_visibility_panel( 'quiz', (int) $quiz->id, 'Ce quiz' ); } else { $this->render_questionnaire_source_pending_panel( 'ce quiz' ); } ?>
      <?php if ( ! $read_only ) : ?>
      <script>
      document.addEventListener('DOMContentLoaded',function(){
        var qWrap=document.getElementById('acdc-quiz-questions-wrap');
        var addQ=document.getElementById('acdc-add-question');
        function escapeAttr(value){return String(value||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
        function isChoiceType(type){return type && ['Choix unique','Choix multiples','Cases à cocher'].indexOf(type)!==-1;}
        function answerInputType(type){return type==='Choix multiples' ? 'checkbox' : 'radio';}
        function answerRowHtml(qIndex,aIndex,type,value,checked){
          var inputType=answerInputType(type);
          var checkedAttr=checked?' checked':'';
          var correctName='questions['+qIndex+'][correct_answers]'+(inputType==='checkbox'?'['+aIndex+']':'');
          return '<div class="acdc-quiz-answer-row" data-answer-index="'+aIndex+'" style="display:grid;grid-template-columns:110px minmax(0,1fr) auto;gap:12px;align-items:center;margin-bottom:10px;">'
            +'<label style="display:flex;align-items:center;gap:8px;margin:0;"><input type="'+inputType+'" class="acdc-quiz-correct-input" name="'+correctName+'" value="'+aIndex+'"'+checkedAttr+'><span>Bonne réponse</span></label>'
            +'<input type="text" name="questions['+qIndex+'][answers]['+aIndex+']" value="'+escapeAttr(value||'')+'" placeholder="Réponse '+(aIndex+1)+'">'
            +'<button type="button" class="acdc-button acdc-button-soft acdc-quiz-remove-answer">Supprimer</button>'
            +'</div>';
        }
        function reindexQuestionBlock(block,qIndex){
          block.setAttribute('data-index',qIndex);
          block.querySelectorAll('input,textarea,select').forEach(function(field){
            if(field.name){field.name=field.name.replace(/questions\[\d+\]/g,'questions['+qIndex+']');}
          });
          var typeSelect=block.querySelector('.acdc-quiz-question-type');
          var type=typeSelect?typeSelect.value:'';
          var rows=block.querySelectorAll('.acdc-quiz-answer-row');
          rows.forEach(function(row,aIndex){
            row.setAttribute('data-answer-index',aIndex);
            var textInput=row.querySelector('input[type="text"]');
            if(textInput){textInput.name='questions['+qIndex+'][answers]['+aIndex+']';textInput.placeholder='Réponse '+(aIndex+1);}
            var correctInput=row.querySelector('.acdc-quiz-correct-input');
            if(correctInput){correctInput.type=answerInputType(type);correctInput.value=String(aIndex);correctInput.name='questions['+qIndex+'][correct_answers]'+(correctInput.type==='checkbox'?'['+aIndex+']':'');}
          });
        }
        function refreshQuestionVisibility(block){
          var typeSelect=block.querySelector('.acdc-quiz-question-type');
          var type=typeSelect?typeSelect.value:'';
          var builder=block.querySelector('.acdc-quiz-choice-builder');
          var guidance=block.querySelector('.acdc-quiz-guidance-block');
          if(builder){builder.style.display=isChoiceType(type)?'block':'none';}
          if(guidance){guidance.style.display=isChoiceType(type)?'none':'block';}
          reindexQuestionBlock(block, parseInt(block.getAttribute('data-index')||'0',10));
        }
        function ensureMinimumAnswers(block){
          var wrap=block.querySelector('.acdc-quiz-answers-wrap');
          var type=(block.querySelector('.acdc-quiz-question-type')||{}).value||'';
          if(!wrap || !isChoiceType(type)){return;}
          if(wrap.querySelectorAll('.acdc-quiz-answer-row').length===0){
            wrap.insertAdjacentHTML('beforeend',answerRowHtml(block.getAttribute('data-index')||0,0,type,'',false));
            wrap.insertAdjacentHTML('beforeend',answerRowHtml(block.getAttribute('data-index')||0,1,type,'',false));
            reindexQuestionBlock(block, parseInt(block.getAttribute('data-index')||'0',10));
          }
        }
        if(addQ&&qWrap){addQ.addEventListener('click',function(){
          var i=qWrap.querySelectorAll('.acdc-quiz-question-block').length;
          var d=document.createElement('div');
          d.className='acdc-panel acdc-panel-block acdc-quiz-question-block';
          d.setAttribute('data-index',i);
          d.innerHTML='<div class="acdc-grid-question-row"><input type="text" name="questions['+i+'][label]" placeholder="Intitulé de la question"><select class="acdc-quiz-question-type" name="questions['+i+'][type]"><?php foreach ( $this->get_quiz_question_type_options() as $key => $label ) : ?><option value="<?php echo esc_attr( $key ); ?>"><?php echo esc_js( $label ); ?></option><?php endforeach; ?></select></div>'
            +'<div class="acdc-quiz-choice-builder" style="display:none;"><div class="acdc-quiz-choice-builder-head" style="display:flex;justify-content:space-between;gap:12px;align-items:center;margin:10px 0 8px;"><strong>Réponses proposées</strong><button type="button" class="acdc-button acdc-button-soft acdc-quiz-add-answer">Ajouter une réponse</button></div><div class="acdc-quiz-answers-wrap"></div></div>'
            +'<div class="acdc-quiz-guidance-block"><textarea name="questions['+i+'][options]" rows="3" placeholder="Consigne ou aide pour cette question"></textarea><small>Ajoutez ici la consigne de réponse libre.</small></div>'
            +'<p><button type="button" class="acdc-button acdc-remove-question acdc-button-soft">Supprimer la question</button></p>';
          qWrap.appendChild(d);
        });
          qWrap.addEventListener('click',function(e){
            var block=e.target.closest('.acdc-quiz-question-block');
            if(!block){return;}
            if(e.target.classList.contains('acdc-remove-question')){e.preventDefault();block.remove();qWrap.querySelectorAll('.acdc-quiz-question-block').forEach(function(item,idx){reindexQuestionBlock(item,idx);});}
            if(e.target.classList.contains('acdc-quiz-add-answer')){e.preventDefault();var wrap=block.querySelector('.acdc-quiz-answers-wrap');if(!wrap){return;}var type=(block.querySelector('.acdc-quiz-question-type')||{}).value||'';var nextIndex=wrap.querySelectorAll('.acdc-quiz-answer-row').length;wrap.insertAdjacentHTML('beforeend',answerRowHtml(block.getAttribute('data-index')||0,nextIndex,type,'',false));reindexQuestionBlock(block,parseInt(block.getAttribute('data-index')||'0',10));}
            if(e.target.classList.contains('acdc-quiz-remove-answer')){e.preventDefault();e.target.closest('.acdc-quiz-answer-row').remove();ensureMinimumAnswers(block);reindexQuestionBlock(block,parseInt(block.getAttribute('data-index')||'0',10));}
          });
          qWrap.addEventListener('change',function(e){
            if(e.target.classList.contains('acdc-quiz-question-type')){var block=e.target.closest('.acdc-quiz-question-block');refreshQuestionVisibility(block);ensureMinimumAnswers(block);}
          });
          qWrap.querySelectorAll('.acdc-quiz-question-block').forEach(function(block,idx){reindexQuestionBlock(block,idx);refreshQuestionVisibility(block);ensureMinimumAnswers(block);});
        }
        var sWrap=document.getElementById('acdc-quiz-scoring-wrap');
        var addS=document.getElementById('acdc-add-score');
        if(addS&&sWrap){addS.addEventListener('click',function(){var i=sWrap.querySelectorAll('.acdc-panel').length;var d=document.createElement('div');d.className='acdc-panel acdc-panel-block';d.innerHTML='<div class="acdc-grid-score-row"><select name="scoring['+i+'][type]"><?php foreach ( $this->get_quiz_notation_type_options() as $key => $label ) : ?><option value="<?php echo esc_attr( $key ); ?>"><?php echo esc_js( $label ); ?></option><?php endforeach; ?></select><input type="text" name="scoring['+i+'][threshold]" placeholder="Seuil"><input type="text" name="scoring['+i+'][label]" placeholder="Libellé affiché"></div><p><button type="button" class="acdc-button acdc-remove-score acdc-button-soft">Supprimer ce type</button></p>';sWrap.appendChild(d);});
          sWrap.addEventListener('click',function(e){if(e.target.classList.contains('acdc-remove-score')){e.preventDefault();e.target.closest('.acdc-panel').remove();}});
        }
      });
      </script>
      <?php endif; ?>
    </form>
    <?php
  }  private function render_front_funders_tab( $action, $item_id ) {
    $funder = $item_id ? $this->get_funder( $item_id ) : null;
    $funders = $this->get_funders();
    $search = isset( $_GET['q'] ) ? sanitize_text_field( wp_unslash( $_GET['q'] ) ) : '';
    if ( '' !== $search ) {
      $funders = array_values( array_filter( $funders, function( $entry ) use ( $search ) {
        $haystack = implode( ' ', array(
          isset( $entry->name ) ? $entry->name : '',
          isset( $entry->sector ) ? $entry->sector : '',
          isset( $entry->address ) ? $entry->address : '',
          isset( $entry->city ) ? $entry->city : '',
          isset( $entry->postal_code ) ? $entry->postal_code : '',
          isset( $entry->phone ) ? $entry->phone : '',
          isset( $entry->email ) ? $entry->email : '',
          isset( $entry->website ) ? $entry->website : '',
          isset( $entry->contact_type ) ? $entry->contact_type : '',
          isset( $entry->has_paca_presence ) ? $entry->has_paca_presence : '',
          isset( $entry->paca_contact_details ) ? $entry->paca_contact_details : '',
          isset( $entry->funder_type ) ? $entry->funder_type : ''
        ) );
        return false !== stripos( $haystack, $search );
      } ) );
    }
    $new_url = is_admin() ? admin_url( 'admin.php?page=acdc-of-funders&action=new' ) : $this->portal_page_url( array( 'tab' => 'funders', 'action' => 'new' ) );
    $page_title = $this->acdc_get_action_page_title( $action, 'Financeurs', 'Créer un financeur', 'Modifier un financeur', 'Voir un financeur' );
    ?>
    <section class="acdc-section-head">
      <div>
        <h2><?php echo esc_html( $page_title ); ?></h2>
        <p>Gestion des financeurs avec coordonnées complètes, présence PACA et liens de contact régionaux.</p>
      </div>
      <div class="acdc-inline-wrap">
        <?php if ( 'view' === $action && $funder && ! empty( $funder->email ) ) : ?>
        <button type="button" class="acdc-button acdc-button-soft" data-acdc-modal-open="acdc-direct-email-modal-funder-<?php echo (int) $funder->id; ?>">&#x2709; Envoyer un e-mail</button>
        <?php endif; ?>
        <a class="acdc-button acdc-button-primary" href="<?php echo esc_url( $new_url ); ?>">Créer un financeur</a>
      </div>
    </section>
    <?php
    if ( in_array( $action, array( 'new', 'edit', 'view' ), true ) ) {
      $this->render_front_funder_form( $funder, 'view' === $action );
      if ( in_array( $action, array( 'edit', 'view' ), true ) ) {
        return;
      }
    }
    ?>
    <div class="acdc-panel acdc-mb-18">
      <form method="get" action="">
        <?php if ( is_admin() ) : ?>
          <input type="hidden" name="page" value="acdc-of-funders">
        <?php endif; ?>
        <input type="hidden" name="tab" value="funders">
        <div class="acdc-inline-wrap acdc-inline-wrap-center">
          <input type="search" name="q" value="<?php echo esc_attr( $search ); ?>" placeholder="Rechercher" style="max-width:420px;">
          <button type="submit" class="acdc-button acdc-button-soft">Rechercher</button>
        </div>
      </form>
    </div>
    <div class="acdc-panel">
      <div class="acdc-table-wrap">
        <table class="acdc-table" data-acdc-table-id="funders-list">
          <thead>
            <tr>
              <th>Nom OPCO</th>
              <th>Secteur</th>
              <th>Adresse</th>
              <th>Ville</th>
              <th>Code postal</th>
              <th>Téléphone</th>
              <th>E-mail</th>
              <th>Site web</th>
              <th>Type contact</th>
              <th>Présence PACA</th>
              <th>Page contact + coordonnées PACA</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
          <?php if ( ! empty( $funders ) ) : ?>
            <?php foreach ( $funders as $entry ) : ?>
              <tr>
                <td><?php echo esc_html( ! empty( $entry->name ) ? $entry->name : '—' ); ?></td>
                <td><?php echo esc_html( ! empty( $entry->sector ) ? $entry->sector : '—' ); ?></td>
                <td><?php echo esc_html( ! empty( $entry->address ) ? $entry->address : '—' ); ?></td>
                <td><?php echo esc_html( ! empty( $entry->city ) ? $entry->city : '—' ); ?></td>
                <td><?php echo esc_html( ! empty( $entry->postal_code ) ? $entry->postal_code : '—' ); ?></td>
                <td><?php echo esc_html( ! empty( $entry->phone ) ? $entry->phone : '—' ); ?></td>
                <td><?php echo esc_html( ! empty( $entry->email ) ? $entry->email : '—' ); ?></td>
                <td><?php if ( ! empty( $entry->website ) ) : ?><a href="<?php echo esc_url( $entry->website ); ?>" target="_blank" rel="noopener noreferrer"><?php echo esc_html( preg_replace( '#^https?://#', '', $entry->website ) ); ?></a><?php else : ?>—<?php endif; ?></td>
                <td><?php echo esc_html( ! empty( $entry->contact_type ) ? $entry->contact_type : '—' ); ?></td>
                <td><?php echo esc_html( ! empty( $entry->has_paca_presence ) ? $entry->has_paca_presence : '—' ); ?></td>
                <td><?php if ( ! empty( $entry->paca_contact_details ) ) : ?><div style="max-width:320px;white-space:normal;"><?php echo nl2br( esc_html( $entry->paca_contact_details ) ); ?></div><?php else : ?>—<?php endif; ?></td>
                <td>
                  <?php $base = is_admin() ? admin_url( 'admin.php?page=acdc-of-funders' ) : $this->portal_page_url( array( 'tab' => 'funders' ) ); ?>
                  <a href="<?php echo esc_url( add_query_arg( array( 'action' => 'view', 'item_id' => $entry->id ), $base ) ); ?>">Voir</a>
                  <span> | </span>
                  <a href="<?php echo esc_url( add_query_arg( array( 'action' => 'edit', 'item_id' => $entry->id ), $base ) ); ?>">Modifier</a>
                  <span> | </span>
                  <a href="<?php echo esc_url( wp_nonce_url( admin_url( 'admin-post.php?action=acdc_delete_funder&funder_id=' . $entry->id . ( is_admin() ? '&page=acdc-of-funders' : '' ) ), 'acdc_delete_funder_' . $entry->id ) ); ?>" onclick="return confirm('Supprimer ce financeur ?');">Supprimer</a>
                </td>
              </tr>
            <?php endforeach; ?>
          <?php else : ?>
            <tr><td colspan="12">Aucun financeur enregistré.</td></tr>
          <?php endif; ?>
          </tbody>
        </table>
      </div>
    </div>
    <?php
  }  private function render_front_funder_form( $funder = null, $read_only = false ) {
    $state = ! $read_only ? $this->acdc_consume_form_state( 'funder' ) : array();
    $state_input = ( ! empty( $state['input'] ) && is_array( $state['input'] ) ) ? $state['input'] : array();
