  }  private function render_front_groups_tab( $action, $item_id ) {
    $group = $item_id ? $this->get_group( $item_id ) : null;
    $groups = $this->get_groups();
    $search = isset( $_GET['q'] ) ? sanitize_text_field( wp_unslash( $_GET['q'] ) ) : '';
    if ( '' !== $search ) {
      $groups = array_values( array_filter( $groups, function( $entry ) use ( $search ) {
        $haystack = implode( ' ', array( $entry->name, $entry->comment_text, $entry->formation_title, $entry->trainer_name, $entry->attendance_method ) );
        return false !== stripos( $haystack, $search );
      } ) );
    }
    $new_url = is_admin() ? admin_url( 'admin.php?page=acdc-of-groups&action=new' ) : $this->portal_page_url( array( 'tab' => 'groups', 'action' => 'new' ) );
    $page_title = $this->acdc_get_action_page_title( $action, 'Groupes', 'Créer un groupe', 'Modifier un groupe', 'Voir un groupe' );
    ?>
    <section class="acdc-section-head">
      <div>
        <h2><?php echo esc_html( $page_title ); ?></h2>
        <p>Organisation des groupes de formation et suivi synthétique des apprenants rattachés.</p>
      </div>
      <div class="acdc-inline-wrap">
        <a class="acdc-button acdc-button-primary" href="<?php echo esc_url( $new_url ); ?>">Créer un groupe</a>
      </div>
    </section>
    <?php
    if ( 'documents' === $action ) {
      $this->render_front_group_document_space( $group );
      return;
    }
    if ( in_array( $action, array( 'new', 'edit', 'view' ), true ) ) {
      $this->render_front_group_form( $group, 'view' === $action );
      // Pages Créer / Voir / Modifier un groupe : aucune recherche ni liste parasite sous le formulaire.
      return;
    }
    ?>
