                    $register_url = is_admin()
                      ? admin_url( 'admin.php?page=acdc-of-register-training&action=new&group_id=' . (int) $entry->id )
                      : $this->portal_page_url( array( 'tab' => 'register_training', 'action' => 'new', 'group_id' => (int) $entry->id ) );
                    $documents_url = add_query_arg( array( 'action' => 'documents', 'item_id' => (int) $entry->id ), $base );
                    $interrupt_url = wp_nonce_url( admin_url( 'admin-post.php?action=acdc_interrupt_group&group_id=' . (int) $entry->id . ( is_admin() ? '&page=acdc-of-groups' : '' ) ), 'acdc_interrupt_group_' . (int) $entry->id );
