  }  private function render_front_group_document_space( $group ) {
    if ( ! $group ) {
      echo '<div class="acdc-panel"><p>Groupe introuvable.</p></div>';
      return;
    }
    $this->acdc_ensure_group_document_space( $group );
    $base = is_admin() ? admin_url( 'admin.php?page=acdc-of-groups' ) : $this->portal_page_url( array( 'tab' => 'groups' ) );
    $families = array(
      'Quiz effectués',
      'Feuilles d’émargement',
      'Programmes de formation',
      'Analyses du besoin',
      'Conventions / Contrats',
      'Convocations de début de formation',
      'Résultats tests de positionnement',
      'Enquêtes intermédiaires',
      'Enquêtes à chaud',
      'Résultat évaluations des acquis',
      'Certificats de réalisation',
      'Attestations de fin de formation',
      'Enquêtes à froid',
    );
    ?>
    <div class="acdc-panel acdc-group-document-space">
      <div class="acdc-needs-section-title">Espace documents du groupe</div>
      <p class="acdc-help">Cet espace regroupe les documents liés au groupe, à la formation concernée et à la session de formation.</p>
      <div class="acdc-grid-2cols acdc-mb-18">
        <p><label>Groupe</label><input type="text" readonly value="<?php echo esc_attr( $group->name ?: '—' ); ?>"></p>
        <p><label>Formation</label><input type="text" readonly value="<?php echo esc_attr( $group->formation_title ?: '—' ); ?>"></p>
        <p><label>Date de début</label><input type="text" readonly value="<?php echo esc_attr( ! empty( $group->start_date ) ? mysql2date( 'd/m/Y', $group->start_date ) : '—' ); ?>"></p>
        <p><label>Date de fin</label><input type="text" readonly value="<?php echo esc_attr( ! empty( $group->end_date ) ? mysql2date( 'd/m/Y', $group->end_date ) : '—' ); ?>"></p>
      </div>
      <div class="acdc-table-wrap">
        <table class="acdc-table acdc-group-documents-table">
          <thead><tr><th>Famille documentaire</th><th>Rattachement</th><th>Statut</th></tr></thead>
          <tbody>
            <?php foreach ( $families as $family ) : ?>
              <tr>
                <td><?php echo esc_html( $family ); ?></td>
                <td><?php echo esc_html( 'Groupe #' . (int) $group->id . ' — ' . ( $group->formation_title ?: 'formation non renseignée' ) ); ?></td>
                <td><span class="acdc-badge acdc-badge-soft">Espace prêt</span></td>
              </tr>
            <?php endforeach; ?>
          </tbody>
        </table>
      </div>
      <p class="acdc-actions-end-wrap"><a class="acdc-button acdc-button-soft" href="<?php echo esc_url( $base ); ?>">Retour aux groupes</a></p>
    </div>
    <?php
  }  private function render_front_group_form( $group = null, $read_only = false ) {
    /* ACDC 3.20.92 — Conservation des données saisies en cas d'erreur formulaire
       (mécanisme transverse `acdc_consume_form_state` désormais aligné sur les autres modules). */
    $state = ! $read_only ? $this->acdc_consume_form_state( 'group' ) : array();
    $state_input = ( ! empty( $state['input'] ) && is_array( $state['input'] ) ) ? $state['input'] : array();
    $required_fields = ( ! empty( $state['required_fields'] ) && is_array( $state['required_fields'] ) ) ? array_values( array_unique( array_map( 'sanitize_key', $state['required_fields'] ) ) ) : array();
    $value = function( $key, $default = '' ) use ( $group, $state_input ) {
      if ( array_key_exists( $key, $state_input ) && ! is_array( $state_input[ $key ] ) ) {
        return $state_input[ $key ];
      }
      return $group && isset( $group->$key ) ? $group->$key : $default;
    };
    $field_class = function( $key ) use ( $required_fields ) { return in_array( sanitize_key( $key ), $required_fields, true ) ? ' class="acdc-field-invalid"' : ''; };
    $invalid_note = function( $key ) use ( $required_fields ) { return in_array( sanitize_key( $key ), $required_fields, true ) ? '<span class="acdc-field-help acdc-field-help-error">Champ obligatoire à renseigner.</span>' : ''; };
    /* ACDC 3.20.92 — Liste des formateurs pour le <select>. Tri alphabétique nom/prénom
       (le helper get_trainers() trie par created_at DESC, ce qui est inadapté pour un select). */
    $trainers_for_select = $this->get_trainers();
    usort( $trainers_for_select, function( $a, $b ) {
      $key_a = strtolower( (string) $a->last_name . ' ' . (string) $a->first_name );
      $key_b = strtolower( (string) $b->last_name . ' ' . (string) $b->first_name );
      return strcmp( $key_a, $key_b );
    } );
    $current_trainer_id = (int) $value( 'trainer_id', 0 );

    /* Formations pour le select */
    $formations_for_select = $this->get_formations( array( 'archived' => false ) );
    $current_formation_id = (int) $value( 'formation_id', 0 );

    /* Apprenants pour la liste de sélection */
    global $wpdb;
    $all_learners = $wpdb->get_results(
      "SELECT id, first_name, usage_last_name, email FROM {$this->learner_table} ORDER BY usage_last_name ASC, first_name ASC"
    );

    /* IDs apprenants actuellement dans le groupe */
    $selected_learner_ids = array();
    if ( ! empty( $state_input['learner_ids'] ) && is_array( $state_input['learner_ids'] ) ) {
      $selected_learner_ids = array_map( 'absint', $state_input['learner_ids'] );
    } elseif ( $group && ! empty( $group->learner_ids ) ) {
      $selected_learner_ids = array_filter( array_map( 'absint', explode( ',', (string) $group->learner_ids ) ) );
    }

    /* Conventions (registration_contracts) pour l'import en masse */
    $conventions = $wpdb->get_results(
      "SELECT id, title, learner_ids, formation_id FROM {$this->registration_contract_table} WHERE learner_ids IS NOT NULL AND learner_ids != '' ORDER BY title ASC"
    );
    $conventions_data = array();
    foreach ( $conventions as $conv ) {
      $conv_learner_ids = array_values( array_filter( array_map( 'absint', explode( ',', (string) $conv->learner_ids ) ) ) );
      if ( ! empty( $conv_learner_ids ) ) {
        $conventions_data[] = array(
          'id'           => (int) $conv->id,
          'title'        => $conv->title,
          'learner_ids'  => $conv_learner_ids,
          'formation_id' => (int) $conv->formation_id,
        );
      }
    }
    ?>
    <style>.acdc-needs-form .acdc-field-invalid{border-color:var(--acdc-danger)!important;box-shadow:0 0 0 2px rgba(224,109,109,.12);} .acdc-needs-form .acdc-field-help-error{display:block;margin-top:6px;color:var(--acdc-danger)!important;font-size:12px;line-height:1.45;}
    .acdc-group-learner-list{max-height:260px;overflow-y:auto;border:1px solid var(--acdc-border);border-radius:8px;padding:8px 12px;background:#fff;}
    .acdc-group-learner-list label{display:flex;align-items:center;gap:8px;padding:5px 0;font-size:13px;cursor:pointer;border-bottom:1px solid #f4f4f4;}
    .acdc-group-learner-list label:last-child{border-bottom:none;}
    .acdc-group-learner-list input[type=checkbox]{width:16px;height:16px;flex-shrink:0;}
    .acdc-group-learner-search{width:100%;margin-bottom:8px;}
    .acdc-group-import-row{display:flex;gap:10px;align-items:center;flex-wrap:wrap;}
    .acdc-group-import-row select{flex:1;min-width:200px;}
    </style>
    <form class="acdc-form acdc-needs-form" method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>">
      <?php wp_nonce_field( 'acdc_save_group' ); ?>
      <input type="hidden" name="action" value="acdc_save_group">
      <input type="hidden" name="group_id" value="<?php echo $group ? esc_attr( $group->id ) : 0; ?>">
      <?php if ( is_admin() ) : ?><input type="hidden" name="page" value="acdc-of-groups"><?php endif; ?>
      <div class="acdc-panel acdc-needs-section">
        <div class="acdc-needs-section-title">Informations</div>
        <div class="acdc-grid-2cols" style="grid-template-columns:220px minmax(0,1fr);">
          <p><label>Nom *</label></p>
          <p><input type="text" name="group[name]" required value="<?php echo esc_attr( $value( 'name' ) ); ?>" <?php echo $read_only ? 'readonly' : ''; ?> placeholder="Indiquez le label du groupe"<?php echo $field_class( 'name' ); ?>><?php echo $invalid_note( 'name' ); ?></p>

          <p><label>Formation</label></p>
          <p>
            <select name="group[formation_id]" id="acdc-group-formation-select" <?php disabled( $read_only ); ?>>
              <option value="0">— Aucune formation associée —</option>
              <?php foreach ( $formations_for_select as $fo ) : ?>
                <option value="<?php echo esc_attr( $fo->id ); ?>" <?php selected( $current_formation_id, (int) $fo->id ); ?>><?php echo esc_html( $fo->title ); ?></option>
              <?php endforeach; ?>
            </select>
          </p>

          <p><label>Formateur</label></p>
          <p>
            <?php /* ACDC 3.20.92 — Désignation du formateur via select id-based (remplace la chaîne libre trainer_name historique non-éditable).
                     trainer_name reste calculée automatiquement côté handler pour la rétrocompatibilité (merge tags PDF, extranet apprenant). */ ?>
            <select name="group[trainer_id]" <?php disabled( $read_only ); ?>>
              <option value="0">— Aucun formateur désigné —</option>
              <?php foreach ( $trainers_for_select as $tr ) :
                $tr_label = trim( (string) $tr->first_name . ' ' . (string) $tr->last_name );
                if ( '' === $tr_label ) { $tr_label = '(sans nom)'; }
              ?>
                <option value="<?php echo esc_attr( $tr->id ); ?>" <?php selected( $current_trainer_id, (int) $tr->id ); ?>><?php echo esc_html( $tr_label ); ?></option>
