    <script>
    function acdcGroupFilterLearners(q) {
      var list = document.getElementById('acdc-group-learner-list');
      if (!list) return;
      var term = q.trim().toLowerCase();
      var labels = list.querySelectorAll('label[data-name]');
      labels.forEach(function(el) {
        el.style.display = (term === '' || el.getAttribute('data-name').indexOf(term) !== -1) ? '' : 'none';
      });
    }
    function acdcGroupImportConvention() {
      var sel = document.getElementById('acdc-group-convention-select');
      if (!sel || !sel.value) return;
      var opt = sel.options[sel.selectedIndex];
      var lids = (opt.getAttribute('data-learners') || '').split(',').map(function(s){ return s.trim(); }).filter(Boolean);
      var formationId = opt.getAttribute('data-formation') || '';
      // Cocher les apprenants
      var list = document.getElementById('acdc-group-learner-list');
      lids.forEach(function(lid) {
        var cb = list ? list.querySelector('input[type=checkbox][value="' + lid + '"]') : null;
        if (cb) cb.checked = true;
      });
      // Préremplir la formation si elle est vide
      if (formationId && formationId !== '0') {
        var formSel = document.getElementById('acdc-group-formation-select');
        if (formSel && (!formSel.value || formSel.value === '0')) {
          formSel.value = formationId;
        }
      }
      acdcGroupUpdateCount();
    }
    function acdcGroupUpdateCount() {
      var list = document.getElementById('acdc-group-learner-list');
      var counter = document.getElementById('acdc-group-learner-count');
      if (!list || !counter) return;
      var n = list.querySelectorAll('input[type=checkbox]:checked').length;
      counter.textContent = n + ' apprenant' + (n !== 1 ? 's' : '') + ' sélectionné' + (n !== 1 ? 's' : '');
    }
    (function(){
      var list = document.getElementById('acdc-group-learner-list');
      if (list) {
        list.addEventListener('change', function(e) {
          if (e.target && e.target.type === 'checkbox') acdcGroupUpdateCount();
        });
      }
    })();
    </script>
    <?php
  }  private function render_front_need_form( $need, $companies, $contacts ) {
    $current_user_name = wp_get_current_user()->display_name;
    $state = ! $need ? $this->acdc_consume_form_state( 'need' ) : array();
    $state_input = ( ! empty( $state['input'] ) && is_array( $state['input'] ) ) ? $state['input'] : array();
    $required_fields = ( ! empty( $state['required_fields'] ) && is_array( $state['required_fields'] ) ) ? array_values( array_unique( array_map( 'sanitize_key', $state['required_fields'] ) ) ) : array();
    $current_query_prospect_id = isset( $_GET['prospect_id'] ) ? absint( $_GET['prospect_id'] ) : 0;
    $stored_prospect_id = isset( $state_input['source_prospect_id'] ) ? absint( $state_input['source_prospect_id'] ) : 0;
    $need_prospect_id = ( $need && ! empty( $need->source_prospect_id ) ) ? absint( $need->source_prospect_id ) : 0;
    $source_prospect_id = $current_query_prospect_id ? $current_query_prospect_id : ( $stored_prospect_id ? $stored_prospect_id : $need_prospect_id );
    $source_prospect = null;
    $prefill_company_id = 0;
    $prefill_contact_id = 0;
    if ( $source_prospect_id ) {
      $source_prospect = $this->get_prospect( $source_prospect_id );
      if ( $source_prospect ) {
        $prefill_company_id = (int) $this->acdc_find_company_id_from_prospect( $source_prospect, $companies );
        if ( ! $prefill_company_id && $need && ! empty( $need->company_id ) ) {
          $prefill_company_id = (int) $need->company_id;
        }
        if ( $prefill_company_id ) {
          $prefill_contact_id = (int) $this->acdc_find_contact_id_from_prospect( $source_prospect, $prefill_company_id );
        }
        if ( ! $prefill_contact_id && $need && ! empty( $need->contact_id ) ) {
          $prefill_contact_id = (int) $need->contact_id;
        }
      }
    }
    $value = function( $key, $default = '' ) use ( $need, $state_input, $prefill_company_id, $prefill_contact_id, $source_prospect_id, &$source_prospect, &$current_user_name ) {
      if ( array_key_exists( $key, $state_input ) ) {
        return $state_input[ $key ];
      }
      if ( 'source_prospect_id' === $key && $source_prospect_id ) {
        return $source_prospect_id;
      }
      if ( $need && isset( $need->$key ) && '' !== (string) $need->$key ) {
        return $need->$key;
      }
      if ( 'company_id' === $key && $prefill_company_id ) {
        return $prefill_company_id;
      }
      if ( 'contact_id' === $key && $prefill_contact_id ) {
        return $prefill_contact_id;
      }
      /* Préfill automatique depuis le prospect lié (création uniquement) */
      if ( ! $need && $source_prospect ) {
        if ( 'theme' === $key ) {
          $desired = trim( (string) ( $source_prospect->desired_training ?? '' ) );
          if ( '' !== $desired ) {
            $theme_keys = array_keys( $this->get_need_theme_options() );
            $desired_lc = strtolower( $desired );
            foreach ( $theme_keys as $tk ) {
              if ( '' === $tk ) { continue; }
              if ( strtolower( $tk ) === $desired_lc || false !== strpos( $desired_lc, strtolower( $tk ) ) || false !== strpos( strtolower( $tk ), $desired_lc ) ) {
                return $tk;
              }
            }
            return 'Autre';
          }
        }
        if ( 'collection_channel' === $key ) {
          $source = trim( (string) ( $source_prospect->source ?? '' ) );
          $source_map = array(
            'Recommandation' => 'Recommandation',
            'Bouche à oreille' => 'Recommandation',
            'LinkedIn'        => 'Réseau social',
            'Facebook'        => 'Réseau social',
            'Réseau social'   => 'Réseau social',
            'Site internet'   => 'Formulaire web',
            'Moteur de recherche' => 'Formulaire web',
            'Organique'       => 'Formulaire web',
          );
          if ( isset( $source_map[ $source ] ) ) {
            return $source_map[ $source ];
          }
        }
        if ( 'acdc_interlocutor' === $key && ! empty( $source_prospect->assigned_to ) ) {
          return (string) $source_prospect->assigned_to;
        }
        if ( 'planned_funding' === $key && ! empty( $source_prospect->planned_funding ) ) {
          return (string) $source_prospect->planned_funding;
        }
        if ( 'funder_id' === $key && ! empty( $source_prospect->funder_id ) ) {
          return (string) $source_prospect->funder_id;
        }
      }
      /* Fallback interlocuteur = utilisateur connecté */
      if ( 'acdc_interlocutor' === $key && '' === $default ) {
        return $current_user_name;
      }
      return $default;
    };
    $field_class = function( $key ) use ( $required_fields ) {
      return in_array( sanitize_key( $key ), $required_fields, true ) ? ' class="acdc-field-invalid"' : '';
    };
    $invalid_note = function( $key ) use ( $required_fields ) {
      return in_array( sanitize_key( $key ), $required_fields, true ) ? '<span class="acdc-field-help acdc-field-help-error">Champ obligatoire à renseigner.</span>' : '';
    };
    $auto_lock_company = (bool) $source_prospect && ( $prefill_company_id || ( $need && ! empty( $need->company_id ) ) );
    $select = function( $name, $label, $options, $selected, $required = false ) use ( $field_class, $invalid_note ) {
      ?>
      <p>
        <label><?php echo esc_html( $label ); ?><?php echo $required ? ' *' : ''; ?></label>
        <select name="need[<?php echo esc_attr( $name ); ?>]" <?php echo $required ? 'required' : ''; ?><?php echo $field_class( $name ); ?>>
          <?php foreach ( $options as $option_value => $option_label ) : ?>
            <option value="<?php echo esc_attr( $option_value ); ?>" <?php selected( (string) $selected, (string) $option_value ); ?>><?php echo esc_html( $option_label ); ?></option>
          <?php endforeach; ?>
        </select>
        <?php echo $invalid_note( $name ); ?>
      </p>
      <?php
    };
    ?>
    <style>.acdc-needs-form .acdc-field-invalid{border-color:var(--acdc-danger)!important;box-shadow:0 0 0 2px rgba(224,109,109,.12);} .acdc-needs-form .acdc-field-help-error{display:block;margin-top:6px;color:var(--acdc-danger)!important;font-size:12px;line-height:1.45;}</style>
    <form class="acdc-form acdc-needs-form" method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>">
      <?php wp_nonce_field( 'acdc_save_need' ); ?>
