      <input type="hidden" name="need_id" value="<?php echo $need ? esc_attr( $need->id ) : 0; ?>">
      <input type="hidden" name="return_after_save" value="edit">
      <input type="hidden" name="need[source_prospect_id]" value="<?php echo esc_attr( (int) $value( 'source_prospect_id', 0 ) ); ?>">
      <?php if ( is_admin() ) : ?><input type="hidden" name="page" value="acdc-of-needs"><?php endif; ?>

      <div class="acdc-panel acdc-needs-section">
        <div class="acdc-needs-section-title">1. Identification</div>
        <?php if ( $source_prospect ) : ?>
          <div class="acdc-inline-notice" style="margin-bottom:18px;padding:12px 14px;border:1px solid var(--acdc-border);border-radius:10px;background:#fff8e8;color:#0C2D52;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;">
            <div><strong>Prospect lié automatiquement :</strong> <?php echo esc_html( trim( $source_prospect->first_name . ' ' . $source_prospect->last_name ) ?: ( $source_prospect->company_name ? $source_prospect->company_name : 'Prospect #' . (int) $source_prospect->id ) ); ?></div>
            <a class="acdc-button acdc-button-soft" href="<?php echo esc_url( is_admin() ? admin_url( 'admin.php?page=acdc-of-prospects&action=edit&item_id=' . (int) $source_prospect->id ) : $this->portal_page_url( array( 'tab' => 'prospects', 'action' => 'edit', 'item_id' => (int) $source_prospect->id ) ) ); ?>">Voir le prospect</a>
          </div>

        <?php elseif ( ! $need ) : ?>
          <div class="acdc-actions-end-wrap" style="justify-content:flex-start;margin-bottom:18px;">
            <a class="acdc-button acdc-button-soft" href="<?php echo esc_url( is_admin() ? admin_url( 'admin.php?page=acdc-of-prospects&action=new&redirect_to=needs&return_tab=needs' ) : $this->portal_page_url( array( 'tab' => 'prospects', 'action' => 'new', 'redirect_to' => 'needs', 'return_tab' => 'needs' ) ) ); ?>">Nouveau prospect</a>
          </div>
        <?php endif; ?>
        <input type="hidden" name="need[company_id]" value="<?php echo esc_attr( (int) $value( 'company_id', 0 ) ); ?>">
        <input type="hidden" name="need[contact_id]" value="<?php echo esc_attr( (int) $value( 'contact_id', 0 ) ); ?>">
        <?php if ( $source_prospect ) :
          /* Calcul du label entreprise */
          $prefill_display_company = '';
