          } else {
            $prefill_display_contact = trim( $source_prospect->first_name . ' ' . $source_prospect->last_name );
          }
          if ( '' === $prefill_display_contact && ! empty( $source_prospect->company_name ) ) {
            $prefill_display_contact = (string) $source_prospect->company_name;
