          if ( ! empty( $need->source_prospect_id ) ) { $varg['prospect_id'] = (int) $need->source_prospect_id; }
          $view_url_need_form = is_admin()
            ? admin_url( 'admin.php?page=acdc-of-needs&action=view&item_id=' . (int) $need->id . ( ! empty( $need->source_prospect_id ) ? '&prospect_id=' . (int) $need->source_prospect_id : '' ) )
