  }  private function render_front_simple_emails_tab() {
    $prospects = $this->get_prospects();
    $logs = $this->get_marketing_store( 'logs', array() );
    $queue = $this->get_marketing_store( 'queue', array() );

    $search = isset( $_GET['simple_email_search'] ) ? sanitize_text_field( wp_unslash( $_GET['simple_email_search'] ) ) : '';
    $status_filter = isset( $_GET['simple_email_status'] ) ? sanitize_text_field( wp_unslash( $_GET['simple_email_status'] ) ) : '';
    $assigned_filter = isset( $_GET['simple_email_assigned'] ) ? sanitize_text_field( wp_unslash( $_GET['simple_email_assigned'] ) ) : '';

    $status_counts = array();
    $assigned_counts = array();
    $relance_count = 0;
    $rdv_count = 0;
    $recent_sent_count = 0;
    $draft_count = 0;
    $rows = array();

    foreach ( $queue as $queued_item ) {
      $kind = isset( $queued_item['kind'] ) ? sanitize_key( (string) $queued_item['kind'] ) : '';
      $name = isset( $queued_item['name'] ) ? strtolower( (string) $queued_item['name'] ) : '';
      $context = isset( $queued_item['context'] ) ? strtolower( (string) $queued_item['context'] ) : '';
      if ( in_array( $kind, array( 'followup', 'email', 'simple_email' ), true ) || false !== strpos( $name, 'relance' ) || false !== strpos( $context, 'relance' ) ) {
        $draft_count++;
      }
    }

    /* ACDC 3.25.224 — « Envois récents : 0 » pendant que l'archive comptait
       cinquante destinataires. Cette carte comptait des LIGNES DE JOURNAL
       marketing dont le texte contient « relance » ou « email » — un journal
       qui n'est alimenté que par le module marketing avancé, jamais par les
       envois du parcours. Elle compte maintenant les e-mails réellement
       archivés, c'est-à-dire la seule trace qui prouve qu'un message est
       parti. */
    $cutoff_recent = current_time( 'timestamp' ) - 7 * DAY_IN_SECONDS;
    foreach ( (array) $this->get_marketing_email_archive() as $mail ) {
      $mail = (array) $mail;
      if ( empty( $mail['sent_at'] ) ) {
        continue;
      }
      $timestamp = strtotime( (string) $mail['sent_at'] );
      if ( false !== $timestamp && $timestamp >= $cutoff_recent ) {
        $recent_sent_count++;
      }
    }

    foreach ( $prospects as $prospect ) {
      $status = ! empty( $prospect->status ) ? (string) $prospect->status : 'À traiter';
      $assigned = ! empty( $prospect->assigned_to ) ? (string) $prospect->assigned_to : 'Non assigné';
      $status_counts[ $status ] = isset( $status_counts[ $status ] ) ? $status_counts[ $status ] + 1 : 1;
      $assigned_counts[ $assigned ] = isset( $assigned_counts[ $assigned ] ) ? $assigned_counts[ $assigned ] + 1 : 1;

      $status_lc = function_exists( 'mb_strtolower' ) ? mb_strtolower( $status ) : strtolower( $status );
      $needs_followup = ( false !== strpos( $status_lc, 'relance' ) || false !== strpos( $status_lc, 'a traiter' ) || false !== strpos( $status_lc, 'à traiter' ) || empty( $prospect->last_followup ) );
      if ( $needs_followup ) {
        $relance_count++;
      }

      $latest_rdv = null;
      $rdv_rows = $this->get_prospect_rdv_rows( ! empty( $prospect->id ) ? (int) $prospect->id : 0 );
      if ( ! empty( $rdv_rows ) ) {
        $latest_rdv = $rdv_rows[0];
        if ( ! empty( $latest_rdv->rdv_at ) ) {
          $rdv_count++;
        }
      }

      $display_name = $this->get_prospect_display_name( $prospect );
      $company_name = $this->get_prospect_company_display_name( $prospect );
      $email = 'Particulier' === $prospect->profile_type ? $prospect->email : ( ! empty( $prospect->signer_email ) ? $prospect->signer_email : $prospect->email );
      $phone = 'Particulier' === $prospect->profile_type ? $prospect->phone : ( ! empty( $prospect->company_phone ) ? $prospect->company_phone : ( ! empty( $prospect->signer_phone ) ? $prospect->signer_phone : $prospect->phone ) );
      $haystack = strtolower( trim( $display_name . ' ' . $company_name . ' ' . (string) $email . ' ' . (string) $phone . ' ' . (string) $status . ' ' . (string) $assigned . ' ' . (string) $prospect->desired_training ) );
      if ( '' !== $search && false === strpos( $haystack, strtolower( $search ) ) ) {
        continue;
      }
      if ( '' !== $status_filter && $status !== $status_filter ) {
        continue;
      }
      if ( '' !== $assigned_filter && $assigned !== $assigned_filter ) {
        continue;
      }

      $rows[] = array(
        'id' => ! empty( $prospect->id ) ? (int) $prospect->id : 0,
        'display_name' => $display_name,
        'company_name' => $company_name,
        'email' => $email,
        'phone' => $phone,
        'training' => ! empty( $prospect->desired_training ) ? (string) $prospect->desired_training : '—',
        'status' => $status,
        'assigned' => $assigned,
        'last_followup' => ! empty( $prospect->last_followup ) ? (string) $prospect->last_followup : 'Aucune relance',
        'next_rdv' => ( $latest_rdv && ! empty( $latest_rdv->rdv_at ) ) ? mysql2date( 'd/m/Y H\hi', $latest_rdv->rdv_at ) : '—',
      );
    }

    arsort( $status_counts );
    arsort( $assigned_counts );

    $base_followup = is_admin() ? $this->admin_prospect_followup_url() : $this->portal_page_url( array( 'tab' => 'prospect_followup' ) );
    $this->render_marketing_header( 'Relances simples', 'Pilotez ici les relances directes et manuelles, en complément du sous-module marketing avancé. Cet écran reste orienté action rapide, suivi commercial et contrôle des contacts à rappeler.', array(
      array( 'label' => 'Suivi commercial', 'url' => $base_followup, 'primary' => false ),
      array( 'label' => 'Journaux d’envoi', 'url' => $this->portal_page_url( array( 'tab' => 'marketing_logs' ) ), 'primary' => false ),
      array( 'label' => 'Contacts marketing', 'url' => $this->portal_page_url( array( 'tab' => 'marketing_contacts' ) ), 'primary' => true ),
    ) );

    $this->render_marketing_cards( array(
      array( 'label' => 'Prospects à relancer', 'value' => $relance_count, 'help' => 'Prospects sans relance récente ou encore à traiter.' ),
      array( 'label' => 'Rendez-vous suivis', 'value' => $rdv_count, 'help' => 'Prospects avec rendez-vous connu dans leur suivi.' ),
      array( 'label' => 'Envois récents', 'value' => $recent_sent_count, 'help' => 'Journaux des 7 derniers jours liés aux relances ou e-mails directs.' ),
      array( 'label' => 'Brouillons / attente', 'value' => $draft_count, 'help' => 'Éléments simples repérés dans la file d’attente du module.' ),
    ) );

    echo '<div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin-bottom:18px">';

    echo '<div class="acdc-panel">';
    echo '<h2 style="margin-top:0">Répartition par statut</h2>';
    echo '<table class="acdc-table"><thead><tr><th>Statut</th><th>Volume</th><th>Lecture métier</th></tr></thead><tbody>';
    $printed_statuses = 0;
    foreach ( array_slice( $status_counts, 0, 8, true ) as $status => $count ) {
      $help = 'Prospects suivis dans l’écran de relances.';
      $status_lc = function_exists( 'mb_strtolower' ) ? mb_strtolower( (string) $status ) : strtolower( (string) $status );
      if ( false !== strpos( $status_lc, 'relance' ) ) {
        $help = 'Priorité directe de relance.';
      } elseif ( false !== strpos( $status_lc, 'chaud' ) ) {
        $help = 'Prospect à traiter rapidement.';
      } elseif ( false !== strpos( $status_lc, 'annul' ) ) {
        $help = 'Statut à surveiller avant nouvelle action.';
      }
      echo '<tr><td>' . esc_html( $status ) . '</td><td>' . esc_html( (string) $count ) . '</td><td>' . esc_html( $help ) . '</td></tr>';
      $printed_statuses++;
    }
    if ( 0 === $printed_statuses ) {
      echo '<tr><td colspan="3">Aucun statut disponible pour le moment.</td></tr>';
    }
    echo '</tbody></table>';
    echo '</div>';

    echo '<div class="acdc-panel">';
    echo '<h2 style="margin-top:0">Lecture rapide</h2>';
    echo '<table class="acdc-table"><tbody>';
    echo '<tr><th>Utilité de l’écran</th><td>Traiter rapidement des relances directes sans passer par une campagne avancée.</td></tr>';
    echo '<tr><th>Sources utilisées</th><td>Prospects, suivi commercial, journaux marketing et file d’attente.</td></tr>';
    echo '<tr><th>Action prioritaire</th><td>Repérer les contacts sans dernière relance, avec rendez-vous ou statut à traiter.</td></tr>';
    echo '<tr><th>Complément recommandé</th><td>Utiliser le suivi commercial pour les échanges détaillés et les rendez-vous.</td></tr>';
    echo '</tbody></table>';
    echo '</div>';

    echo '</div>';

    echo '<div style="display:grid;grid-template-columns:1.4fr 1fr;gap:18px;margin-bottom:18px">';

    echo '<div class="acdc-panel">';
    echo '<h2 style="margin-top:0">Filtres</h2>';
    echo '<form method="get" class="acdc-filters" style="display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:12px;align-items:end">';
    if ( is_admin() ) {
      echo '<input type="hidden" name="page" value="acdc-of-dashboard">';
    }
    echo '<input type="hidden" name="tab" value="emails">';
    echo '<p style="margin:0"><label>Recherche</label><input type="text" name="simple_email_search" value="' . esc_attr( $search ) . '" placeholder="Nom, entreprise, e-mail, téléphone"></p>';
    echo '<p style="margin:0"><label>Statut</label><select name="simple_email_status"><option value="">Tous</option>';
    foreach ( array_slice( array_keys( $status_counts ), 0, 12 ) as $status_option ) {
      echo '<option value="' . esc_attr( $status_option ) . '" ' . selected( $status_filter, $status_option, false ) . '>' . esc_html( $status_option ) . '</option>';
    }
    echo '</select></p>';
    echo '<p style="margin:0"><label>Assigné à</label><select name="simple_email_assigned"><option value="">Tous</option>';
    foreach ( array_slice( array_keys( $assigned_counts ), 0, 12 ) as $assigned_option ) {
      echo '<option value="' . esc_attr( $assigned_option ) . '" ' . selected( $assigned_filter, $assigned_option, false ) . '>' . esc_html( $assigned_option ) . '</option>';
    }
    echo '</select></p>';
    echo '<p style="margin:0"><button type="submit" class="acdc-button acdc-button-secondary">Filtrer</button></p>';
    echo '</form>';
    echo '</div>';

    echo '<div class="acdc-panel">';
    echo '<h2 style="margin-top:0">Actions recommandées</h2>';
    echo '<table class="acdc-table"><tbody>';
    echo '<tr><th>1</th><td>Traiter d’abord les prospects sans dernière relance.</td></tr>';
    echo '<tr><th>2</th><td>Contrôler les rendez-vous programmés avant nouvel envoi.</td></tr>';
    echo '<tr><th>3</th><td>Basculer vers le module marketing pour les séquences plus complexes.</td></tr>';
    echo '<tr><th>4</th><td>Conserver une trace claire dans le suivi commercial après chaque action.</td></tr>';
    echo '</tbody></table>';
    echo '</div>';

    echo '</div>';

    echo '<div class="acdc-panel" style="margin-bottom:18px">';
    echo '<h2 style="margin-top:0">Historique détaillé</h2>';
    echo '<table class="acdc-table"><thead><tr><th>Prospect</th><th>Entreprise</th><th>E-mail</th><th>Téléphone</th><th>Formation souhaitée</th><th>Statut</th><th>Assigné à</th><th>Dernière relance</th><th>Prochain rendez-vous</th><th>Action</th></tr></thead><tbody>';
    $printed = 0;
    foreach ( array_slice( $rows, 0, 50 ) as $row ) {
      $view_url = add_query_arg( array( 'action' => 'view', 'item_id' => (int) $row['id'] ), $base_followup );
      echo '<tr>';
      echo '<td>' . esc_html( $row['display_name'] ) . '</td>';
      echo '<td>' . esc_html( $row['company_name'] ? $row['company_name'] : '—' ) . '</td>';
      echo '<td>' . esc_html( $row['email'] ? $row['email'] : '—' ) . '</td>';
      echo '<td>' . esc_html( $row['phone'] ? $row['phone'] : '—' ) . '</td>';
      echo '<td>' . esc_html( $row['training'] ) . '</td>';
      echo '<td>' . esc_html( $row['status'] ) . '</td>';
      echo '<td>' . esc_html( $row['assigned'] ) . '</td>';
      echo '<td>' . esc_html( $row['last_followup'] ) . '</td>';
      echo '<td>' . esc_html( $row['next_rdv'] ) . '</td>';
      echo '<td><a class="acdc-button acdc-button-soft" href="' . esc_url( $view_url ) . '">Ouvrir</a></td>';
      echo '</tr>';
      $printed++;
    }
    if ( 0 === $printed ) {
      echo '<tr><td colspan="10">Aucune fiche ne correspond aux filtres actuels.</td></tr>';
    }
    echo '</tbody></table>';
    echo '</div>';
  }  private function render_front_statistics_tab() {
    $prospects = $this->get_prospects();
    $total_prospects = count( $prospects );
    $assigned_counts = array();
    $source_counts = array();
    $formation_counts = array();
    $rdv_status_counts = array( 'Confirmé' => 0, 'Fait' => 0, 'Absent' => 0, 'Annulé' => 0 );
    $status_counts = array();
    $quote_count = 0;
    $contract_count = 0;
    $cancel_count = 0;
    $followup_count = 0;
    $analysis_count = 0;
    $created_dates = array();

    foreach ( $prospects as $prospect ) {
      $assigned = ! empty( $prospect->assigned_to ) ? (string) $prospect->assigned_to : '—';
      $source   = ! empty( $prospect->source ) ? (string) $prospect->source : '—';
      $training = ! empty( $prospect->desired_training ) ? (string) $prospect->desired_training : '—';
      $status   = ! empty( $prospect->status ) ? (string) $prospect->status : 'À traiter';

      $assigned_counts[ $assigned ] = isset( $assigned_counts[ $assigned ] ) ? $assigned_counts[ $assigned ] + 1 : 1;
      $source_counts[ $source ] = isset( $source_counts[ $source ] ) ? $source_counts[ $source ] + 1 : 1;
      $formation_counts[ $training ] = isset( $formation_counts[ $training ] ) ? $formation_counts[ $training ] + 1 : 1;
      $status_counts[ $status ] = isset( $status_counts[ $status ] ) ? $status_counts[ $status ] + 1 : 1;

      $status_lc = function_exists( 'mb_strtolower' ) ? mb_strtolower( $status ) : strtolower( $status );
      if ( false !== strpos( $status_lc, 'devis' ) ) { $quote_count++; }
      if ( false !== strpos( $status_lc, 'convention' ) || false !== strpos( $status_lc, 'contrat' ) ) { $contract_count++; }
      if ( false !== strpos( $status_lc, 'annul' ) ) { $cancel_count++; }
      if ( ! empty( $prospect->last_followup ) ) { $followup_count++; }
      if ( ! empty( $prospect->created_at ) ) { $created_dates[] = strtotime( $prospect->created_at ); }
      if ( ! empty( $prospect->needs_summary ) || ! empty( $prospect->need_summary ) ) { $analysis_count++; }

      $rdv_rows = $this->get_prospect_rdv_rows( ! empty( $prospect->id ) ? (int) $prospect->id : 0 );
      if ( ! empty( $rdv_rows ) ) {
        $latest = $rdv_rows[0];
        $label = ! empty( $latest->status_label ) ? (string) $latest->status_label : '';
        $label_lc = function_exists( 'mb_strtolower' ) ? mb_strtolower( $label ) : strtolower( $label );
        if ( false !== strpos( $label_lc, 'fait' ) ) {
          $rdv_status_counts['Fait']++;
        } elseif ( false !== strpos( $label_lc, 'abs' ) ) {
          $rdv_status_counts['Absent']++;
        } elseif ( false !== strpos( $label_lc, 'annul' ) ) {
          $rdv_status_counts['Annulé']++;
        } else {
          $rdv_status_counts['Confirmé']++;
        }
      }
    }

    arsort( $assigned_counts );
    arsort( $source_counts );
    arsort( $formation_counts );

    $assigned_counts = array_slice( $assigned_counts, 0, 5, true );
    $source_counts   = array_slice( $source_counts, 0, 5, true );
    $formation_counts = array_slice( $formation_counts, 0, 5, true );

    $avg_delay_days = 0;
    if ( ! empty( $created_dates ) ) {
      $sum = 0; $n = 0;
      foreach ( $created_dates as $ts ) { if ( $ts ) { $sum += max( 0, floor( ( time() - $ts ) / DAY_IN_SECONDS ) ); $n++; } }
      if ( $n ) { $avg_delay_days = (int) floor( $sum / $n ); }
    }

    $rate = function( $count ) use ( $total_prospects ) {
      if ( $total_prospects < 1 ) { return 0; }
      return round( ( $count / $total_prospects ) * 100, 1 );
    };

    $cards = array(
      array( 'title' => 'Prospects ajoutés', 'value' => (string) $total_prospects, 'sub' => 'Depuis le début', 'kind' => 'count' ),
      array( 'title' => "Délai moyen d'inscription", 'value' => (string) $avg_delay_days . ' jours', 'sub' => $total_prospects ? 'Calcul estimatif' : 'Pas de donnée', 'kind' => 'count' ),
      array( 'title' => "Taux d'inscription", 'value' => $rate( $contract_count ) . '%', 'sub' => (string) $contract_count, 'kind' => 'progress', 'pct' => $rate( $contract_count ), 'color' => '#69d2a6' ),
      array( 'title' => "Taux d'annulation", 'value' => $rate( $cancel_count ) . '%', 'sub' => (string) $cancel_count, 'kind' => 'progress', 'pct' => $rate( $cancel_count ), 'color' => '#69d2a6' ),
      array( 'title' => 'Taux de relance', 'value' => $rate( $followup_count ) . '%', 'sub' => (string) $followup_count, 'kind' => 'progress', 'pct' => $rate( $followup_count ), 'color' => '#DCE4EC' ),
      array( 'title' => "Taux d'envoi d'analyse du besoin", 'value' => $rate( $analysis_count ) . '%', 'sub' => (string) $analysis_count, 'kind' => 'progress', 'pct' => $rate( $analysis_count ), 'color' => '#DCE4EC' ),
      array( 'title' => "Taux d'envoi de devis", 'value' => $rate( $quote_count ) . '%', 'sub' => (string) $quote_count, 'kind' => 'progress', 'pct' => $rate( $quote_count ), 'color' => '#DCE4EC' ),
      array( 'title' => 'Taux de génération de convention / contrat', 'value' => $rate( $contract_count ) . '%', 'sub' => (string) $contract_count, 'kind' => 'progress', 'pct' => $rate( $contract_count ), 'color' => '#f1cc35' ),
    );

    $prospect_view_base = $this->portal_page_url( array( 'tab' => 'prospects' ) );
    ?>
    <section class="acdc-section-head"><div><h2>Statistiques commerciales</h2></div></section>
    <div class="acdc-panel acdc-mb-18"><div class="acdc-inline-wrap" style="justify-content:space-between;align-items:center;gap:16px;"><input type="search" placeholder="Rechercher" style="max-width:420px;"><div class="acdc-inline-wrap" style="gap:10px;"><button type="button" class="acdc-icon-button"><?php echo $this->render_inline_icon( 'settings', 16 ); ?></button><button type="button" class="acdc-icon-button"><?php echo $this->render_inline_icon( 'filter', 16 ); ?></button><button type="button" class="acdc-icon-button"><?php echo $this->render_inline_icon( 'chevron-down', 16 ); ?></button></div></div></div>

    <style>
      .acdc-stat-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px;margin-bottom:18px}.acdc-stat-panel{position:relative;min-height:114px}.acdc-stat-panel h3{margin:0 0 10px;font-size:16px;color:#1E4777}.acdc-stat-total{position:absolute;top:0;right:0;font-size:12px;color:#3C3C3C}.acdc-stat-list{margin:0;padding-left:18px;font-size:13px;line-height:1.6}.acdc-stat-list li{margin:0 0 3px}.acdc-ring{position:absolute;right:18px;bottom:18px;width:58px;height:58px;border-radius:50%;background:conic-gradient(#ef6b57 0 33%,#f0c038 33% 66%,#3cb371 66% 100%)}.acdc-ring:after{content:'';position:absolute;inset:8px;border-radius:50%;background:#fff}.acdc-kpis{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:18px;margin-bottom:18px}.acdc-kpi-card{padding:18px;position:relative}.acdc-kpi-card h4{margin:0 0 12px;font-size:15px;color:#1E4777}.acdc-kpi-value{font-size:22px;font-weight:700;color:#667085}.acdc-kpi-sub{font-size:13px;color:#3C3C3C}.acdc-kpi-progress{height:10px;border-radius:999px;background:#DCE4EC;overflow:hidden;margin-top:18px}.acdc-kpi-progress span{display:block;height:100%;border-radius:999px}.acdc-filter-box{padding:0;overflow:hidden;margin-bottom:14px}.acdc-filter-head{display:flex;justify-content:flex-end;background:#DCE4EC;padding:10px 12px;color:#64748b;font-size:12px;text-transform:uppercase;letter-spacing:.03em}.acdc-filter-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;padding:16px}.acdc-filter-grid label{display:block;font-size:12px;color:#1E4777;text-transform:uppercase;margin-bottom:6px}.acdc-table-prospects td small{display:block;color:#7b8798}.acdc-eye-col{text-align:right}.acdc-help-dot{position:absolute;right:10px;bottom:10px;width:20px;height:20px;border-radius:50%;background:#E9C77C;color:#0B0706;font-size:12px;display:flex;align-items:center;justify-content:center}.acdc-count-icon{display:flex;align-items:center;gap:14px}.acdc-count-icon .box{width:40px;height:40px;border-radius:10px;background:#C5A253;color:#0B0706;display:flex;align-items:center;justify-content:center}.acdc-stat-empty{color:#3C3C3C;font-size:13px}@media (max-width:1200px){.acdc-kpis,.acdc-filter-grid,.acdc-stat-grid{grid-template-columns:1fr 1fr}}@media (max-width:782px){.acdc-kpis,.acdc-filter-grid,.acdc-stat-grid{grid-template-columns:1fr}}</style>

    <div class="acdc-stat-grid">
      <div class="acdc-panel acdc-stat-panel">
        <h3>Inscriptions par apporteur d'affaires</h3><div class="acdc-stat-total">(<?php echo (int) array_sum( $assigned_counts ); ?> total)</div>
        <?php if ( ! empty( $assigned_counts ) ) : ?><ul class="acdc-stat-list"><?php foreach ( $assigned_counts as $label => $count ) : ?><li><?php echo esc_html( $label ); ?> (<?php echo (int) $count; ?> - <?php echo esc_html( $rate( $count ) ); ?>%)</li><?php endforeach; ?></ul><?php else : ?><p class="acdc-stat-empty">Aucune donnée.</p><?php endif; ?><span class="acdc-help-dot">?</span>
      </div>
      <div class="acdc-panel acdc-stat-panel">
        <h3>Formations les plus demandées</h3><div class="acdc-stat-total">(<?php echo (int) array_sum( $formation_counts ); ?> total)</div>
        <?php if ( ! empty( $formation_counts ) ) : ?><ul class="acdc-stat-list"><?php foreach ( $formation_counts as $label => $count ) : ?><li><?php echo esc_html( $label ); ?> (<?php echo (int) $count; ?> - <?php echo esc_html( $rate( $count ) ); ?>%)</li><?php endforeach; ?></ul><?php else : ?><p class="acdc-stat-empty">Aucune donnée.</p><?php endif; ?><div class="acdc-ring"></div><span class="acdc-help-dot">?</span>
