    <div class="acdc-panel">
      <div class="acdc-table-wrap"><table class="acdc-table acdc-table-prospects"><thead><tr><th>Profil</th><th>Prénom/Nom</th><th>Téléphone</th><th>E-mail</th><th>Formation souhaitée</th><th>Session</th><th>Statut</th><th>RDV</th><th>Dernière relance</th><th>Assigné à</th><th>Source</th><th>Ajouté le</th><th></th></tr></thead><tbody>
      <?php if ( ! empty( $prospects ) ) : foreach ( $prospects as $prospect ) : $view_url = add_query_arg( array( 'action' => 'view', 'item_id' => (int) $prospect->id ), $prospect_view_base ); $rdv_rows = $this->get_prospect_rdv_rows( (int) $prospect->id ); $latest = $this->get_prospect_latest_rdv( $prospect, $rdv_rows ); ?>
        <tr>
          <td><?php echo esc_html( $prospect->profile_type ?: '—' ); ?><small><?php echo esc_html( $prospect->company_name ?: '' ); ?></small></td>
          <td><?php echo esc_html( $this->get_prospect_display_name( $prospect ) ); ?></td>
          <td><?php echo esc_html( $prospect->phone ?: '—' ); ?></td>
          <td><?php echo esc_html( $this->get_prospect_primary_email( $prospect ) ?: '—' ); ?></td>
          <td><?php echo esc_html( $prospect->desired_training ?: '—' ); ?></td>
          <td><?php echo esc_html( $prospect->session_label ?: '—' ); ?></td>
          <td><?php echo esc_html( $prospect->status ?: 'À traiter' ); ?></td>
          <td><?php echo esc_html( ( $latest && ! empty( $latest->rdv_at ) ) ? mysql2date( 'd/m/Y à H\hi', $latest->rdv_at ) : '—' ); ?></td>
          <td><?php echo esc_html( $prospect->last_followup ?: 'Aucune relance' ); ?></td>
          <td><?php echo esc_html( $prospect->assigned_to ?: '—' ); ?></td>
          <td><?php echo esc_html( $prospect->source ?: '—' ); ?></td>
          <td><?php echo esc_html( $prospect->created_at ? mysql2date( 'd/m/Y H:i', $prospect->created_at ) : '—' ); ?></td>
          <td class="acdc-eye-col"><a class="acdc-icon-link" href="<?php echo esc_url( $view_url ); ?>"><?php echo $this->render_inline_icon( 'eye', 25 ); ?></a></td>
