            <?php if ( ! empty( $learners ) ) : foreach ( $learners as $entry ) :
              $name = trim( implode( ' ', array_filter( array( $entry->first_name, $entry->usage_last_name ?: $entry->last_name ) ) ) );
              $commanditaire_type = ! empty( $entry->company_name ) ? 'Entreprise' : 'Particulier';
              $commanditaire_meta = ! empty( $entry->company_name ) ? $entry->company_name : '';
              $formation = ! empty( $entry->formation_title ) ? $entry->formation_title : '—';
              $dates = '—';
              if ( ! empty( $entry->start_date ) ) {
                $dates = 'Début : ' . mysql2date( 'd/m/Y', $entry->start_date );
                if ( ! empty( $entry->end_date ) ) {
                  $dates .= '<br><small>Fin : ' . mysql2date( 'd/m/Y', $entry->end_date ) . '</small>';
                }
              }
              $schedule_count = 0;
              if ( ! empty( $entry->schedule_json ) ) {
                $schedule = json_decode( $entry->schedule_json, true );
                if ( is_array( $schedule ) ) { $schedule_count = count( $schedule ); }
              }
              if ( $schedule_count < 1 && ! empty( $entry->session_id ) ) { $schedule_count = 1; }
              $seances_label = $schedule_count ? sprintf( '%d séance%s de formation', $schedule_count, $schedule_count > 1 ? 's' : '' ) : '—';
              $progress = '—';
              if ( ! empty( $entry->formation_duration ) ) {
                $dur = preg_replace( '/^([0-9]{1,2}):([0-9]{2})$/', '$1h$2', (string) $entry->formation_duration );
                $progress = $dur . ' / ' . $dur;
              }
              $trainer = ! empty( $entry->group_trainer_name ) ? $entry->group_trainer_name : '—';
              $status = ! empty( $entry->status ) ? $entry->status : '—';
              if ( false !== strpos( strtolower( $status ), 'termin' ) ) { $status = 'Formation terminée - …'; }
              $access = '<span style="color:#ef4444;display:inline-flex;align-items:center;">' . $this->render_inline_icon( 'close', 16 ) . '</span>';
              $view_url = add_query_arg( array( 'action' => 'view', 'item_id' => (int) $entry->id ), $learner_view_base );
            ?>
