        <div><label>Signature formateur</label><select name="filter_trainer_signature"><?php foreach ( $signature_options as $value => $label ) : ?><option value="<?php echo esc_attr( $value ); ?>" <?php selected( $filters['learner_signature_status'], $value ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select></div>
        <div><label>Statut présence</label><select name="filter_presence_status"><?php foreach ( $presence_options as $value => $label ) : ?><option value="<?php echo esc_attr( $value ); ?>" <?php selected( $filters['presence_status'], $value ); ?>><?php echo esc_html( $label ); ?></option><?php endforeach; ?></select></div>
        <div><label>Formateurs</label><input type="text" name="filter_trainer" value="<?php echo esc_attr( $filters['trainer'] ); ?>" placeholder="Rechercher un formateur..."></div>
        <div><label>Formations</label><input type="text" name="filter_formation" value="<?php echo esc_attr( $filters['formation'] ); ?>" placeholder="Rechercher une formation..."></div>
