        <td><?php echo esc_html( ! empty( $item->formation_code ) ? $item->formation_code . ' | ' : '' ); ?><?php echo esc_html( ! empty( $item->formation_title ) ? $item->formation_title : '—' ); ?></td>
        <td><?php echo esc_html( ! empty( $item->trainer_display_name ) ? $item->trainer_display_name : '—' ); ?></td>
        <td><?php echo esc_html( ! empty( $item->session_type ) ? $item->session_type : 'Groupe' ); ?></td>
