              <div style="font-size:11px;color:#4b5d76;margin-top:2px"><?php echo esc_html( mysql2date( 'H\\hi', $emarg_ses->trainer_signed_at ) ); ?></div>
              <?php endif; ?>
              <?php if ( $emarg_ses->trainer_sig_url ) : ?>
              <img src="<?php echo esc_url( $emarg_ses->trainer_sig_url ); ?>" style="max-width:80px;max-height:36px;display:block;margin:4px auto 0;border:1px solid #e2e6ea;border-radius:4px" alt="Signature">
              <?php endif; ?>
            </div>
          <?php elseif ( 'none' === $t_status || ! $emarg_ses ) : ?>
            <form method="post" action="<?php echo esc_url( admin_url('admin-post.php') ); ?>" style="margin:0">
              <?php wp_nonce_field( 'acdc_emarg_send_trainer_' . (int) $item->id ); ?>
              <input type="hidden" name="action" value="acdc_emarg_send_trainer">
              <input type="hidden" name="session_id" value="<?php echo esc_attr( $item->id ); ?>">
              <button type="submit" class="acdc-button acdc-button-soft acdc-button-sm" style="font-size:12px;padding:4px 10px">✉ Envoyer</button>
