  }private function render_front_training_programs_tab() {
    $search = isset( $_GET['q'] ) ? sanitize_text_field( wp_unslash( $_GET['q'] ) ) : ( isset( $_GET['s'] ) ? sanitize_text_field( wp_unslash( $_GET['s'] ) ) : '' );
    $per_page = isset( $_GET['per_page'] ) ? absint( $_GET['per_page'] ) : 25;
    if ( ! in_array( $per_page, array( 25, 50, 100 ), true ) ) {
      $per_page = 25;
    }
    $paged = isset( $_GET['paged'] ) ? max( 1, absint( $_GET['paged'] ) ) : 1;
    $base_tab = 'training_programs';
    $base_url = is_admin() ? $this->admin_tab_url( $base_tab ) : $this->portal_page_url( array( 'tab' => $base_tab ) );

    $items = $this->get_formations( array( 'archived' => false, 'search' => $search ) );
    if ( ! empty( $items ) ) {
      usort(
        $items,
        static function( $a, $b ) {
          $a_time = ! empty( $a->updated_at ) ? strtotime( $a->updated_at ) : 0;
          $b_time = ! empty( $b->updated_at ) ? strtotime( $b->updated_at ) : 0;
          if ( $a_time === $b_time ) {
            return (int) $b->id <=> (int) $a->id;
          }
          return $b_time <=> $a_time;
        }
      );
    }

    $total = count( $items );
    $total_pages = max( 1, (int) ceil( $total / $per_page ) );
    if ( $paged > $total_pages ) {
      $paged = $total_pages;
    }
    $offset = ( $paged - 1 ) * $per_page;
    $items = array_slice( $items, $offset, $per_page );
    ?>
    <section class="acdc-section-head">
      <div>
        <h2>Programmes de formation</h2>
      </div>
    </section>
    <div class="acdc-panel acdc-mb-18">
      <form class="acdc-search-bar" method="get" action="<?php echo esc_url( $base_url ); ?>">
        <?php if ( is_admin() ) : ?>
          <input type="hidden" name="page" value="acdc-of-dashboard">
        <?php endif; ?>
        <input type="hidden" name="tab" value="training_programs">
        <div class="acdc-search-row">
          <input type="search" name="q" value="<?php echo esc_attr( $search ); ?>" placeholder="Rechercher">
          <button type="button" class="acdc-filter-toggle acdc-filter-toggle-icons-only" data-acdc-filter-toggle aria-expanded="false" title="Filtres"><?php echo $this->render_inline_icon( 'filter', 18 ); ?> <?php echo $this->render_inline_icon( 'chevron-down', 16 ); ?></button>
        </div>
        <div class="acdc-sessions-filters-panel acdc-documents-filters-panel" data-acdc-filters-panel hidden>
          <div class="acdc-documents-filter-card">
            <label><span>Par page</span>
              <select name="per_page">
                <?php foreach ( array( 25, 50, 100 ) as $size ) : ?>
                  <option value="<?php echo esc_attr( $size ); ?>" <?php selected( $per_page, $size ); ?>><?php echo esc_html( $size ); ?></option>
                <?php endforeach; ?>
              </select>
            </label>
          </div>
          <div class="acdc-inline-wrap" style="justify-content:flex-end;margin-top:14px;">
            <a class="acdc-button acdc-button-soft" href="<?php echo esc_url( $base_url ); ?>">Réinitialiser</a>
            <button type="submit" class="acdc-button acdc-button-primary">Appliquer</button>
          </div>
        </div>
      </form>
    </div>
    <div class="acdc-panel">
      <?php if ( empty( $items ) ) : ?>
        <div class="acdc-empty-state" style="padding:72px 24px;text-align:center;">
          <div class="acdc-empty-state-icon" aria-hidden="true"><?php echo $this->render_inline_icon( 'program', 54 ); ?></div>
          <p style="margin:0;color:#1E4777;">Aucune donnée ne correspond aux critères demandés.</p>
        </div>
      <?php else : ?>
        <div class="acdc-table-wrap">
          <table class="acdc-table acdc-table-training-programs" data-acdc-table-id="training-programs-list">
            <thead>
              <tr>
                <th><input type="checkbox" aria-label="Sélectionner les programmes"></th>
                <th>ID</th>
                <th>Formation</th>
                <th>Format</th>
                <th>Modifié le</th>
                <th>Durée (H)</th>
                <th><span class="screen-reader-text">Menu</span></th>
                <th><span class="screen-reader-text">Voir</span></th>
                <th><span class="screen-reader-text">Modifier</span></th>
              </tr>
            </thead>
            <tbody>
            <?php foreach ( $items as $entry ) : ?>
              <?php
                $view_url = ! empty( $entry->program_file_url ) ? $entry->program_file_url : ( is_admin() ? $this->admin_tab_url( 'formations', array( 'action' => 'view', 'item_id' => (int) $entry->id ) ) : $this->portal_page_url( array( 'tab' => 'formations', 'action' => 'view', 'item_id' => (int) $entry->id ) ) );
                $edit_url = is_admin() ? $this->admin_tab_url( 'formations', array( 'action' => 'edit', 'item_id' => (int) $entry->id ) ) : $this->portal_page_url( array( 'tab' => 'formations', 'action' => 'edit', 'item_id' => (int) $entry->id ) );
                $delete_url = wp_nonce_url( admin_url( 'admin-post.php?action=acdc_delete_formation&formation_id=' . (int) $entry->id ), 'acdc_delete_formation_' . (int) $entry->id );
                $menu_download_url = ! empty( $entry->program_file_url ) ? $entry->program_file_url : '';
                $duration = trim( (string) $entry->duration );
                if ( preg_match( '/^(\d{1,2}):(\d{2})$/', $duration, $m ) ) {
                  $duration = sprintf( '%02dh%02d', (int) $m[1], (int) $m[2] );
                } elseif ( preg_match( '/^(\d{1,2})h(\d{2})$/i', $duration, $m ) ) {
                  $duration = sprintf( '%02dh%02d', (int) $m[1], (int) $m[2] );
                }
                $updated_label = ! empty( $entry->updated_at ) ? mysql2date( 'j F Y \à H\hi', $entry->updated_at, true ) : '—';
              ?>
              <tr>
                <td><input type="checkbox" aria-label="Sélectionner ce programme"></td>
                <td><?php echo esc_html( $entry->id ); ?></td>
                <td>
                  <a href="<?php echo esc_url( $view_url ); ?>" class="acdc-program-link" <?php echo ! empty( $entry->program_file_url ) ? 'target="_blank" rel="noopener"' : ''; ?>><?php echo esc_html( $entry->title ); ?></a>
                </td>
                <td><?php echo esc_html( ! empty( $entry->modality ) ? $entry->modality : '—' ); ?></td>
                <td><?php echo esc_html( $updated_label ); ?></td>
                <td><?php echo esc_html( '' !== $duration ? $duration : '—' ); ?></td>
                <td>
                  <div class="acdc-row-menu" data-acdc-row-menu>
                    <button type="button" class="acdc-row-menu-toggle" data-acdc-row-menu-toggle aria-expanded="false" title="Actions"><?php echo $this->render_inline_icon( 'more-horizontal', 25 ); ?></button>
                    <div class="acdc-row-menu-dropdown" data-acdc-row-menu-dropdown hidden>
                      <a href="<?php echo esc_url( $view_url ); ?>" <?php echo ! empty( $entry->program_file_url ) ? 'target="_blank" rel="noopener"' : ''; ?>>Voir</a>
                      <a href="<?php echo esc_url( $edit_url ); ?>">Modifier</a>
                      <?php if ( '' !== $menu_download_url ) : ?><a href="<?php echo esc_url( $menu_download_url ); ?>" target="_blank" rel="noopener">Télécharger</a><?php endif; ?>
                      <a href="<?php echo esc_url( $delete_url ); ?>" onclick="return confirm('Supprimer ce programme ?');">Supprimer</a>
                    </div>
                  </div>
                </td>
                <td><a href="<?php echo esc_url( $view_url ); ?>" title="Voir" aria-label="Voir" class="acdc-row-view-link" <?php echo ! empty( $entry->program_file_url ) ? 'target="_blank" rel="noopener"' : ''; ?>><?php echo $this->render_inline_icon( 'view', 25 ); ?></a></td>
                <td><a href="<?php echo esc_url( $edit_url ); ?>" title="Modifier" aria-label="Modifier" class="acdc-row-edit-link"><?php echo $this->render_inline_icon( 'edit-pencil', 25 ); ?></a></td>
