    <script>
      (function(){
        var filterToggle = document.querySelector('[data-acdc-filter-toggle]');
        var filterPanel = document.querySelector('[data-acdc-filters-panel]');
        if(filterToggle && filterPanel){
          filterToggle.addEventListener('click', function(){
            var open = filterToggle.getAttribute('aria-expanded') === 'true';
            filterToggle.setAttribute('aria-expanded', open ? 'false' : 'true');
            filterPanel.hidden = open;
          });
        }
        document.querySelectorAll('[data-acdc-row-menu-toggle]').forEach(function(btn){
          btn.addEventListener('click', function(e){
            e.stopPropagation();
            var wrapper = btn.closest('[data-acdc-row-menu]');
            var dropdown = wrapper ? wrapper.querySelector('[data-acdc-row-menu-dropdown]') : null;
            var open = btn.getAttribute('aria-expanded') === 'true';
            document.querySelectorAll('[data-acdc-row-menu-dropdown]').forEach(function(menu){ menu.hidden = true; });
            document.querySelectorAll('[data-acdc-row-menu-toggle]').forEach(function(other){ other.setAttribute('aria-expanded', 'false'); });
            if(dropdown){ dropdown.hidden = open; }
            btn.setAttribute('aria-expanded', open ? 'false' : 'true');
          });
        });
        document.addEventListener('click', function(){
          document.querySelectorAll('[data-acdc-row-menu-dropdown]').forEach(function(menu){ menu.hidden = true; });
          document.querySelectorAll('[data-acdc-row-menu-toggle]').forEach(function(btn){ btn.setAttribute('aria-expanded', 'false'); });
        });
      })();
    </script>
