  }  private function render_front_attendance_sheets_tab( $action = 'list', $item_id = 0 ) {
    if ( ! in_array( $action, array( 'list', 'view' ), true ) ) {
      $action = 'list';
    }

    $base_tab = 'attendance_sheets';
    $list_url = is_admin() ? $this->admin_tab_url( $base_tab ) : $this->portal_page_url( array( 'tab' => $base_tab ) );

    if ( 'view' === $action && $item_id ) {
      $session = $this->get_session( $item_id );
      if ( ! $session || ! empty( $session->is_draft ) || 'Brouillon' === (string) $session->status || 'Annulée' === (string) $session->status ) {
        $session = null;
      }
      if ( ! $session ) {
        wp_safe_redirect( add_query_arg( array( 'notice' => rawurlencode( 'Feuille d’émargement introuvable.' ), 'notice_type' => 'error' ), $list_url ) );
        exit;
      }
      /* ACDC 3.25.205 — La carte se fabriquait sa propre requête, recopiée de
         celle de la liste mais amputée de la jointure du formateur : le champ
         n'était alimenté sur AUCUNE feuille, d'où « Formateur : — » partout.
         Chercher un cas de données aurait été inutile — il n'y avait pas de cas,
         il y avait une colonne absente.
         Plutôt que d'ajouter la jointure manquante à une copie qui divergera de
         nouveau, la carte lit désormais la MÊME ligne que la liste : même
         requête, mêmes libellés dérivés, même émargement préchargé. Un tableau
         et sa fiche de détail ne peuvent plus se contredire puisqu'ils ne lisent
         plus qu'une seule source. */
      $rows = $this->get_validated_sessions( array( 'id' => (string) (int) $item_id ) );
      if ( ! empty( $rows ) ) {
        $session = $rows[0];
      }
      ?>
      <section class="acdc-section-head">
        <div>
          <h2>Feuilles d’émargement</h2>
          <p>Consultez les feuilles d’émargement rattachées aux séances validées.</p>
        </div>
        <div class="acdc-inline-wrap">
          <a class="acdc-button acdc-button-soft" href="<?php echo esc_url( $list_url ); ?>">Retour à la liste</a>
          <button type="button" class="acdc-button acdc-button-primary" data-acdc-modal-open="acdc-create-blank-attendance-modal">Créer émargement vierge</button>
        </div>
      </section>
      <div class="acdc-grid-2cols acdc-mb-18">
        <div class="acdc-panel">
          <h3>Informations de la séance</h3>
          <div class="acdc-list-details">
            <div><strong>Apprenant / groupe :</strong> <?php echo esc_html( $this->get_session_validated_learner_or_group_label( $session ) ); ?></div>
            <div><strong>Formation :</strong> <?php echo esc_html( ! empty( $session->formation_title ) ? $session->formation_title : '—' ); ?></div>
            <div><strong>Formateur :</strong> <?php echo esc_html( $this->get_session_validated_trainer_label( $session ) ); ?></div>
            <div><strong>Date et heures :</strong> <?php echo esc_html( $this->get_session_datetime_label( $session ) ); ?></div>
            <div><strong>Durée :</strong> <?php echo esc_html( $this->get_session_duration_label( $session ) ); ?></div>
            <div><strong>Méthode d’émargement :</strong> <?php echo esc_html( ! empty( $session->attendance_method ) ? $session->attendance_method : '—' ); ?></div>
          </div>
        </div>
        <div class="acdc-panel">
          <h3>Signatures</h3>
          <div class="acdc-list-details">
            <div><strong>Date ajout / signature :</strong> <?php echo esc_html( $this->get_attendance_sheet_signature_date_label( $session ) ); ?></div>
            <div><strong>Signature formateur :</strong> <?php echo esc_html( $this->get_attendance_sheet_trainer_signature_label( $session ) ); ?></div>
            <div><strong>Signature apprenant :</strong> Voir détails</div>
            <div><strong>Progression :</strong> Voir détails</div>
            <div><strong>État dossier :</strong> Voir détails</div>
          </div>
        </div>
      </div>
      <?php $this->render_blank_attendance_modal(); ?>
      <?php
      return;
    }

    $search = isset( $_GET['q'] ) ? sanitize_text_field( wp_unslash( $_GET['q'] ) ) : ( isset( $_GET['s'] ) ? sanitize_text_field( wp_unslash( $_GET['s'] ) ) : '' );
    $items = $this->get_attendance_sheet_entries( $search );
    ?>
