        <div class="acdc-modal-body acdc-modal-body-padding">
          <form class="acdc-form" method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>" target="_blank">
            <?php wp_nonce_field( 'acdc_create_blank_attendance_sheet' ); ?>
            <input type="hidden" name="action" value="acdc_create_blank_attendance_sheet">
            <div class="acdc-contract-grid">
              <div class="acdc-contract-label">Nombre d'apprenants <span class="acdc-required">*</span></div>
              <div><input type="number" name="blank_attendance[count]" min="1" max="60" step="1" placeholder="Nombre d'apprenants" required></div>
