  /**
   * ACDC 3.25.224 — CET ÉCRAN N'AVAIT JAMAIS RIEN LU.
   *
   * « Aucune donnée ne correspond aux critères demandés » n'était pas un
   * résultat : c'était du texte écrit en dur. Aucune requête, aucun filtre,
   * un champ de recherche sans destination et un picto sans effet — pendant
   * que l'archive comptait cinquante destinataires. La recette l'a relevé
   * comme « un écran de suivi qui ne remonte rien » ; il ne remontait rien
   * parce qu'il ne cherchait rien.
   *
   * L'écran lit désormais l'archive réelle : le total par module, la part
   * d'échecs, et les derniers envois nommés. La recherche porte sur l'objet,
   * le destinataire et le module.
   */
  private function render_front_emails_summary_tab() {
    $search = isset( $_GET['q'] ) ? sanitize_text_field( wp_unslash( $_GET['q'] ) ) : '';
    $days   = isset( $_GET['days'] ) ? absint( wp_unslash( $_GET['days'] ) ) : 0;
    $base_url = is_admin() ? $this->admin_tab_url( 'emails_summary' ) : $this->portal_page_url( array( 'tab' => 'emails_summary' ) );

    $archive = $this->get_marketing_email_archive();
    $needle  = strtolower( trim( $search ) );
    $cutoff  = $days > 0 ? ( current_time( 'timestamp' ) - $days * DAY_IN_SECONDS ) : 0;

    $entries  = array();
    $by_module = array();
    $sent = 0;
    $failed = 0;
    $recipients = 0;

    foreach ( (array) $archive as $entry ) {
      $entry = (array) $entry;
      $to    = isset( $entry['to'] ) ? (array) $entry['to'] : array();

      if ( $cutoff > 0 ) {
        $ts = ! empty( $entry['sent_at'] ) ? strtotime( (string) $entry['sent_at'] ) : 0;
        if ( ! $ts || $ts < $cutoff ) {
          continue;
        }
      }

      if ( '' !== $needle ) {
        $haystack = strtolower( implode( ' ', array_filter( array(
          (string) ( $entry['subject'] ?? '' ),
          implode( ' ', array_map( 'strval', $to ) ),
          (string) ( $entry['source_module'] ?? '' ),
          (string) ( $entry['source_action'] ?? '' ),
          (string) ( $entry['category'] ?? '' ),
        ) ) ) );
        if ( false === strpos( $haystack, $needle ) ) {
          continue;
        }
      }

      $module = (string) ( $entry['source_module'] ?? 'plugin' );
      if ( ! isset( $by_module[ $module ] ) ) {
        $by_module[ $module ] = array( 'total' => 0, 'failed' => 0, 'recipients' => 0, 'last' => '' );
      }
      $by_module[ $module ]['total']++;
      $by_module[ $module ]['recipients'] += count( $to );
      if ( '' === $by_module[ $module ]['last'] ) {
        $by_module[ $module ]['last'] = (string) ( $entry['sent_at'] ?? '' );
      }

      $recipients += count( $to );
      if ( 'sent' === (string) ( $entry['status'] ?? '' ) ) {
        $sent++;
      } else {
        $failed++;
        $by_module[ $module ]['failed']++;
      }

      $entries[] = $entry;
    }

    uasort( $by_module, static function( $a, $b ) {
      return (int) $b['total'] <=> (int) $a['total'];
    } );

    $recent = array_slice( $entries, 0, 50 );
    ?>
    <section class="acdc-section-head">
      <div>
        <h2>Récapitulatif des e-mails et relances</h2>
        <p>Ce que le plugin a réellement envoyé, module par module, d'après l'archive des envois.</p>
      </div>
    </section>
    <div class="acdc-panel acdc-mb-18">
      <form class="acdc-search-bar" method="get" action="<?php echo esc_url( $base_url ); ?>">
        <?php if ( is_admin() ) : ?><input type="hidden" name="page" value="acdc-of-dashboard"><?php endif; ?>
        <input type="hidden" name="tab" value="emails_summary">
        <div class="acdc-search-row">
          <input type="search" name="q" value="<?php echo esc_attr( $search ); ?>" placeholder="Rechercher un objet, un destinataire, un module">
          <select name="days">
            <option value="0" <?php selected( $days, 0 ); ?>>Tout l'historique</option>
            <option value="7" <?php selected( $days, 7 ); ?>>7 derniers jours</option>
            <option value="30" <?php selected( $days, 30 ); ?>>30 derniers jours</option>
            <option value="90" <?php selected( $days, 90 ); ?>>90 derniers jours</option>
          </select>
          <button type="submit" class="acdc-button acdc-button-primary">Appliquer</button>
          <a class="acdc-button acdc-button-soft" href="<?php echo esc_url( $base_url ); ?>">Réinitialiser</a>
        </div>
      </form>
    </div>

    <?php if ( empty( $entries ) ) : ?>
      <div class="acdc-panel">
        <div class="acdc-empty-state" style="padding:72px 24px;text-align:center;">
          <div class="acdc-empty-state-icon" aria-hidden="true"><?php echo $this->render_inline_icon( 'emails', 54 ); ?></div>
          <p style="margin:0;color:#1E4777;">
            <?php if ( '' !== $search || $days > 0 ) : ?>
              Aucun envoi ne correspond à cette recherche. L'archive compte <?php echo (int) count( (array) $archive ); ?> envoi(s) au total.
            <?php else : ?>
              L'archive des envois est vide : aucun e-mail n'est encore parti depuis ce site.
            <?php endif; ?>
          </p>
        </div>
      </div>
    <?php else : ?>
      <div class="acdc-panel acdc-mb-18">
        <div class="acdc-inline-wrap" style="gap:28px;flex-wrap:wrap;">
          <div><div class="acdc-contract-label">Envois</div><div style="font-size:22px;font-weight:700;color:#1E4777;"><?php echo (int) count( $entries ); ?></div></div>
          <div><div class="acdc-contract-label">Destinataires</div><div style="font-size:22px;font-weight:700;color:#1E4777;"><?php echo (int) $recipients; ?></div></div>
          <div><div class="acdc-contract-label">Aboutis</div><div style="font-size:22px;font-weight:700;color:#1e7a41;"><?php echo (int) $sent; ?></div></div>
          <div><div class="acdc-contract-label">En échec</div><div style="font-size:22px;font-weight:700;color:<?php echo $failed > 0 ? '#b32d2e' : '#1E4777'; ?>;"><?php echo (int) $failed; ?></div></div>
        </div>
      </div>

      <div class="acdc-panel acdc-mb-18">
        <h3 style="margin:0 0 12px;">Par module</h3>
        <div class="acdc-table-wrap">
          <table class="acdc-table">
            <thead><tr><th>Module</th><th>Envois</th><th>Destinataires</th><th>En échec</th><th>Dernier envoi</th></tr></thead>
            <tbody>
            <?php foreach ( $by_module as $module => $stats ) : ?>
              <tr>
                <td><strong><?php echo esc_html( $module ); ?></strong></td>
                <td><?php echo (int) $stats['total']; ?></td>
                <td><?php echo (int) $stats['recipients']; ?></td>
                <td<?php echo $stats['failed'] > 0 ? ' style="color:#b32d2e;font-weight:700"' : ''; ?>><?php echo (int) $stats['failed']; ?></td>
                <td><?php echo esc_html( $stats['last'] ? mysql2date( 'd/m/Y H:i', $stats['last'] ) : '—' ); ?></td>
              </tr>
            <?php endforeach; ?>
            </tbody>
          </table>
        </div>
      </div>

      <div class="acdc-panel">
        <h3 style="margin:0 0 12px;">Derniers envois</h3>
        <div class="acdc-table-wrap">
          <table class="acdc-table">
            <thead><tr><th>Date</th><th>Destinataire(s)</th><th>Objet</th><th>Module / action</th><th>État</th></tr></thead>
            <tbody>
            <?php foreach ( $recent as $entry ) :
              $entry = (array) $entry;
              $to    = isset( $entry['to'] ) ? (array) $entry['to'] : array();
              $ok    = 'sent' === (string) ( $entry['status'] ?? '' );
              ?>
              <tr>
                <td><?php echo esc_html( ! empty( $entry['sent_at'] ) ? mysql2date( 'd/m/Y H:i', (string) $entry['sent_at'] ) : '—' ); ?></td>
                <td><?php echo esc_html( implode( ', ', array_map( 'strval', $to ) ) ); ?></td>
                <td><?php echo esc_html( (string) ( $entry['subject'] ?? '' ) ); ?></td>
                <td><?php echo esc_html( (string) ( $entry['source_module'] ?? '' ) . ' / ' . (string) ( $entry['source_action'] ?? '' ) ); ?></td>
                <td>
                  <?php if ( $ok ) : ?>
                    <span class="acdc-status-pill acdc-status-pill-success">Abouti</span>
                  <?php else : ?>
                    <span class="acdc-status-pill" style="background:#f8d7da;color:#721c24">Échec</span>
                    <?php if ( ! empty( $entry['error_message'] ) ) : ?>
                      <div style="font-size:11px;color:#721c24;margin-top:3px"><?php echo esc_html( (string) $entry['error_message'] ); ?></div>
                    <?php endif; ?>
                  <?php endif; ?>
                </td>
              </tr>
            <?php endforeach; ?>
            </tbody>
          </table>
        </div>
        <?php if ( count( $entries ) > count( $recent ) ) : ?>
          <p class="description" style="margin-top:10px;">Les <?php echo (int) count( $recent ); ?> envois les plus récents sur <?php echo (int) count( $entries ); ?>. Affinez la recherche pour voir les autres.</p>
        <?php endif; ?>
      </div>
    <?php endif; ?>
    <?php
  }  private function render_front_companies_tab( $action, $item_id ) {
    $company  = $item_id ? $this->get_company( $item_id ) : null;
    $companies = $this->get_companies();
    $new_url = is_admin() ? admin_url( 'admin.php?page=acdc-of-companies&action=new' ) : $this->portal_page_url( array( 'tab' => 'companies', 'action' => 'new' ) );
    $page_title = $this->acdc_get_action_page_title( $action, 'Entreprises', 'Créer une entreprise', 'Modifier une entreprise', 'Voir une entreprise' );
    $page_description = 'Gestion des structures clientes et commanditaires.';
    if ( 'new' === $action ) {
      $page_description = 'Création d’une structure cliente ou commanditaire.';
    } elseif ( 'edit' === $action ) {
      $page_description = 'Modification des informations d’une structure cliente ou commanditaire.';
    } elseif ( 'view' === $action ) {
      $page_description = 'Consultation détaillée d’une structure cliente ou commanditaire.';
    }
    ?>
    <section class="acdc-section-head">
      <div>
        <h2><?php echo esc_html( $page_title ); ?></h2>
        <p><?php echo esc_html( $page_description ); ?></p>
      </div>
      <div class="acdc-inline-wrap">
        <?php if ( 'view' === $action && $company && ! empty( $company->email ) ) : ?>
        <button type="button" class="acdc-button acdc-button-soft" data-acdc-modal-open="acdc-direct-email-modal-company-<?php echo (int) $company->id; ?>">&#x2709; Envoyer un e-mail</button>
        <?php endif; ?>
        <?php if ( 'new' !== $action ) : ?>
        <a class="acdc-button acdc-button-primary" href="<?php echo esc_url( $new_url ); ?>">Créer une entreprise</a>
        <?php endif; ?>
      </div>
    </section>
    <?php
    // Les écrans unitaires Entreprise doivent rester centrés sur la fiche concernée.
    // La liste complète des entreprises est strictement réservée à la page de liste.
    if ( 'view' === $action ) {
      if ( $company ) {
        $this->render_front_company_detail( $company );
      } else {
        echo '<div class="acdc-panel"><p>Entreprise introuvable.</p></div>';
      }
      return;
    }

    if ( in_array( $action, array( 'new', 'edit' ), true ) ) {
      $this->render_front_company_form( $company, $action );
      return;
    }

    /* ACDC 3.25.157 — LOT 2 : cet onglet affichait ses 191 lignes d'un bloc, sans
       champ de recherche ni pagination, alors que les sept autres répertoires en
       disposent. Même barre et même pagination que les autres onglets. */
    $c_search    = isset( $_GET['q'] ) ? sanitize_text_field( wp_unslash( $_GET['q'] ) ) : '';
    $c_per_page  = isset( $_GET['per_page'] ) ? absint( wp_unslash( $_GET['per_page'] ) ) : 25;
    if ( ! in_array( $c_per_page, array( 25, 50, 100 ), true ) ) { $c_per_page = 25; }
    $c_total     = (int) $this->get_companies( array( 'search' => $c_search, 'count' => true ) );
    $c_total_pg  = max( 1, (int) ceil( $c_total / $c_per_page ) );
    $c_paged     = isset( $_GET['paged'] ) ? max( 1, absint( wp_unslash( $_GET['paged'] ) ) ) : 1;
    if ( $c_paged > $c_total_pg ) { $c_paged = $c_total_pg; }
    $c_offset    = ( $c_paged - 1 ) * $c_per_page;
    $c_base_url  = is_admin() ? $this->admin_tab_url( 'companies' ) : $this->portal_page_url( array( 'tab' => 'companies' ) );
    $companies   = $this->get_companies( array( 'search' => $c_search, 'limit' => $c_per_page, 'offset' => $c_offset ) );
    ?>
    <div class="acdc-panel acdc-mb-18">
      <form class="acdc-search-bar" method="get" action="<?php echo esc_url( $c_base_url ); ?>">
        <?php if ( is_admin() ) : ?><input type="hidden" name="page" value="acdc-of-dashboard"><?php endif; ?>
        <input type="hidden" name="tab" value="companies">
        <div class="acdc-search-row">
          <input type="search" name="q" value="<?php echo esc_attr( $c_search ); ?>" placeholder="Rechercher un nom, un SIRET, une ville, un e-mail">
          <select name="per_page" aria-label="Résultats par page">
            <?php foreach ( array( 25, 50, 100 ) as $c_size ) : ?>
              <option value="<?php echo esc_attr( $c_size ); ?>" <?php selected( $c_per_page, $c_size ); ?>><?php echo esc_html( $c_size ); ?> / page</option>
            <?php endforeach; ?>
          </select>
          <button type="submit" class="acdc-button acdc-button-primary">Rechercher</button>
          <?php if ( '' !== $c_search ) : ?>
            <a class="acdc-button acdc-button-soft" href="<?php echo esc_url( $c_base_url ); ?>">Réinitialiser</a>
          <?php endif; ?>
        </div>
      </form>
    </div>
    <div class="acdc-panel acdc-companies-list-panel">
      <div class="acdc-table-wrap">
        <table class="acdc-table acdc-companies-table" data-acdc-table-id="companies-list">
          <thead>
            <tr>
              <th>SIRET / N° d’identification</th>
              <th>Entreprise</th>
              <th>Prospect</th>
              <th>Adresse</th>
              <th>Code postal</th>
              <th>Ville</th>
              <th>Adresse e-mail signataire / entreprise</th>
              <th>Prénom du signataire</th>
              <th>Nom du signataire</th>
              <th>Qualité du signataire</th>
              <th>Signature documents</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
          <?php if ( ! empty( $companies ) ) : ?>
            <?php foreach ( $companies as $entry ) : ?>
              <?php
                $contacts = $this->get_related_contacts( $entry->id );
                $signatory = ! empty( $contacts ) ? reset( $contacts ) : null;
                $signatory_first_name = isset( $entry->signer_first_name ) && '' !== trim( (string) $entry->signer_first_name ) ? (string) $entry->signer_first_name : ( $signatory && isset( $signatory->first_name ) ? (string) $signatory->first_name : '' );
                $signatory_last_name  = isset( $entry->signer_last_name ) && '' !== trim( (string) $entry->signer_last_name ) ? (string) $entry->signer_last_name : ( $signatory && isset( $signatory->last_name ) ? (string) $signatory->last_name : '' );
                $signatory_quality    = isset( $entry->signer_quality ) && '' !== trim( (string) $entry->signer_quality ) ? (string) $entry->signer_quality : ( $signatory && isset( $signatory->job_title ) ? (string) $signatory->job_title : '' );
                $signatory_email      = ! empty( $entry->email ) ? (string) $entry->email : ( $signatory && ! empty( $signatory->email ) ? (string) $signatory->email : '' );
                $signature_label      = isset( $entry->signature_documents ) && '' !== trim( (string) $entry->signature_documents ) ? (string) $entry->signature_documents : $this->acdc_build_company_signature_documents_label( $signatory_first_name, $signatory_last_name, $signatory_quality );
                if ( '' === trim( (string) $signature_label ) ) { $signature_label = ! empty( $entry->name ) ? (string) $entry->name : '—'; }
                $is_prospect = isset( $entry->is_prospect ) ? (bool) $entry->is_prospect : ( isset( $entry->prospect ) ? (bool) $entry->prospect : false );
                $base = is_admin() ? admin_url( 'admin.php?page=acdc-of-companies' ) : $this->portal_page_url( array( 'tab' => 'companies' ) );
                $need_url = is_admin() ? admin_url( 'admin.php?page=acdc-of-need-analyses&action=new&company_id=' . (int) $entry->id ) : $this->portal_page_url( array( 'tab' => 'need_analyses', 'action' => 'new', 'company_id' => (int) $entry->id ) );
                /* ACDC 3.25.157 — LOT 2 : deux slugs inexistants dans ce menu.
                   « Devis » passait action=new, paramètre que l'onglet Devis n'écoute
                   pas (il attend scope=action&quote_action=create) : on retombait sur la
                   liste. « Convention/Contrat » pointait tab=contracts, slug qui n'existe
                   pas — l'onglet réel est registration_contract — d'où le retour au
                   tableau de bord. */
                $quote_url = is_admin()
                  ? admin_url( 'admin.php?page=acdc-of-dashboard&tab=quotes&scope=action&quote_action=create&company_id=' . (int) $entry->id )
                  : $this->portal_page_url( array( 'tab' => 'quotes', 'scope' => 'action', 'quote_action' => 'create', 'company_id' => (int) $entry->id ) );
                $contract_url = is_admin()
                  ? admin_url( 'admin.php?page=acdc-of-dashboard&tab=registration_contract&action=new&company_id=' . (int) $entry->id )
                  : $this->portal_page_url( array( 'tab' => 'registration_contract', 'action' => 'new', 'company_id' => (int) $entry->id ) );
                $register_url = is_admin() ? admin_url( 'admin.php?page=acdc-of-register-training&action=new&company_id=' . (int) $entry->id ) : $this->portal_page_url( array( 'tab' => 'register_training', 'action' => 'new', 'company_id' => (int) $entry->id ) );
              ?>
              <tr>
                <td class="acdc-nowrap"><?php echo esc_html( $entry->siret ?: '—' ); ?></td>
                <td><strong><?php echo esc_html( $entry->name ?: '—' ); ?></strong></td>
                <td class="acdc-company-prospect-cell"><span class="acdc-prospect-indicator <?php echo $is_prospect ? 'is-yes' : 'is-no'; ?>"><?php echo $is_prospect ? '✓' : '×'; ?></span></td>
                <td><?php echo esc_html( $entry->address ?: '—' ); ?></td>
                <td class="acdc-nowrap"><?php echo esc_html( $entry->postal_code ?: '—' ); ?></td>
                <td><?php echo esc_html( $entry->city ?: '—' ); ?></td>
                <td class="acdc-nowrap"><?php echo esc_html( $signatory_email ?: '—' ); ?></td>
