  private function acdc_build_company_signature_documents_label( $first_name, $last_name, $quality ) {
    $name = trim( preg_replace( '/\s+/', ' ', trim( (string) $first_name ) . ' ' . trim( (string) $last_name ) ) );
    $quality = trim( preg_replace( '/\s+/', ' ', (string) $quality ) );
    if ( '' !== $name && '' !== $quality ) {
      return $name . ' - ' . $quality;
    }
    if ( '' !== $name ) {
      return $name;
    }
    return $quality;
  }

