    $state_input = ( ! empty( $state['input'] ) && is_array( $state['input'] ) ) ? $state['input'] : array();
    $required_fields = ( ! empty( $state['required_fields'] ) && is_array( $state['required_fields'] ) ) ? array_values( array_unique( array_map( 'sanitize_key', $state['required_fields'] ) ) ) : array();

    $value = function( $key, $default = '' ) use ( $company, $state_input ) {
      if ( array_key_exists( $key, $state_input ) ) {
        return $state_input[ $key ];
      }
      return $company && isset( $company->$key ) ? $company->$key : $default;
    };

    $field_class = function( $key ) use ( $required_fields ) {
      return in_array( sanitize_key( $key ), $required_fields, true ) ? ' class="acdc-field-invalid"' : '';
    };

