    <script>
    (function(){
      var panel = document.currentScript ? document.currentScript.previousElementSibling : null;
      while (panel && (!panel.classList || !panel.classList.contains('acdc-form-panel'))) { panel = panel.previousElementSibling; }
      panel = panel || document.querySelector('.acdc-form-panel');
      if (!panel) { return; }
      var first = panel.querySelector('input[name="signer_first_name"]');
      var last = panel.querySelector('input[name="signer_last_name"]');
      var quality = panel.querySelector('input[name="signer_quality"]');
      var signature = panel.querySelector('[data-acdc-company-signature-documents]');
      if (!first || !last || !quality || !signature) { return; }
      function clean(value){ return (value || '').replace(/\s+/g, ' ').trim(); }
      function build(){
        var name = [clean(first.value), clean(last.value)].filter(Boolean).join(' ');
        var q = clean(quality.value);
        return q ? (name ? name + ' - ' + q : q) : name;
      }
      function refresh(){ signature.value = build(); }
      first.addEventListener('input', refresh);
      last.addEventListener('input', refresh);
      quality.addEventListener('input', refresh);
      refresh();
    })();
    </script>
