  }  private function render_front_company_detail( $company ) {
    if ( ! $company ) {
      echo '<div class="acdc-panel"><p>Entreprise introuvable.</p></div>';
      return;
    }

    $company_for_view = clone $company;
    $contact_summaries = array();
    foreach ( (array) $this->get_related_contacts( $company->id ) as $contact ) {
      $contact_name = trim( ( isset( $contact->first_name ) ? (string) $contact->first_name : '' ) . ' ' . ( isset( $contact->last_name ) ? (string) $contact->last_name : '' ) );
      $contact_parts = array();
      if ( '' !== $contact_name ) {
        $contact_parts[] = $contact_name;
      }
      if ( ! empty( $contact->job_title ) ) {
        $contact_parts[] = (string) $contact->job_title;
      }
      if ( ! empty( $contact->email ) ) {
        $contact_parts[] = (string) $contact->email;
      }
      if ( ! empty( $contact->phone ) ) {
        $contact_parts[] = (string) $contact->phone;
      }
      if ( ! empty( $contact_parts ) ) {
        $contact_summaries[] = implode( ' — ', $contact_parts );
      }
    }
    if ( ! empty( $contact_summaries ) ) {
      $company_for_view->contacts_annexes = trim( ( isset( $company_for_view->contacts_annexes ) ? (string) $company_for_view->contacts_annexes : "" ) . "\n" . implode( "\n", $contact_summaries ) );
    }

    $this->render_front_company_form( $company_for_view, 'edit' );
    ?>
    <script>
    (function(){
      var scripts = document.getElementsByTagName('script');
      var current = scripts[scripts.length - 1];
      var panel = current ? current.previousElementSibling : null;
      while (panel && (!panel.classList || !panel.classList.contains('acdc-form-panel'))) { panel = panel.previousElementSibling; }
      panel = panel || document.querySelector('.acdc-form-panel');
      if (!panel) { return; }
      panel.classList.add('acdc-company-view-readonly');
      var form = panel.querySelector('form.acdc-form');
      if (form) {
        form.setAttribute('aria-label', 'Voir une entreprise');
        form.addEventListener('submit', function(event){ event.preventDefault(); return false; });
      }
      panel.querySelectorAll('input:not([type="hidden"]), textarea').forEach(function(field){
        field.readOnly = true;
        field.setAttribute('aria-readonly', 'true');
      });
      panel.querySelectorAll('select').forEach(function(field){
        field.disabled = true;
        field.setAttribute('aria-disabled', 'true');
      });
      panel.querySelectorAll('button[type="submit"]').forEach(function(button){
        button.remove();
      });
      panel.querySelectorAll('.acdc-company-form-actions-inline a').forEach(function(link){
        var button = document.createElement('button');
        button.type = 'button';
        button.className = link.className;
        button.disabled = true;
        button.textContent = link.textContent || 'Ajouter un contact';
        link.parentNode.replaceChild(button, link);
      });
      var style = document.createElement('style');
      style.textContent = '.acdc-company-view-readonly input[readonly],.acdc-company-view-readonly textarea[readonly],.acdc-company-view-readonly select:disabled{background:#f8fafc;color:#0C2D52;opacity:1;cursor:default}.acdc-company-view-readonly button[disabled]{opacity:.55;cursor:not-allowed}.acdc-company-view-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:16px}';
      document.head.appendChild(style);
      if (form) {
        var actions = document.createElement('p');
        actions.className = 'acdc-company-view-actions';
        <?php $email_btn_company = ! empty( $company->email ) ? '<button type="button" class="acdc-button acdc-button-soft" data-acdc-modal-open="acdc-direct-email-modal-company-' . (int) $company->id . '">&#x2709; Envoyer un e-mail</button>' : ''; ?>
        actions.innerHTML = '<a class="acdc-button acdc-button-primary" href="<?php echo esc_js( $this->portal_page_url( array( 'tab' => 'companies', 'action' => 'edit', 'item_id' => $company->id ) ) ); ?>">Modifier</a><?php echo $email_btn_company; ?><a class="acdc-button acdc-button-secondary" href="<?php echo esc_js( $this->portal_page_url( array( 'tab' => 'companies' ) ) ); ?>">Retour</a>';
        form.appendChild(actions);
      }
    })();
    </script>
    <?php if ( ! empty( $company->email ) ) :
      $to_name_co = ! empty( $company->name ) ? $company->name : trim( $company->signer_first_name . ' ' . $company->signer_last_name );
      $this->render_direct_email_modal( $company, 'company', $company->email, $to_name_co, 'companies' );
