  $total = count( $rows );
  $total_pages = max( 1, (int) ceil( max( 1, $total ) / $per_page ) );
  if ( $paged > $total_pages ) { $paged = $total_pages; }
  $offset = ( $paged - 1 ) * $per_page;
  $page_rows = array_slice( $rows, $offset, $per_page );
