                    foreach ( $prog_decoded as $_pb ) {
                      if ( isset( $_pb['jour'], $_pb['moment'] ) ) {
                        $prog_blocs_indexed[ (int) $_pb['jour'] ][ $_pb['moment'] ] = $_pb;
                      }
                    }
                  }
                }
                $get_prog = function( $j, $moment, $champ ) use ( $prog_blocs_indexed ) {
                  return isset( $prog_blocs_indexed[ $j ][ $moment ][ $champ ] ) ? (string) $prog_blocs_indexed[ $j ][ $moment ][ $champ ] : '';
                };
                for ( $_j = 1; $_j <= 5; $_j++ ) :
                  $_has_jour = isset( $prog_blocs_indexed[ $_j ] ) && ! empty( $prog_blocs_indexed[ $_j ] );
