                .acdc-prog-jour-summary::-webkit-details-marker{display:none}
                .acdc-prog-jour-summary:hover{background:#f0f4f9}
                .acdc-prog-jour-chevron{width:18px;height:18px;border-right:2px solid var(--acdc-primary,#8b5b23);border-bottom:2px solid var(--acdc-primary,#8b5b23);transform:rotate(45deg);transition:transform .2s;margin-right:4px;flex-shrink:0}
                .acdc-prog-jour[open] .acdc-prog-jour-chevron{transform:rotate(-135deg)}
                .acdc-prog-jour-body{padding:18px 20px;border-top:1px solid var(--acdc-border-soft,#dce4ec)}
                .acdc-prog-demijournee{margin-bottom:22px;padding-bottom:22px;border-bottom:1px dashed var(--acdc-border-soft,#dce4ec)}
