          <?php if ( ! $is_view ) : ?>
          <script>
          (function(){
            var nav = document.querySelector('#acdc-formation-tabs .acdc-form-tab-nav');
            if (!nav) { return; }
            var btns = nav.querySelectorAll('.acdc-form-tab-btn');
            function activateTab(key) {
              btns.forEach(function(b){
                var isActive = b.getAttribute('data-acdc-tab') === key;
                b.classList.toggle('is-active', isActive);
                b.setAttribute('aria-selected', isActive ? 'true' : 'false');
              });
              document.querySelectorAll('#acdc-formation-tabs .acdc-form-tab-panel').forEach(function(p){
                p.hidden = (p.id !== 'acdc-tab-panel-' + key);
              });
              try { sessionStorage.setItem('acdc_formation_tab', key); } catch(e) {}
            }
            btns.forEach(function(btn){
              btn.addEventListener('click', function(){
                activateTab(btn.getAttribute('data-acdc-tab'));
              });
            });
            // Restaurer l'onglet actif depuis sessionStorage
            try {
              var saved = sessionStorage.getItem('acdc_formation_tab');
              if (saved && document.getElementById('acdc-tab-panel-' + saved)) {
                activateTab(saved);
              }
            } catch(e) {}
          })();
          </script>
          <?php else : ?>
          <script>
          (function(){
            var nav = document.querySelector('#acdc-formation-tabs .acdc-form-tab-nav');
