      <script>
      (function(){
        if (window.acdcFormationPrereqReady) { return; }
        window.acdcFormationPrereqReady = true;

        var activeTrigger = null;
        var floatingPopover = null;

        function ensureFloatingPopover(){
          if (floatingPopover) { return floatingPopover; }
          floatingPopover = document.createElement('div');
          floatingPopover.className = 'acdc-formation-prereq-popover acdc-formation-prereq-popover-floating';
          floatingPopover.setAttribute('role', 'dialog');
          floatingPopover.setAttribute('hidden', 'hidden');
          document.body.appendChild(floatingPopover);
          return floatingPopover;
        }

        function closeFloatingPopover(){
          var pop = ensureFloatingPopover();
          pop.classList.remove('is-open');
          pop.setAttribute('hidden', 'hidden');
          pop.innerHTML = '';
          if (activeTrigger) {
            activeTrigger.setAttribute('aria-expanded', 'false');
            activeTrigger = null;
          }
        }

        function positionFloatingPopover(trigger, pop){
          if (!trigger || !pop) { return; }
          var rect = trigger.getBoundingClientRect();
          pop.style.left = '0px';
          pop.style.top = '0px';
          pop.removeAttribute('hidden');
          pop.classList.add('is-open');
          var gap = 10;
          var left = rect.left;
          var top = rect.bottom + gap;
          var maxLeft = window.innerWidth - pop.offsetWidth - 16;
          if (left > maxLeft) { left = Math.max(16, maxLeft); }
          if (top + pop.offsetHeight > window.innerHeight - 16) {
            top = Math.max(16, rect.top - pop.offsetHeight - gap);
          }
          pop.style.left = left + 'px';
          pop.style.top = top + 'px';
        }

        document.addEventListener('click', function(event){
          var trigger = event.target.closest('[data-acdc-prereq-toggle]');
          var pop = ensureFloatingPopover();

          if (trigger) {
            event.preventDefault();
            var wrap = trigger.parentNode;
            var source = wrap ? wrap.querySelector('.acdc-formation-prereq-content') : null;
            if (!source) { return; }
            if (activeTrigger === trigger && pop.classList.contains('is-open')) {
              closeFloatingPopover();
              return;
            }
            if (activeTrigger) {
              activeTrigger.setAttribute('aria-expanded', 'false');
            }
            activeTrigger = trigger;
            activeTrigger.setAttribute('aria-expanded', 'true');
            pop.textContent = source.textContent || source.innerText || '';
            positionFloatingPopover(trigger, pop);
            return;
          }

          if (pop.classList.contains('is-open') && !pop.contains(event.target)) {
            closeFloatingPopover();
          }
        });

        window.addEventListener('resize', function(){
          if (!activeTrigger || !floatingPopover || !floatingPopover.classList.contains('is-open')) { return; }
          positionFloatingPopover(activeTrigger, floatingPopover);
        });

        window.addEventListener('scroll', function(){
          if (!activeTrigger || !floatingPopover || !floatingPopover.classList.contains('is-open')) { return; }
          positionFloatingPopover(activeTrigger, floatingPopover);
        }, true);

        document.addEventListener('keydown', function(event){
          if (event.key !== 'Escape') { return; }
          closeFloatingPopover();
        });
      }());
      </script>
    <?php endif; ?>
    <?php
