    </style>
    <script>
      (function(){
        var form = document.querySelector('.acdc-pre-meeting-form');
        if(!form){return;}
        var searchInput = document.getElementById('acdc-pre-meeting-learner-search');
        var learnerSelect = document.getElementById('acdc-pre-meeting-learner');
        var formationSelect = document.getElementById('acdc-pre-meeting-formation');
        var rdvInput = document.getElementById('acdc-pre-meeting-rdv');
        var help = document.getElementById('acdc-pre-meeting-session-dates-help');
        var datesMap = <?php echo wp_json_encode( $session_dates_map ); ?> || {};
        if(searchInput && learnerSelect){
          var originalOptions = Array.prototype.slice.call(learnerSelect.options).map(function(opt){
            return {value: opt.value, label: opt.textContent, selected: opt.selected};
          });
          function rebuildLearners(){
            var current = learnerSelect.value;
            var query = (searchInput.value || '').toLowerCase().trim();
            learnerSelect.innerHTML = '';
            originalOptions.forEach(function(opt){
              if(!opt.value){
                var emptyOpt = document.createElement('option');
                emptyOpt.value = '';
                emptyOpt.textContent = opt.label;
                learnerSelect.appendChild(emptyOpt);
                return;
              }
              if(query && opt.label.toLowerCase().indexOf(query) === -1){ return; }
              var node = document.createElement('option');
              node.value = opt.value;
              node.textContent = opt.label;
              if(opt.value === current){ node.selected = true; }
              learnerSelect.appendChild(node);
            });
          }
          searchInput.addEventListener('input', rebuildLearners);
        }
        function updateDatesHelp(){
          if(!formationSelect || !help){ return true; }
          var formationId = formationSelect.value || '';
          var dates = datesMap[formationId] || [];
          if(!dates.length){
            help.textContent = 'Aucune date de séance enregistrée pour cette formation. Le rendez-vous ne pourra être validé que lorsqu’une séance existera.';
            help.classList.add('acdc-field-help-error');
            return false;
          }
          var pretty = dates.map(function(d){ var parts = d.split('-'); return parts[2] + '/' + parts[1] + '/' + parts[0]; });
          help.textContent = 'Dates de séances disponibles : ' + pretty.join(' • ');
          help.classList.remove('acdc-field-help-error');
          return true;
        }
        function isRdvAllowed(){
          if(!formationSelect || !rdvInput){ return true; }
          var formationId = formationSelect.value || '';
          var dates = datesMap[formationId] || [];
          var value = rdvInput.value || '';
          if(!formationId || !value){ return true; }
          var datePart = value.split('T')[0];
          return dates.indexOf(datePart) !== -1;
        }
        if(formationSelect){ formationSelect.addEventListener('change', updateDatesHelp); updateDatesHelp(); }
        if(rdvInput){ rdvInput.addEventListener('change', function(){
          if(isRdvAllowed()){ updateDatesHelp(); return; }
          help.textContent = 'La date choisie ne correspond à aucune séance de formation de cette formation.';
          help.classList.add('acdc-field-help-error');
        }); }
        form.addEventListener('submit', function(event){
          if(learnerSelect && !learnerSelect.value){
            event.preventDefault();
            window.alert('Veuillez sélectionner un apprenant dans le répertoire des apprenants.');
            return;
          }
          if(!updateDatesHelp()){
            event.preventDefault();
            window.alert('Aucune séance de formation n’est enregistrée pour la formation sélectionnée.');
            return;
          }
          if(!isRdvAllowed()){
            event.preventDefault();
            window.alert('Le rendez-vous post-formation doit être positionné sur une date de séance de formation.');
          }
        });
      })();
    </script>
    <?php
  }private function render_brand_block() {
  $o = $this->get_branding_options();
  $logo = ! empty( $o['logo_url'] ) ? esc_url( $o['logo_url'] ) : '';
  echo '<div class="acdc-nav-brand">';
  if ( $logo ) {
    echo '<div class="acdc-nav-brand-logo"><img src="' . $logo . '" alt="Logo"></div>';
  }
  echo '<div class="acdc-nav-brand-title">' . esc_html( $o['display_name'] ) . '</div>';
  echo '<div class="acdc-nav-brand-subtitle">' . esc_html( $o['sidebar_subtitle'] ) . '</div>';
  echo '</div>';
}public function enqueue_admin_assets( $hook ) {
  if ( false === strpos( (string) $hook, 'acdc-of-' ) ) {
    return;
  }
  wp_enqueue_style( 'dashicons' );
  wp_enqueue_style( 'acdc-of-frontend', ACDC_OF_SAAS_URL . 'assets/css/frontend.css', array( 'dashicons' ), ACDC_OF_SAAS_VERSION );
  wp_add_inline_style( 'acdc-of-frontend', $this->get_dynamic_css() );
  wp_enqueue_style( 'acdc-of-ui-system', ACDC_OF_SAAS_URL . 'assets/css/acdc-ui-system.css', array( 'acdc-of-frontend' ), ACDC_OF_SAAS_VERSION );
  wp_enqueue_style( 'acdc-of-components', ACDC_OF_SAAS_URL . 'assets/css/acdc-components.css', array( 'acdc-of-ui-system' ), ACDC_OF_SAAS_VERSION );
  wp_enqueue_script( 'acdc-of-ui-kernel', ACDC_OF_SAAS_URL . 'assets/js/acdc-ui-kernel.js', array(), ACDC_OF_SAAS_VERSION, true );
  if ( method_exists( $this, 'localize_ui_kernel_settings' ) ) { $this->localize_ui_kernel_settings(); }
  wp_enqueue_script( 'acdc-of-admin', ACDC_OF_SAAS_URL . 'assets/js/admin.js', array( 'acdc-of-ui-kernel' ), ACDC_OF_SAAS_VERSION, true );
  /* ACDC 3.20.60 — passage de la config back office au moteur AcdcActionHub. */
  wp_localize_script( 'acdc-of-admin', 'ACDC_ACTION_HUB_CONFIG', $this->get_action_hub_config() );
  wp_enqueue_script( 'acdc-of-ui-system', ACDC_OF_SAAS_URL . 'assets/js/acdc-ui-system.js', array( 'acdc-of-ui-kernel', 'acdc-of-admin' ), ACDC_OF_SAAS_VERSION, true );
  wp_enqueue_style( 'acdc-of-admin-backoffice', ACDC_OF_SAAS_URL . 'assets/css/acdc-admin-backoffice.css', array( 'acdc-of-components' ), ACDC_OF_SAAS_VERSION );
  wp_enqueue_script( 'acdc-of-admin-backoffice', ACDC_OF_SAAS_URL . 'assets/js/acdc-admin-backoffice.js', array( 'acdc-of-ui-system' ), ACDC_OF_SAAS_VERSION, true );
}


