private function acdc_format_need_company_display( $entry ) {
  $company_name = isset( $entry->company_name ) ? trim( (string) $entry->company_name ) : '';
  if ( '' !== $company_name ) {
    return $company_name;
  }
  $prospect_company = isset( $entry->prospect_company ) ? trim( (string) $entry->prospect_company ) : '';
  if ( '' !== $prospect_company ) {
    return $prospect_company;
  }
  $company = '';
  if ( isset( $entry->company ) ) {
    $company = trim( (string) $entry->company );
  }
  if ( '' !== $company ) {
    return $company;
  }
  return '—';
}

private function acdc_format_need_contact_display( $entry ) {
  $contact_name = isset( $entry->contact_name ) ? trim( (string) $entry->contact_name ) : '';
  if ( '' !== $contact_name ) {
    return $contact_name;
  }
  $parts = array();
  foreach ( array( 'prospect_first_name', 'prospect_last_name' ) as $key ) {
    if ( isset( $entry->$key ) && '' !== trim( (string) $entry->$key ) ) {
      $parts[] = trim( (string) $entry->$key );
    }
  }
  if ( ! empty( $parts ) ) {
    return implode( ' ', $parts );
  }
  if ( isset( $entry->prospect_name ) && '' !== trim( (string) $entry->prospect_name ) ) {
    return trim( (string) $entry->prospect_name );
  }
  return '—';
}

private function acdc_format_need_interlocutor_display( $entry ) {
  $value = isset( $entry->acdc_interlocutor ) ? trim( (string) $entry->acdc_interlocutor ) : '';
  if ( '' !== $value ) {
    return $value;
  }
  if ( isset( $entry->assigned_to ) && '' !== trim( (string) $entry->assigned_to ) ) {
    return trim( (string) $entry->assigned_to );
  }
  return '—';
}

