private function render_admin_portal_wrapper( $tab ) {
  if ( isset( $_GET['tab'] ) ) {
    $tab = sanitize_key( wp_unslash( $_GET['tab'] ) );
  }
  $action = isset( $_GET['action'] ) ? sanitize_key( wp_unslash( $_GET['action'] ) ) : 'list';
  if ( ! $this->current_user_can_access_plugin_screen( $tab, $action, 'admin' ) ) {
    wp_die( esc_html( 'Accès refusé à cet écran.' ) );
  }
  echo '<div class="wrap acdc-admin-wrap">' . $this->render_admin_portal_content( $tab ) . '</div>';
}private function acdc_get_action_page_title( $action, $list_title, $create_title, $edit_title, $view_title ) {
  if ( 'new' === $action ) {
    return $create_title;
  }
  if ( 'edit' === $action ) {
    return $edit_title;
  }
  if ( 'view' === $action ) {
    return $view_title;
  }
  return $list_title;
}
