public function render_admin_configuration_page() {
  if ( ! current_user_can( 'manage_options' ) ) {
    return;
  }

  $branding = method_exists( $this, 'get_branding_options' ) ? $this->get_branding_options() : array();
  $message  = isset( $_GET['message'] ) ? sanitize_key( wp_unslash( $_GET['message'] ) ) : '';

  $text = function( $key, $default = '' ) use ( $branding ) {
    return isset( $branding[ $key ] ) ? (string) $branding[ $key ] : $default;
  };

  $color = function( $key, $default = '#ffffff' ) use ( $branding ) {
    $value = isset( $branding[ $key ] ) ? (string) $branding[ $key ] : $default;
    return preg_match( '/^#[0-9a-fA-F]{6}$/', $value ) ? $value : $default;
  };

  $pdf_fonts = array(
    'Helvetica'   => 'Helvetica',
    'Times-Roman' => 'Times',
    'Courier'     => 'Courier',
  );
  $keep_data = get_option( 'acdc_of_keep_data_on_uninstall', 'yes' );
  $db_version = get_option( 'acdc_of_db_version', '3.0.0' );
  $purge_prod = get_option( 'acdc_of_purge_allowed_in_production', 'no' );
  $backup_retention = absint( get_option( 'acdc_of_backup_retention_count', 30 ) );
  $last_safety_backup_at = get_option( 'acdc_of_last_safety_backup_at', '' );
  $last_safety_backup_file = get_option( 'acdc_of_last_safety_backup_file', '' );
