    <script>
      document.addEventListener('DOMContentLoaded', function(){
        var tabs = document.querySelectorAll('.acdc-configuration-page [data-tab-target]');
        var panes = document.querySelectorAll('.acdc-configuration-page [data-tab-pane]');
        if (!tabs.length || !panes.length) { return; }
        tabs.forEach(function(tab){
          tab.addEventListener('click', function(){
            var target = tab.getAttribute('data-tab-target');
            tabs.forEach(function(item){ item.classList.remove('is-active'); });
            panes.forEach(function(pane){ pane.classList.remove('is-active'); });
            tab.classList.add('is-active');
            var targetPane = document.querySelector('.acdc-configuration-page [data-tab-pane="' + target + '"]');
            if (targetPane) { targetPane.classList.add('is-active'); }
          });
        });
      });
    </script>


