          <?php endforeach; ?>
          <input type="hidden" name="acdc_of_keep_data_on_uninstall" value="">
          <p><label><input type="checkbox" name="acdc_of_keep_data_on_uninstall" value="yes" <?php checked( $keep_data, 'yes' ); ?>> <strong>Conserver les données lors de la désinstallation</strong></label></p>
          <input type="hidden" name="acdc_of_purge_allowed_in_production" value="">
