          <p><label><strong>Nombre de sauvegardes versionnées à conserver</strong><br><input type="number" min="5" max="100" class="small-text" name="acdc_of_backup_retention_count" value="<?php echo esc_attr( (string) $backup_retention ); ?>"></label></p>
          <p><strong>Version du schéma de données :</strong> <?php echo esc_html( $db_version ); ?></p>
          <p><strong>Dernière sauvegarde de sécurité :</strong> <?php echo $last_safety_backup_at ? esc_html( $last_safety_backup_at ) : 'Aucune'; ?></p>
          <?php if ( $last_safety_backup_file ) : ?><p><strong>Fichier manifeste sécurité :</strong> <?php echo esc_html( $last_safety_backup_file ); ?></p><?php endif; ?>
          <p><button type="submit" class="button">Enregistrer les options de maintenance</button></p>
        </form>
      </section>
  </div>
  <?php
}

private function render_simple_pdf( $pages, $filename = 'document.pdf', $disposition = 'inline' ) {
  while ( ob_get_level() ) {
    ob_end_clean();
  }
  nocache_headers();
  header( 'Content-Type: application/pdf' );
  $disposition = in_array( $disposition, array( 'inline', 'attachment' ), true ) ? $disposition : 'inline';
  header( 'Content-Disposition: ' . $disposition . '; filename="' . sanitize_file_name( $filename ) . '"' );
  echo $this->_build_simple_pdf_string( $pages );
  exit;
}

/**
 * ACDC 3.21.63 — Construit le contenu binaire d'un PDF simple et le retourne comme string.
 * Utilisé par render_simple_pdf() (sortie directe) et par _auto_send_completion_certificate_for_session() (sauvegarde fichier).
 *
 * @param array $pages Tableau de pages (même format que render_simple_pdf)
 * @return string Contenu binaire du PDF
 */
private function _build_simple_pdf_string( $pages ) {

  $objects = array();
  $page_ids = array();
  $font_regular_id = 0;
  $font_bold_id = 0;

  $add_object = static function ( $content ) use ( &$objects ) {
    $objects[] = $content;
    return count( $objects );
  };

  $font_regular_id = $add_object( "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>" );
  $font_bold_id  = $add_object( "<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>" );

  $image_map = array();
  foreach ( $pages as $page_lines ) {
    foreach ( $page_lines as $line ) {
      if ( isset( $line['type'] ) && 'image' === $line['type'] && ! empty( $line['image_key'] ) && ! isset( $image_map[ $line['image_key'] ] ) && ! empty( $line['image_data'] ) ) {
        $image_object = "<< /Type /XObject /Subtype /Image /Width " . (int) $line['image_width'] . " /Height " . (int) $line['image_height'] . " /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length " . strlen( $line['image_data'] ) . " >>
stream
" . $line['image_data'] . "
endstream";
        $image_map[ $line['image_key'] ] = array(
          'name' => 'Im' . ( count( $image_map ) + 1 ),
          'object_id' => $add_object( $image_object ),
        );
      }
    }
  }

  $content_ids = array();
  $page_resource_xobjects = array();
  $page_sizes = array();
  foreach ( $pages as $page_lines ) {
    $stream = "";
    $used_images = array();
    $page_width = 595;
    $page_height = 842;
    foreach ( $page_lines as $line ) {
      if ( isset( $line['type'] ) && 'page_meta' === $line['type'] ) {
        if ( ! empty( $line['width'] ) ) {
          $page_width = (float) $line['width'];
        }
        if ( ! empty( $line['height'] ) ) {
          $page_height = (float) $line['height'];
        }
        continue;
      }
      if ( isset( $line['type'] ) && 'image' === $line['type'] ) {
        if ( empty( $line['image_key'] ) || empty( $image_map[ $line['image_key'] ] ) ) {
          continue;
        }
        $img_name = $image_map[ $line['image_key'] ]['name'];
        $used_images[ $img_name ] = $image_map[ $line['image_key'] ]['object_id'];
        $stream .= sprintf( "q %.2f 0 0 %.2f %.2f %.2f cm /%s Do Q
", (float) $line['display_width'], (float) $line['display_height'], (float) $line['x'], (float) $line['y'], $img_name );
        continue;
      }
      if ( isset( $line['type'] ) && 'rect' === $line['type'] ) {
        $fill = isset( $line['fill_color'] ) ? $this->pdf_hex_to_rgb( $line['fill_color'] ) : null;
        $stroke = isset( $line['stroke_color'] ) ? $this->pdf_hex_to_rgb( $line['stroke_color'] ) : null;
        $stream .= "q
";
        if ( $fill ) {
          $stream .= sprintf( "%.4f %.4f %.4f rg
", $fill[0], $fill[1], $fill[2] );
        }
        if ( $stroke ) {
          $stream .= sprintf( "%.4f %.4f %.4f RG
", $stroke[0], $stroke[1], $stroke[2] );
        }
        $stream .= sprintf( "%.2f w
", isset( $line['line_width'] ) ? (float) $line['line_width'] : 1 );
        $stream .= sprintf( "%.2f %.2f %.2f %.2f re
", (float) $line['x'], (float) $line['y'], (float) $line['width'], (float) $line['height'] );
        if ( $fill && $stroke ) {
          $stream .= "B
";
        } elseif ( $fill ) {
          $stream .= "f
";
        } else {
          $stream .= "S
";
        }
        $stream .= "Q
";
        continue;
      }
      $font_id = ( 'Helvetica-Bold' === $line['font'] ) ? $font_bold_id : $font_regular_id;
      $color = isset( $line['color'] ) ? $this->pdf_hex_to_rgb( $line['color'] ) : array( 0, 0, 0 );
      $raw_text = isset( $line['text'] ) ? (string) $line['text'] : '';
      $tw = 0.0;
      if ( 0 === strpos( $raw_text, '[[TW:' ) ) {
        $tw_end = strpos( $raw_text, ']]'  );
        if ( false !== $tw_end ) {
          $tw = (float) substr( $raw_text, 5, $tw_end - 5 );
          $raw_text = substr( $raw_text, $tw_end + 2 );
        }
      }
      $tc = ( isset( $line['char_spacing'] ) && abs( (float) $line['char_spacing'] ) > 0.001 ) ? (float) $line['char_spacing'] : 0.0;
      $stream .= "BT
";
      $stream .= sprintf( "%.4f %.4f %.4f rg
", $color[0], $color[1], $color[2] );
      $stream .= sprintf( "/F%d %s Tf
", $font_id, (float) $line['size'] );
      if ( $tc > 0.001 ) { $stream .= sprintf( "%.4f Tc
", $tc ); }
      if ( $tw > 0.001 ) { $stream .= sprintf( "%.4f Tw
", $tw ); }
      $stream .= sprintf( "1 0 0 1 %.2f %.2f Tm
", (float) $line['x'], (float) $line['y'] );
      $stream .= "(" . $this->pdf_encode_text( $raw_text ) . ") Tj
";
      if ( $tc > 0.001 ) { $stream .= "0 Tc
"; }
      if ( $tw > 0.001 ) { $stream .= "0 Tw
"; }
      $stream .= "ET
";
    }
    $content_ids[] = $add_object( "<< /Length " . strlen( $stream ) . " >>
stream
" . $stream . "
endstream" );
    $page_resource_xobjects[] = $used_images;
    $page_sizes[] = array( 'width' => $page_width, 'height' => $page_height );
  }

  $pages_root_id = 0;
  foreach ( $content_ids as $index => $content_id ) {
    $xobject_resource = '';
    if ( ! empty( $page_resource_xobjects[ $index ] ) ) {
      $chunks = array();
      foreach ( $page_resource_xobjects[ $index ] as $img_name => $img_object_id ) {
        $chunks[] = '/' . $img_name . ' ' . $img_object_id . ' 0 R';
      }
      $xobject_resource = ' /XObject << ' . implode( ' ', $chunks ) . ' >>';
    }
    $page_width = ! empty( $page_sizes[ $index ]['width'] ) ? (float) $page_sizes[ $index ]['width'] : 595;
    $page_height = ! empty( $page_sizes[ $index ]['height'] ) ? (float) $page_sizes[ $index ]['height'] : 842;
    $page_ids[] = $add_object( "<< /Type /Page /Parent PAGES_ROOT /MediaBox [0 0 {$page_width} {$page_height}] /Resources << /Font << /F{$font_regular_id} {$font_regular_id} 0 R /F{$font_bold_id} {$font_bold_id} 0 R >>{$xobject_resource} >> /Contents {$content_id} 0 R >>" );
  }

  $kids = array();
  foreach ( $page_ids as $pid ) {
    $kids[] = $pid . ' 0 R';
  }
  $pages_root_id = $add_object( "<< /Type /Pages /Count " . count( $page_ids ) . " /Kids [ " . implode( ' ', $kids ) . " ] >>" );

  foreach ( $page_ids as $index => $pid ) {
    $objects[ $pid - 1 ] = str_replace( 'PAGES_ROOT', $pages_root_id . ' 0 R', $objects[ $pid - 1 ] );
  }

  $catalog_id = $add_object( "<< /Type /Catalog /Pages {$pages_root_id} 0 R >>" );

  $pdf = "%PDF-1.4
%âãÏÓ
";
  $offsets = array( 0 );
  foreach ( $objects as $i => $object ) {
    $offsets[] = strlen( $pdf );
    $pdf .= ( $i + 1 ) . " 0 obj
" . $object . "
endobj
";
  }
  $xref_pos = strlen( $pdf );
  $pdf .= "xref
0 " . ( count( $objects ) + 1 ) . "
";
  $pdf .= "0000000000 65535 f 
";
  for ( $i = 1; $i <= count( $objects ); $i++ ) {
    $pdf .= sprintf( "%010d 00000 n 
", $offsets[ $i ] );
  }
  $pdf .= "trailer
<< /Size " . ( count( $objects ) + 1 ) . " /Root {$catalog_id} 0 R >>
startxref
{$xref_pos}
%%EOF";
  return $pdf;
}

/**
 * ACDC 3.21.90 — Wrapper public pour _build_simple_pdf_string
 * Utilisé par ACDC_Cerfa_BPF_Generator (externe, pas de visibilité private)
 */
public function _build_simple_pdf_string_public( $pages ) {
  return $this->_build_simple_pdf_string( $pages );
}

private function acdc_render_backoffice_tabs( $current ) {
  $tabs = array(
    'acdc-of-dashboard' => "Centre d'administration",
    'acdc-of-ui-system' => 'UI / Design système',
    'acdc-of-ui-variables' => 'Variables CSS',
    'acdc-of-improvement-pilotage' => 'Qualité & conformité',
    'acdc-of-configuration' => 'Réglages organisme',
    'acdc-of-maintenance' => 'Données & maintenance',
  );
  echo '<nav class="acdc-admin-tabs">';
  foreach ( $tabs as $slug => $label ) {
    $class = $slug === $current ? 'acdc-admin-tab is-active' : 'acdc-admin-tab';
    echo '<a class="' . esc_attr( $class ) . '" href="' . esc_url( admin_url( 'admin.php?page=' . $slug ) ) . '">' . esc_html( $label ) . '</a>';
  }
  echo '</nav>';
}

