  $cards = array(
    array( 'title' => 'UI / Design système', 'text' => 'Couleurs, typographie, boutons, tableaux, icônes, modales et aperçu immédiat.', 'link' => admin_url( 'admin.php?page=acdc-of-ui-system' ), 'cta' => 'Ouvrir le designer' ),
