public function render_admin_ui_variables_page() {
  $this->acdc_render_backoffice_tabs( 'acdc-of-ui-variables' );
  $o = $this->get_branding_options();
  $defaults = $this->get_branding_defaults();
  $vars = array();
  foreach ( $defaults as $key => $default ) {
    $value = isset( $o[ $key ] ) ? $o[ $key ] : $default;
    $vars[ $key ] = $value;
  }
  echo '<div class="wrap acdc-admin-shell"><h1>Variables CSS</h1>';
  if ( isset( $_GET['updated'] ) ) { echo '<div class="notice notice-success"><p>Variables enregistrées.</p></div>'; }
  echo '<div class="acdc-admin-two-cols"><div class="acdc-admin-panel"><h2>Variables actives</h2><table class="widefat striped"><thead><tr><th>Clé</th><th>Valeur</th></tr></thead><tbody>';
  foreach ( $vars as $k => $v ) {
    echo '<tr><td><code>' . esc_html( $k ) . '</code></td><td><code>' . esc_html( is_scalar( $v ) ? (string) $v : wp_json_encode( $v ) ) . '</code></td></tr>';
  }
  echo '</tbody></table></div>';
  echo '<div class="acdc-admin-panel"><h2>CSS personnalisé</h2><form method="post" action="' . esc_url( admin_url( 'admin-post.php' ) ) . '">';
  wp_nonce_field( 'acdc_save_branding' );
  echo '<input type="hidden" name="action" value="acdc_save_branding"><input type="hidden" name="redirect_page" value="acdc-of-ui-variables">';
  foreach ( $o as $key => $value ) { if ( 'custom_css' === $key ) { continue; } echo '<input type="hidden" name="branding[' . esc_attr( $key ) . ']" value="' . esc_attr( $value ) . '">'; }
  echo '<textarea name="branding[custom_css]" rows="18" style="width:100%;font-family:monospace;">' . esc_textarea( $o['custom_css'] ) . '</textarea>';
  echo '<p class="description">Ajoutez ici des surcharges ciblées. Elles sont injectées après les variables globales.</p><p><button type="submit" class="button button-primary">Enregistrer le CSS personnalisé</button></p></form>';
  echo '<hr><p><a class="button" href="' . esc_url( wp_nonce_url( admin_url( 'admin-post.php?action=acdc_export_branding' ), 'acdc_export_branding' ) ) . '">Exporter</a></p></div></div></div>';
}

public function render_admin_maintenance_page() {
  $this->acdc_render_backoffice_tabs( 'acdc-of-maintenance' );
  $keep_data = get_option( 'acdc_of_keep_data_on_uninstall', 'yes' );
  $backup_retention = absint( get_option( 'acdc_of_backup_retention_count', 30 ) );
  $last_manual_backup_at = get_option( 'acdc_of_last_manual_backup_at', '' );
  $last_safety_backup_at = get_option( 'acdc_of_last_safety_backup_at', '' );
  echo '<div class="wrap acdc-admin-shell"><h1>Données & maintenance</h1>';
  if ( isset( $_GET['updated'] ) ) { echo '<div class="notice notice-success"><p>Réglages de maintenance enregistrés.</p></div>'; }
  echo '<div class="acdc-admin-two-cols">';
  echo '<div class="acdc-admin-panel"><h2>Sauvegardes</h2><p><strong>Dernière sauvegarde manuelle :</strong> ' . ( $last_manual_backup_at ? esc_html( $last_manual_backup_at ) : 'Aucune' ) . '</p><p><strong>Dernière sauvegarde de sécurité :</strong> ' . ( $last_safety_backup_at ? esc_html( $last_safety_backup_at ) : 'Aucune' ) . '</p><form method="post" action="' . esc_url( admin_url( 'admin-post.php' ) ) . '">';
  wp_nonce_field( 'acdc_create_manual_backup' );
  echo '<input type="hidden" name="action" value="acdc_create_manual_backup"><p><button type="submit" class="button button-primary">Créer une sauvegarde</button></p></form><p><a class="button" href="' . esc_url( admin_url( 'admin.php?page=acdc-of-configuration' ) ) . '">Ouvrir les outils complets</a></p></div>';
  echo '<div class="acdc-admin-panel"><h2>Protection des données</h2><form method="post" action="' . esc_url( admin_url( 'admin-post.php' ) ) . '">';
  wp_nonce_field( 'acdc_save_branding' );
  echo '<input type="hidden" name="action" value="acdc_save_branding"><input type="hidden" name="redirect_page" value="acdc-of-maintenance">';
  $o = $this->get_branding_options();
  foreach ( $o as $key => $value ) { echo '<input type="hidden" name="branding[' . esc_attr( $key ) . ']" value="' . esc_attr( $value ) . '">'; }
  echo '<p><label><input type="checkbox" name="acdc_of_keep_data_on_uninstall" value="yes" ' . checked( $keep_data, 'yes', false ) . '> Conserver les données à la désinstallation</label></p><p><label>Nombre de sauvegardes à conserver<br><input type="number" class="small-text" min="5" max="100" name="acdc_of_backup_retention_count" value="' . esc_attr( (string) $backup_retention ) . '"></label></p><p><button type="submit" class="button button-primary">Enregistrer</button></p></form></div>';
  echo '</div></div>';
}

/* ─────────────────────────────────────────────────────────────────────────────
 * MOTEUR PDF HTML — mPDF
 * render_html_pdf()                    : génère et envoie le PDF via mPDF
 * acdc_build_need_pdf_html()           : construit le HTML du recueil des besoins
 * acdc_build_nad_apprenant_pdf_html()  : construit le HTML de l'analyse du besoin apprenant
 * ───────────────────────────────────────────────────────────────────────────── */

private function acdc_build_nad_apprenant_pdf_html( $nad ) {
  global $wpdb;
  $profile    = $this->get_company_profile_options();
  $pdf_assets = $this->get_acdc_internal_pdf_asset_urls();

  $logo_url = '';
  if ( ! empty( $pdf_assets['logo_url'] ) )      { $logo_url = (string) $pdf_assets['logo_url']; }
  elseif ( ! empty( $profile['pdf_logo_url'] ) ) { $logo_url = (string) $profile['pdf_logo_url']; }
  elseif ( ! empty( $profile['logo_url'] ) )     { $logo_url = (string) $profile['logo_url']; }
  else { $logo_url = 'https://acdcformation.com/wp-content/uploads/2026/03/Logo-ACDC.png'; }

  // Apprenant — requête directe pour éviter la dépendance cross-trait
  $learner_name  = '';
  $learner_email = '';
  if ( ! empty( $nad->apprenant_id ) ) {
    $learner = $wpdb->get_row( $wpdb->prepare(
      "SELECT first_name, last_name, email FROM {$wpdb->prefix}acdc_of_learners WHERE id = %d",
      (int) $nad->apprenant_id
    ) );
    if ( $learner ) {
      $learner_name  = trim( (string) $learner->first_name . ' ' . (string) $learner->last_name );
      $learner_email = ! empty( $learner->email ) ? (string) $learner->email : '';
    }
  }
  if ( '' === $learner_name && ! empty( $nad->repondant_prenom ) ) {
    $learner_name = trim( sanitize_text_field( (string) $nad->repondant_prenom ) . ' ' . sanitize_text_field( (string) $nad->repondant_nom ) );
  }

  // Formation liée
  $formation_title = '';
  if ( ! empty( $nad->formation_id ) ) {
    $f = $this->get_formation( (int) $nad->formation_id );
    if ( $f ) { $formation_title = (string) $f->title; }
  }

  // Statut et thématique
  $statuts_map = array( 'brouillon' => 'Brouillon', 'nouveau' => 'Nouveau', 'a_traiter' => 'À traiter', 'traite' => 'Traité', 'soumise' => 'Soumise', 'archive' => 'Archivé', 'expire' => 'Expiré' );
  $nad_statut = isset( $statuts_map[ (string) $nad->statut ] ) ? $statuts_map[ (string) $nad->statut ] : (string) $nad->statut;
  $them_map   = $this->get_thematiques_map();
  $thematique = ! empty( $nad->thematique ) ? ( isset( $them_map[ $nad->thematique ] ) ? $them_map[ $nad->thematique ] : (string) $nad->thematique ) : '';

  // Réponses JSON
  $reponses = array();
  if ( ! empty( $nad->reponses ) ) {
    $r = json_decode( $nad->reponses, true );
    if ( is_array( $r ) ) { $reponses = $r; }
  }

  // Questions — logique identique au bloc vert interface
  $nad_bloc_ids = array();
  if ( ! empty( $nad->blocs_ids ) ) {
    $decoded_bids = json_decode( $nad->blocs_ids, true );
    if ( is_array( $decoded_bids ) ) { $nad_bloc_ids = array_map( 'intval', $decoded_bids ); }
  }
  if ( ! empty( $nad_bloc_ids ) ) {
    $ph_bids = implode( ',', array_fill( 0, count( $nad_bloc_ids ), '%d' ) );
    $rows = $wpdb->get_results( $wpdb->prepare(
      "SELECT code, libelle FROM {$this->need_question_table}
       WHERE bloc_id IN ($ph_bids)
       ORDER BY FIELD(bloc_id, $ph_bids), ordre ASC, id ASC",
      ...$nad_bloc_ids, ...$nad_bloc_ids
    ) );
  } else {
    $rows = $wpdb->get_results(
      "SELECT code, libelle FROM {$this->need_question_table} ORDER BY bloc_id ASC, ordre ASC, id ASC"
    );
  }

  $questions_data = array();
  foreach ( $rows as $row ) {
    $code = (string) $row->code;
    $raw  = isset( $reponses[ $code ] ) ? $reponses[ $code ] : null;
    if ( is_array( $raw ) ) {
      $val = implode( ', ', array_filter( array_map( 'strval', $raw ) ) );
    } elseif ( null === $raw ) {
      $val = '';
    } else {
      $val = (string) $raw;
    }
    $questions_data[] = array(
      'label'      => ! empty( $row->libelle ) ? (string) $row->libelle : ucfirst( str_replace( '_', ' ', $code ) ),
      'bloc_label' => 'Questions',
      'val'        => $val,
    );
  }

  $data = array(
    'logo_url'        => $logo_url,
    'org_name'        => ! empty( $profile['company_name'] ) ? $profile['company_name'] : 'ACDC - Formation',
    'org_sub'         => ! empty( $profile['tagline'] )      ? $profile['tagline']      : 'Azur Compétences Développement & Conseil',
    'org_addr'        => array_filter( array(
      ! empty( $profile['address'] )  ? (string) $profile['address']  : 'ACDC-Formation',
      ! empty( $profile['address2'] ) ? (string) $profile['address2'] : '',
      trim( ( ! empty( $profile['zip'] ) ? $profile['zip'] : '83310' ) . ' ' . ( ! empty( $profile['city'] ) ? $profile['city'] : 'Cogolin' ) ) . ' - France',
    ) ),
    'org_siret'       => ! empty( $profile['siret'] )   ? $profile['siret']   : '',
    'org_nda'         => ! empty( $profile['nda'] )     ? $profile['nda']     : '',
    'org_email'       => ! empty( $profile['email'] )   ? $profile['email']   : '',
    'org_tel'         => ! empty( $profile['phone'] )   ? $profile['phone']   : '',
    'org_web'         => ! empty( $profile['website'] ) ? $profile['website'] : '',
    'learner_name'    => $learner_name,
    'learner_email'   => $learner_email,
    'formation_title' => $formation_title,
    'nad_id'          => (int) $nad->id,
    'nad_statut'      => $nad_statut,
    'nad_date'        => mysql2date( 'd/m/Y', $nad->updated_at ),
    'thematique'      => $thematique,
    'questions'       => $questions_data,
  );

  $template = dirname( dirname( plugin_dir_path( __FILE__ ) ) ) . '/includes/pdf-templates/analyse-besoin-apprenant.php';
  if ( ! file_exists( $template ) ) {
    return '<html><body>Template PDF introuvable.</body></html>';
  }
  ob_start();
  include $template;
  return ob_get_clean();
}

private function render_html_pdf( $html, $filename = 'document.pdf', $disposition = 'inline' ) {
  $autoload = dirname( dirname( dirname( dirname( plugin_dir_path( __FILE__ ) ) ) ) ) . '/acdc-libs/vendor/autoload.php';
  if ( ! file_exists( $autoload ) ) {
    wp_die( esc_html( 'Librairie PDF (mPDF) introuvable. Vérifiez l\'installation.' ) );
  }
  require_once $autoload;
  if ( ! class_exists( '\Mpdf\Mpdf' ) ) {
    wp_die( esc_html( "Librairie PDF (mPDF) indisponible : le dossier acdc-libs semble incomplet. Vérifiez l'installation." ) );
  }

  while ( ob_get_level() ) { ob_end_clean(); }

  $mpdf = new \Mpdf\Mpdf( array(
    'format'        => 'A4',
    'margin_top'    => 14,
    'margin_bottom' => 14,
    'margin_left'   => 14,
    'margin_right'  => 14,
    'tempDir'       => sys_get_temp_dir(),
  ) );

  $mpdf->SetTitle( sanitize_file_name( $filename ) );
  $mpdf->WriteHTML( $html );

  $disposition = in_array( $disposition, array( 'inline', 'attachment' ), true ) ? $disposition : 'inline';
  $mpdf->Output( sanitize_file_name( $filename ), 'I' === strtoupper( $disposition[0] ) ? 'I' : 'D' );
  exit;
}

private function acdc_build_need_pdf_html( $need, $source_prospect_id = 0, $client_only = false ) {
  /* ── Données liées ── */
  $company  = ! empty( $need->company_id ) ? $this->get_company( (int) $need->company_id )   : null;
  $contact  = ! empty( $need->contact_id ) ? $this->get_contact( (int) $need->contact_id )   : null;
  $prospect = $source_prospect_id          ? $this->get_prospect( (int) $source_prospect_id ) : null;

  /* ── Profil organisme ── */
  $profile    = $this->get_company_profile_options();
  $pdf_assets = $this->get_acdc_internal_pdf_asset_urls();

  /* Logo PDF : préférer pdf_logo_url (petit logo) ou logo_url en fallback */
  $logo_url = '';
  if ( ! empty( $pdf_assets['logo_url'] ) ) {
    $logo_url = (string) $pdf_assets['logo_url'];
  } elseif ( ! empty( $profile['pdf_logo_url'] ) ) {
    $logo_url = (string) $profile['pdf_logo_url'];
  } elseif ( ! empty( $profile['logo_url'] ) ) {
    $logo_url = (string) $profile['logo_url'];
  } else {
    $logo_url = 'https://acdcformation.com/wp-content/uploads/2026/03/Logo-ACDC.png';
  }

  $signature_url = ! empty( $pdf_assets['cachet_signature_url'] )
    ? (string) $pdf_assets['cachet_signature_url']
    : 'https://acdcformation.com/wp-content/uploads/2026/04/Cachet-et-signature.png';

  /* ── Noms ── */
  $company_name = $company && ! empty( $company->name )
    ? (string) $company->name
    : ( $prospect ? $this->get_prospect_company_display_name( $prospect ) : '' );

  if ( $contact ) {
    $contact_name = trim( $contact->first_name . ' ' . $contact->last_name );
  } elseif ( $prospect ) {
    /* ACDC 3.25.239 — « Contact » nomme une personne. L'entreprise est déjà
       sur la ligne du dessus : l'y répéter n'apprend rien et efface le nom
       que le lecteur cherche. */
    $contact_name = trim( $this->get_prospect_contact_person_name( $prospect ) );
  } else {
    $contact_name = '';
  }

  /* ── Formatage dates ── */
  $fmt_date = function( $value ) {
    if ( empty( $value ) ) { return ''; }
    $ts = strtotime( (string) $value );
    return $ts ? date_i18n( 'd/m/Y', $ts ) : '';
  };

  /* ── Données passées au template ── */
  $data = array(
    'logo_url'          => $logo_url,
    'signature_url'     => $signature_url,
    'org_name'          => ! empty( $profile['company_name'] ) ? $profile['company_name'] : 'ACDC - Formation',
    'org_sub'           => ! empty( $profile['tagline'] )      ? $profile['tagline']      : 'Azur Compétences Développement & Conseil',
    'org_addr'          => array_filter( array(
      ! empty( $profile['address'] )  ? (string) $profile['address']  : 'ACDC-Formation',
      ! empty( $profile['address2'] ) ? (string) $profile['address2'] : '',
      trim( ( ! empty( $profile['zip'] ) ? $profile['zip'] : '83310' ) . ' ' . ( ! empty( $profile['city'] ) ? $profile['city'] : 'Cogolin' ) ) . ' - France',
    ) ),
    'org_siret'         => ! empty( $profile['siret'] )   ? $profile['siret']   : '405109901 00042',
    'org_nda'           => ! empty( $profile['nda'] )     ? $profile['nda']     : '93 83 08347 83',
    'org_email'         => ! empty( $profile['email'] )   ? $profile['email']   : 'contact@acdc-formation.com',
    'org_tel'           => ! empty( $profile['phone'] )   ? $profile['phone']   : '06 78 26 91 10',
    'org_web'           => ! empty( $profile['website'] ) ? $profile['website'] : 'acdc-formation.com',
    'company_name'      => $company_name,
    'contact_name'      => $contact_name,
    'theme'             => ! empty( $need->theme )              ? (string) $need->theme              : '',
    'collection_channel'=> ! empty( $need->collection_channel ) ? (string) $need->collection_channel : '',
    'collection_date'   => $fmt_date( $need->collection_date ),
    'acdc_interlocutor' => ! empty( $need->acdc_interlocutor )  ? (string) $need->acdc_interlocutor  : '',
    'status'            => ! empty( $need->status )             ? (string) $need->status             : '',
    'target_audience'   => ! empty( $need->target_audience )    ? (string) $need->target_audience    : '',
    'audience_level'    => ! empty( $need->audience_level )     ? (string) $need->audience_level     : '',
    'learners_count'    => ! empty( $need->learners_count )     ? (string) $need->learners_count     : '',
    'desired_format'    => ! empty( $need->desired_format )     ? (string) $need->desired_format     : '',
    'planned_funding'   => ! empty( $need->planned_funding )    ? (string) $need->planned_funding    : '',
    'urgency'           => ! empty( $need->urgency )            ? (string) $need->urgency            : '',
    'desired_deadline'  => $fmt_date( $need->desired_deadline ),
    'expressed_need'    => ! empty( $need->expressed_need )     ? (string) $need->expressed_need     : '',
    'reframed_need'     => ! empty( $need->reframed_need )      ? (string) $need->reframed_need      : '',
    'context_text'      => ! empty( $need->context_text )       ? (string) $need->context_text       : '',
    'current_situation' => ! empty( $need->current_situation )  ? (string) $need->current_situation  : '',
    'expected_objectives' => ! empty( $need->expected_objectives ) ? (string) $need->expected_objectives : '',
    'constraints_text'  => ! empty( $need->constraints_text )   ? (string) $need->constraints_text   : '',
    'budget'            => ! empty( $need->budget )             ? (string) $need->budget             : '',
    'next_action'       => ! empty( $need->next_action )        ? (string) $need->next_action        : '',
    'next_action_date'  => $fmt_date( $need->next_action_date ),
    'internal_summary'  => ! empty( $need->internal_summary )   ? (string) $need->internal_summary   : '',
    'client_only'       => (bool) $client_only,
  );

  $template = dirname( dirname( plugin_dir_path( __FILE__ ) ) ) . '/includes/pdf-templates/recueil-besoins.php';
  if ( ! file_exists( $template ) ) {
    return '<html><body>Template PDF introuvable.</body></html>';
  }

  ob_start();
  include $template;
  return ob_get_clean();
}

