          </p>
        </form>
      </div>
      <script>
      (function(){
        var btn  = document.getElementById('acdc-teval-add-btn');
        var wrap = document.getElementById('acdc-teval-form-wrap');
        var cncl = document.getElementById('acdc-teval-cancel-btn');
        if(btn)  btn.addEventListener('click',  function(){ wrap.style.display=''; btn.style.display='none'; });
        if(cncl) cncl.addEventListener('click', function(){ wrap.style.display='none'; if(btn) btn.style.display=''; });
      })();
      </script>
      <?php endif; ?>
    </div>
    <?php
  }

  /* ====================================================================
   *  ACDC 3.24.40 - Helper : modale d envoi e-mail direct depuis une fiche
   * ====================================================================*/
  protected function render_direct_email_modal( $entity, $entity_type, $to_email, $to_name, $tab ) {
    if ( ! $entity || ! $to_email || ! is_email( $to_email ) ) { return; }
    $entity_id = (int) $entity->id;
    $modal_id  = 'acdc-direct-email-modal-' . $entity_type . '-' . $entity_id;
    $sig_list  = $this->get_marketing_store( 'signatures', array() );
    $default_sig = null;
    foreach ( $sig_list as $s ) { if ( ! empty( $s['is_default'] ) ) { $default_sig = $s; break; } }
    if ( ! $default_sig && ! empty( $sig_list ) ) { $default_sig = $sig_list[0]; }
    // Données JSON de la signature encodées base64 — JS appellera buildSigHtml() pour un rendu identique au changement d'expéditeur
    $default_sig_b64 = '';
    if ( $default_sig ) {
      $default_sig_b64 = base64_encode( wp_json_encode( $default_sig ) );
    }
    $default_sig_content = ''; // L'éditeur démarre vide — la signature est injectée par JS

    // Variables disponibles selon le type d'entité — pour le picker dans la toolbar
    $entity_var_groups = $this->get_direct_email_variables( $entity_type );
    $entity_var_json   = wp_json_encode( $entity_var_groups );
    ?><div class="acdc-modal-shell" id="<?php echo esc_attr( $modal_id ); ?>" hidden role="dialog" aria-modal="true" aria-label="Envoyer un e-mail">
      <div class="acdc-modal-backdrop" data-acdc-modal-close></div>
