                <td style="padding:8px 18px 8px 0;">
                  <?php if ( ! empty( $sig_list ) ) : ?>
                  <select name="signature_id" id="acdc-sig-select-<?php echo esc_attr( $entity_type . '-' . $entity_id ); ?>" style="height:36px;border:1px solid var(--acdc-border);border-radius:8px;padding:0 10px;font-size:13px;width:100%;max-width:360px;">
                    <?php foreach ( $sig_list as $sig ) : ?>
                    <option value="<?php echo esc_attr( $sig['id'] ); ?>" <?php selected( ! empty( $sig['is_default'] ) ); ?>><?php echo esc_html( $sig['display_name'] . ' <' . $sig['email'] . '>' ); ?></option>
