                  <span style="font-size:13px;color:var(--acdc-text-muted);">Aucune signature &mdash; <a href="<?php echo esc_url( $this->portal_page_url( array( 'tab' => 'marketing_signatures' ) ) ); ?>">cr&eacute;er une signature</a></span>
                  <?php endif; ?>
