            <div style="padding:14px 18px;min-height:200px;" id="acdc-editor-wrap-<?php echo esc_attr( $entity_type . '-' . $entity_id ); ?>" data-sig-b64="<?php echo esc_attr( $default_sig_b64 ); ?>">
              <?php echo $this->render_acdc_rich_editor( 'body_html', '', array( 'profile' => 'mail', 'min_height' => 200, 'placeholder' => 'Rédigez votre message ici...', 'variables_json' => $entity_var_json ) ); ?>
            </div>
            <script>
            (function(){
              var modalId = '<?php echo esc_js( $modal_id ); ?>';
              var editorWrapId = 'acdc-editor-wrap-<?php echo esc_js( $entity_type . '-' . $entity_id ); ?>';
              function injectSig() {
                var wrap = document.getElementById(editorWrapId);
                if (!wrap) return;
                var b64 = wrap.getAttribute('data-sig-b64');
                if (!b64) return;
                var editorEl = wrap.querySelector('[data-acdc-rich-content]');
                var textarea = wrap.querySelector('[data-acdc-rich-input]');
                if (!editorEl || editorEl.innerHTML.trim() !== '') return; // ne pas écraser si déjà rempli
                try {
                  var json = decodeURIComponent(escape(atob(b64)));
                  var sig = JSON.parse(json);
                  // buildSigHtml exposé via window par le bloc script suivant (même rendu qu'au changement)
                  var buildFn = window['acdcBuildSig_<?php echo esc_js( $entity_type . '_' . $entity_id ); ?>'];
                  var sigHtml = (typeof buildFn === 'function') ? buildFn(sig) : '';
                  if (!sigHtml) return;
                  var html = '<p><br></p><div data-acdc-signature="1">' + sigHtml + '</div>';
                  editorEl.innerHTML = html;
                  if (textarea) textarea.value = html;
                } catch(e) { return; }
              }
              // Observer l'ouverture de la modale (attribut hidden -> false)
              var modal = document.getElementById(modalId);
              if (modal) {
                var obs = new MutationObserver(function(muts) {
                  muts.forEach(function(m) {
                    if (m.attributeName === 'hidden' && !modal.hidden) {
                      setTimeout(injectSig, 80); // laisser l'éditeur JS s'initialiser
                    }
                  });
                });
                obs.observe(modal, { attributes: true });
              }
            })();
            </script>
            <div style="padding:10px 18px;border-top:1px solid var(--acdc-border);background:var(--acdc-bg);">
              <label style="font-size:12px;font-weight:600;color:var(--acdc-text-muted);display:block;margin-bottom:6px;">&#x1F4CE; Pièces jointes</label>
              <input type="file" name="attachments[]" multiple accept=".pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.jpg,.jpeg,.png,.zip" style="font-size:13px;color:var(--acdc-text-muted);">
              <p style="margin:4px 0 0;font-size:11px;color:var(--acdc-text-muted);">PDF, Word, Excel, images — 10 Mo max par fichier</p>
            </div>
            <div style="padding:14px 18px;display:flex;justify-content:flex-end;align-items:center;gap:10px;border-top:1px solid var(--acdc-border);background:#fff;position:sticky;bottom:0;">
              <span id="acdc-email-status-<?php echo esc_attr( $entity_type . '-' . $entity_id ); ?>" style="font-size:13px;color:var(--acdc-text-muted);display:none;"></span>
              <button type="button" class="acdc-button acdc-button-soft" data-acdc-modal-close>Annuler</button>
              <button type="button" class="acdc-button acdc-button-primary" id="acdc-email-send-<?php echo esc_attr( $entity_type . '-' . $entity_id ); ?>">&#x2709; Envoyer</button>
            </div>
          </form>
          <script>
          (function(){
            var formId    = 'acdc-direct-email-form-<?php echo esc_js( $entity_type . '-' . $entity_id ); ?>';
            var btnId     = 'acdc-email-send-<?php echo esc_js( $entity_type . '-' . $entity_id ); ?>';
            var statusId  = 'acdc-email-status-<?php echo esc_js( $entity_type . '-' . $entity_id ); ?>';
            var ajaxUrl   = '<?php echo esc_js( admin_url( 'admin-ajax.php' ) ); ?>';
            var btn = document.getElementById(btnId);
            if (!btn) return;
            btn.addEventListener('click', function() {
              var form = document.getElementById(formId);
              if (!form) return;
              var statusEl = document.getElementById(statusId);
              btn.disabled = true;
              btn.textContent = 'Envoi...';
              if (statusEl) { statusEl.style.display = 'none'; statusEl.textContent = ''; }
              var data = new FormData(form);
              fetch(ajaxUrl, { method: 'POST', body: data, credentials: 'same-origin' })
                .then(function(r) { return r.json(); })
                .then(function(json) {
                  if (json.success && json.data && json.data.redirect) {
                    window.location.href = json.data.redirect;
                  } else {
                    var msg = (json.data && json.data.message) ? json.data.message : 'Erreur inconnue.';
                    if (statusEl) { statusEl.style.display = 'inline'; statusEl.style.color = '#c62828'; statusEl.textContent = msg; }
                    btn.disabled = false;
                    btn.innerHTML = '&#x2709; Envoyer';
                  }
                })
                .catch(function() {
                  if (statusEl) { statusEl.style.display = 'inline'; statusEl.style.color = '#c62828'; statusEl.textContent = 'Erreur réseau. Réessayez.'; }
                  btn.disabled = false;
                  btn.innerHTML = '&#x2709; Envoyer';
                });
            });
          })();
          </script>
        </div>
      </div>
    </div>
    <?php if ( ! empty( $sig_list ) ) : ?>
    <script>
    (function(){
      var sigData = <?php echo wp_json_encode( array_values( $sig_list ) ); ?>;
      var selectEl = document.getElementById('acdc-sig-select-<?php echo esc_js( $entity_type . '-' . $entity_id ); ?>');
      if (!selectEl) return;
      function buildSigHtml(sig) {
        var h = '<table cellpadding="0" cellspacing="0" border="0" style="font-family:Arial,sans-serif;font-size:14px;color:#222;max-width:520px;"><tr>';
        if (sig.photo_url) h += '<td style="vertical-align:top;padding-right:18px;"><img src="'+sig.photo_url+'" width="90" height="90" style="width:90px;height:90px;object-fit:cover;border-radius:6px;"></td>';
        h += '<td style="vertical-align:top;">';
        h += '<p style="margin:0 0 2px;font-size:15px;font-weight:700;color:#0f2c52;">'+(sig.display_name||'')+'</p>';
        if (sig.job_title) h += '<p style="margin:0 0 6px;font-size:13px;color:#4b5d76;">'+sig.job_title+'</p>';
        if (sig.company_name) h += '<p style="margin:0 0 8px;font-size:13px;font-weight:700;color:#d6a353;">'+sig.company_name+'</p>';
        h += '<div style="border-top:1px solid #ddd;margin:8px 0;"></div>';
        if (sig.address) h += '<p style="margin:0 0 4px;font-size:12px;color:#555;">'+sig.address+'</p>';
        if (sig.phone) h += '<p style="margin:0 0 4px;font-size:12px;">'+sig.phone+'</p>';
        if (sig.email) h += '<p style="margin:0 0 8px;font-size:12px;">'+sig.email+'</p>';
        h += '</td></tr></table>';
        return h;
      }
      // Exposer buildSigHtml pour injectSig (bloc précédent) — même rendu à l'init et au changement
      window['acdcBuildSig_<?php echo esc_js( $entity_type . '_' . $entity_id ); ?>'] = buildSigHtml;
      selectEl.addEventListener('change', function() {
        var id = this.value, sig = null;
        for (var i=0;i<sigData.length;i++) { if (sigData[i].id===id) { sig=sigData[i]; break; } }
        if (!sig) return;
        var modal = document.getElementById('<?php echo esc_js( $modal_id ); ?>');
        if (!modal) return;
        var editor = modal.querySelector('[data-acdc-rich-content]');
        var textarea = modal.querySelector('[data-acdc-rich-input]');
        if (!editor) return;
        var newSigNode = '<div data-acdc-signature="1">' + buildSigHtml(sig) + '</div>';
        var existing = editor.querySelector('[data-acdc-signature]');
        if (existing) {
          existing.outerHTML = newSigNode;
        } else {
          editor.innerHTML += '<p><br></p>' + newSigNode;
        }
        if (textarea) { textarea.value = editor.innerHTML; }
      });
    })();
    </script>
    <?php endif; ?>
    <?php
  }

}
